window.PF_CAT_SCHOLARSHIPS=[{"i":"600627001_general_scholarship","n":"General Scholarship","o":"600627001","about":"Our scholarships are kindly donated by local organisations and trusts. Some recognise academic excellence or academic challenges. Others are designed to help meet skills shortages in specific industries, or to simply encourage you on your study journey. Each scholarship has a set of eligibility criteria. If you meet the criteria, and the scholarship is open for applications, we encourage you to apply for it.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Close","url":"https://www.ara.ac.nz/student-services/supporting-your-study/scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Some recognise academic excellence or academic challenges"},"rounds":[]},{"i":"700277001_international_students_scholarships_faqs","n":"International students: scholarships FAQs","o":"700277001","about":"Scholarship questions answered: real questions from Waikato's international students. A list of frequently asked questions (FAQs) from international students applying for scholarships at the University of Waikato.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"","url":"https://www.waikato.ac.nz/study/scholarships/international-scholarships-faqs/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700277001_external_funding_opportunities","n":"External funding opportunities","o":"700277001","about":"Learn about external scholarships and funding opportunities offered by government, private, and community organisations to support your study at Waikato. Beyond the scholarships in ourScholarships Finder, many funding opportunities are offered through other organisations. Please note – the below list is not curated on a regular basis and closing dates / values may alter each year. Be sure to check the details provided by each organisation and contact the external organisations directly for any questions.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.waikato.ac.nz/study/scholarships/external-funding/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_cat_paus_postgraduate_scholarship","n":"Cat Pausé Postgraduate Scholarship","o":"700311001","about":"Dr Caitlin (Cat) Pausé was a senior lecturer at Massey University from 2008 until her death in March 2022. Cat’s academic focus was on the impact of fat stigma on the health and well-being of fat people. She published on coming out as fat, the barriers to health for fat people, and the role of social media in fat activism and scholarship. At Massey, Cat was well-liked and respected by staff and students and is remembered for her generosity, humility and caring. Cat was a strong believer in education and professional development and was known to occasionally sponsor students out of her own pocket to travel to professional seminars and conferences. This scholarship fund was founded by Cat’s parents Paul and Megan Pausé who want this scholarship to benefit numerous generations of students at ","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$7,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"28 January 2027","closing":"1 April 2027","entry":"Applications open 28 January 2027 and close 1 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/cat-pause-postgraduate-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Cat’s academic focus was on the impact of fat stigma on the health and well-being of fat people"},"rounds":[]},{"i":"700800001_fee_refunds","n":"Fee refunds","o":"700800001","about":"You may be entitled to a refund if you change your programme of study, withdraw from your programme or transfer to another institution. If you haven't paid your fees yet and need to change your application to study at AUT, you still need to withdraw from your programme as you will remain liable for your fees. The following information is a guide. To see our full fees and refunds protocol refer to the AUT Calendar section on Payment and Refund of Fees. Payment and Refund of Fees (AUT Calendar)","levels":["General"],"values":[{"condition":"Academic merit / GPA requirements","value":"$300"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.aut.ac.nz/study/fees-and-scholarships/fee-refunds","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":[],"other":"Change of application Enrolment status Refund Admin charge Result recorded Completed less than 10% of course duration Cancelled 100% Nil No result recorded Completed between 10% and 75% of course duration Withdrawal Nil Nil Withdrawn result recorded After 75% of course  duration completed Withdrawal Nil Nil Did not complete result recorded If you have not yet paid your fees If you have enrolled in a programme of study but have not yet paid your fees, you will remain liable for your fees unless you withdraw before the end of the refund period outlined above"},"rounds":[]},{"i":"601290001_financial_assistance","n":"Financial Assistance","o":"601290001","about":"Financial assistance may be available for learners who are facing unexpected financial hardship that is impacting their studies.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.northtec.ac.nz/portal/financial-assistance","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"601915001_scholarships","n":"Scholarships","o":"601915001","about":"At Wintec, we know that being awarded a scholarship could make all the difference in pursuing further study. Whether you’re an adult learner or from an ethnic background, experiencing financial hardship, or undertaking postgraduate study, we have you covered with our wide range of scholarships available. Many different types are on offer. Find the scholarships that could be right for you. Find what you're looking for in our frequently asked questions.","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.wintec.ac.nz/student-resources/support-services/scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700800001_fees_for_aut_student_accommodation","n":"Fees for AUT student accommodation","o":"700800001","about":"Everything you need to know about the cost of living at AUT's student accommodation in Auckland, New Zealand – fees cover your full semester or year, with internet and power included at both Te Āhuru Mayoral Drive Student Accommodation and Akoranga Student Village. Right in the heart of Auckland city, Te Āhuru Mayoral Drive Student Accommodation puts you one minute from AUT City Campus. Here's what it costs for 2026. Te Ahuru Mayoral Drive Student Accommodation info","levels":["General"],"values":[{"condition":"NoCondition","value":"$9,540"},{"condition":"Domestic students","value":"$349"}],"lengths":[{"condition":"NoCondition","length":"One Semester"},{"condition":"Domestic students","length":"One Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Our online application portals open at set times each year. Don't leave it too late – rooms go fast.","url":"https://www.aut.ac.nz/study/fees-and-scholarships/acommodation-fees","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_doctor_of_computing_and_master_of_applied_technology_computing_scholar","n":"Doctor of Computing and Master of Applied Technology (Computing) Scholarships.","o":"600449001","about":"These scholarships are available to support talented students enrolled in the Doctor of Computing and Master of Applied Technology (Computing) at Unitec. Please read theMasters Scholarship Guidelinesfor full details and eligibility criteria. The scholarship is open to both Domestic and International students.","levels":["Masters","PhD / Doctorate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"2026 Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Application and fundingScholarships and AwardsHow to applyAcademic CalendarAdmission requirementsDo your apprenticeship with usFeesFunding your studyChange Enrolment","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/master-of-applied-technology-computing-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"These scholarships are available to support talented students enrolled in the Doctor of Computing and Master of Applied Technology (Computing) at Unitec"},"rounds":[]},{"i":"700311001_massey_university_doctoral_scholarship","n":"Massey University Doctoral Scholarship","o":"700311001","about":"The award of the scholarship focuses on the academic excellence of the student, without limiting the selection to GPA, as well as ensuring that decisions are made in line with the University, College, and School research strategies. The Massey University Doctoral Scholarship acknowledges the unique contribution that Māori and Pacific students make to academic research. Massey is committed to promoting equity of access to learning, teaching, and research. The expectation is that recipients of the Doctoral Scholarship will enrol in their doctoral study no later than 1 March of the year following selection. The Massey University Doctoral Scholarship is available to full-time and part-time candidates enrolled in the Doctor of Philosophy (PhD), Doctor of Clinical Psychology (DClinPsych) or Doct","levels":["PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$90,000"}],"lengths":[{"condition":"NoCondition","length":"Three Years"}],"opening":"1 August 2026","closing":"1 October 2026","entry":"Applications open 1 August 2026 and close 1 October 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-doctoral-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"The award of the scholarship focuses on the academic excellence of the student, without limiting the selection to GPA, as well as ensuring that decisions are made in line with the University, College, and School research strategies"},"rounds":[]},{"i":"700311001_nursing_bursary_for_postgraduate_study","n":"Nursing Bursary for Postgraduate Study","o":"700311001","about":"The Nursing Bursary for Postgraduate Study supports newly graduated registered nurses and registered nurses to undertake postgraduate study alongside work by reducing financial barriers. You will be a Registered Nurse working in the NZ Health and Disability sector and interested in undertaking postgraduate study. This is a postgraduate bursary, you will be enrolled or intending to enrol in course168.733 Physiology & Pathophysiology.","levels":["Diploma","Postgraduate"],"values":[{"condition":"NoCondition","value":"$500"}],"lengths":[{"condition":"NoCondition","length":"One Semester"}],"opening":"8 May 2026","closing":"31 July 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/nursing-bursary-for-postgraduate-study/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_kate_edger_foundation_nz_contemporary_art_award","n":"Kate Edger Foundation – NZ Contemporary Art Award","o":"600449001","about":"The Award is available for a student who will be enrolled in 2026 in the third year or above of a degree or post-graduate degree in an Arts-related area at a NZQA-accredited tertiary institute in the Auckland or Northland region. The Kate Edger Foundation is pleased to announce, in conjunction with the NZ Contemporary Art Trust, that applications for the 2026 NZ Contemporary Art Award are now open. The Award is intended to foster greater understanding of and engagement with contemporary art in New Zealand and to encourage awareness of the benefits of art to society. a New Zealand Citizen or Permanent Resident","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"},{"condition":"Academic merit / GPA requirements","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/kate-edger-foundation-nz-contemporary-art-award/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"The Award is available for a student who will be enrolled in 2026 in the third year or above of a degree or post-graduate degree in an Arts-related area at a NZQA-accredited tertiary institute in the Auckland or Northland region"},"rounds":[]},{"i":"600449001_master_of_applied_business_mab_and_master_of_professional_accounting_m","n":"Master of Applied Business (MAB) and Master of Professional Accounting (MPA) Scholarships","o":"600449001","about":"Support equity goals for Māori and Pacific students by incentivizing their participation and completion on the Master of Applied Business (MAB) and Master of Professional Accounting (MPA) programmes. To encourage Māori and Pacific students who are motivated to make a positive difference in their community to undertake the Master of Applied Business (MAB) or Master of Professional Accounting (MPA). Māori and Pacific students that have received an offer for the Master of Applied Business (MAB) and Master of Professional Accounting (MPA) programmes and who demonstrate motivation to support their community, ideally with a research project in mind.","levels":["Masters"],"values":[{"condition":"NoCondition","value":"$1,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"22 February 2026","entry":"Application and fundingScholarships and AwardsHow to applyAcademic CalendarAdmission requirementsDo your apprenticeship with usFeesFunding your studyChange Enrolment","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/master-of-applied-business-mab-and-master-of-professional-accounting-mpa-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_professor_ren_jizhou_scholarship","n":"Professor Ren Jizhou Scholarship","o":"700311001","about":"This scholarship is supported by funds accumulated under the Gansu Grassland Ecological Research Institute (China) component of the Trade for Training Scheme. The scholarship was set up by Associate Professor Alex Chu in recognition of the contribution made by Professor Ren Jizhou, foundation director of the institute, in promoting the Trade for Training Scheme in China. Professor Ren is also the leading advocate of pastoral farming in China. We're looking for a Chinese student studying agriculture or horticulture at undergraduate or postgraduate level. We're also looking for a New Zealand citizen based in the College of Sciences who is interested in visiting China to engage in work of value to New Zealand agriculture or horticulture. This is an undergraduate or postgraduate scholarship. Y","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/professor-ren-jizhou-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be: studying a specific subject either a New Zealand citizen or a Chinese student"},"rounds":[]},{"i":"700311001_john_mcarthur_geography_research_scholarship","n":"John McArthur Geography Research Scholarship","o":"700311001","about":"John McArthur was born in Nelson in 1941. He completed a Bachelor of Arts in Geography at the University of Canterbury in 1961, before gaining his Teacher’s Certificate in 1962. He gained a university blue in yachting and played senior representative basketball for Canterbury B. John taught at Akaroa District High School before returning to Canterbury to complete a Master of Arts in 1964. In 1966 he began a PhD at the University of Sheffield which he completed before returning to New Zealand in 1970 to take-up a position in the Geography Department at Massey University, Palmerston North where he remained until his retirement in 1997. John died in 2021 and left a bequest to be used to support research at Massey University. Applicants will be enrolled in, or intending to enrol in, a master's","levels":["Diploma","Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$13,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"15 January 2027","entry":"Applications open 1 December 2026 and close 15 January 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/john-mcarthur-geography-research-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants will be enrolled in, or intending to enrol in, a master's degree with a 60, 90, or 120 credit research course"},"rounds":[]},{"i":"700277001_scholarship_information_for_school_leavers","n":"Scholarship information for school leavers","o":"700277001","about":"The University of Waikato offers more than 20 scholarships for school leavers. Awards cover tuition fees, accommodation and living costs. Applications open April and close 31 August. Starting university is a big step and scholarships can make it easier. The University of Waikato offers more than 20 scholarships for students entering university directly from school. Whether you're academically driven, a community leader, a sportsperson, or connected to Māori or Pacific communities, there's likely a scholarship for you.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.waikato.ac.nz/int/study/scholarships/school-leaver-scholarship-information/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":["Māori"],"other":"Whether you're academically driven, a community leader, a sportsperson, or connected to Māori or Pacific communities, there's likely a scholarship for you"},"rounds":[]},{"i":"700311001_massey_university_doctoral_conference_grants","n":"Massey University Doctoral Conference Grants","o":"700311001","about":"The Massey University Doctoral Conference Grants offer financial support for doctoral students to present their research at conferences in their discipline. The grant should be used at your discretion to assist with conference registration costs, travel, accommodation, or any other presentation costs incurred. Applications are considered on a rolling basis throughout the year until funds are exhausted. Selection will occur at the start of each month for applications received in the previous month. Your presentation should be accepted prior to submission of the grant application. Please ensure you allow sufficient time for the grant to be considered by the selection panel.","levels":["PhD / Doctorate"],"values":[{"condition":"NoCondition","value":"$2,000"},{"condition":"International students","value":"$1,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"1 January 2026","closing":"31 October 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-doctoral-conference-grants/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"a full academic CV, listing any previous publications and conference presentations"},"rounds":[]},{"i":"600449001_unitec_pacific_success_scholarships","n":"Unitec Pacific Success Scholarships","o":"600449001","about":"The purpose of this scholarship, established in 2017, is to encourage Pacific students thinking about studying at Unitec for the first time, to pursue their goals and study with Unitec. The scholarship is open to domestic Pacific students in level 3 to 8 programmes that take at least one semester of full-time study to complete. Unitec recognises that financial support is an important consideration for ākonga considering study. The scholarship provides both financial support and mentoring opportunities in the first semester of study.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"Domestic students","length":"One Semester"},{"condition":"NoCondition","length":"One Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Complete the online application form. Support is available for ākonga through our Careers Team and Scholarships Team. Please book an appointment early and prior to the application deadline if you would like to discuss or seek support with your application:https://guides.unitec.ac.nz/scholarships","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/unitec-pacific-success-scholarships/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori","Pacific Islands"],"other":"Academic progress : Ākonga who are awarded the scholarship are expected to achieve Pass grades for all courses, unless exceptional circumstances prevail"},"rounds":[]},{"i":"700800001_manaaki_new_zealand_scholarships","n":"Manaaki New Zealand Scholarships","o":"700800001","about":"AUT hosts a large number of scholars under the Manaaki New Zealand Scholarships Programme each year. Offered by New Zealand’s Ministry of Foreign Affairs and Trade (MFAT), the scholarships enable international students from selected developing countries to study at a New Zealand university and enhance their skills to contribute to the sustainable development of their home country. Frequently asked questions about Manaaki NZ Scholarships","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"13 March 2026","entry":"These are full tertiary scholarships for undergraduate and postgraduate academic study in New Zealand available to eligible international students from ASEAN and Pacific regions. Priority is given to applicants who choose one of the recommended subjects specified by the Ministry of Foreign Affairs and Trade.","url":"https://www.aut.ac.nz/study/fees-and-scholarships/scholarships-and-awards-at-aut/manaaki-new-zealand-government-scholarships","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"Applying for a Manaaki New Zealand Scholarship These are full tertiary scholarships for undergraduate and postgraduate academic study in New Zealand available to eligible international students from ASEAN and Pacific regions"},"rounds":[]},{"i":"700311001_k_a_north_scholarship","n":"K A North Scholarship","o":"700311001","about":"Mr Kenneth Arnold North was the founding principal of Palmerston North Teachers College, which was first established in 1956. Mr North bequest an endowment to the Teachers College at Palmerston North to provide financial assistance to students of the former Palmerston North Teachers College to undertake a course of study in New Zealand. This scholarship is named in his honour. We're looking for a fully registered teacher and who is advancing their education to achieve their career goals and who is passionate about contributing to giving back upon graduation. This is a postgraduate scholarship. You will be enrolled in a minimum of 30 credits per semester and be intending to complete your qualification in the year of the award.","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"14 May 2026","closing":"14 August 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/k-a-north-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a minimum of 30 credits per semester and be intending to complete your qualification in the year of the award"},"rounds":[]},{"i":"700311001_harry_tolley_and_l_j_wild_scholarship","n":"Harry Tolley and L J Wild Scholarship","o":"700311001","about":"This scholarship arises from money provided by Merle Palmer Elliot and Joyce Marion Boyce in memory of their father, Harry Tolley of Hodder and Tolley Limited, and Dr L. J. Wild, founding Headmaster of Feilding Agricultural High School. In 2022 Rosemary and Grahame Bolton donated additional funds to increase the value of the scholarship. Rosemary Bolton is the daughter of one of the original benefactors, Merle Elliot, and the granddaughter of Harry Tolley. Preference will be given to former pupils of Feilding High School. You will have completed at least 120 credits towards a Bachelor of Agricultural Science, a Bachelor of Horticultural and Plant Systems, or a Bachelor of Agribusiness and be enrolled full time in the year of award. Applicants must be domiciled in New Zealand.","levels":["Masters","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/harry-tolley-and-l-j-wild-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must be domiciled in New Zealand"},"rounds":[]},{"i":"600737001_viticulture_wine_science","n":"Viticulture & Wine Science","o":"600737001","about":"For more information on any of the below scholarships please contact the School of Viticulture and Wine Science on 06 830 1913 or emailjrolfe@eit.ac.nz Contact:For interested scholars details of these grants are available atBragato Trust | New Zealand Wine (nzwine.com) The Hawke’s Bay A & P Society Young Vintner’s Award was established in 2002.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$15,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"Open all year","closing":"23 March 2026","entry":"Refer to eligibility criteria.","url":"https://www.eit.ac.nz/students/scholarships/vit-and-wine-science/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"This scholarship is open to first and third year students enrolled in the Bachelor of Viticulture and Wine Science degree"},"rounds":[]},{"i":"700311001_phd_masters_scholarship_opportunity_mori_business_workplace_equity_and","n":"PhD / Master's scholarship opportunity: Māori business, workplace equity and social mobility","o":"700311001","about":"PhD or Master's scholarship opportunity: Māori business, workplace equity and social mobility A funded PhD or Master's opportunity is available to contribute to a Kaupapa Māori qualitative research stream within a wider project on occupational mobility and equal opportunity in Aotearoa New Zealand. The student will work with Professor Matthew Roskruge and Māori research partners to examine how Māori businesses and Māori business leaders understand and respond to barriers and enablers to social and occupational mobility. The project may involve interviews, wānanga, case studies and organisational analysis, with a focus on Māori values, leadership, workplace practices and pathways to more equitable outcomes. This opportunity would suit a student interested in Māori business, Māori economic d","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$35,000"}],"lengths":[{"condition":"NoCondition","length":"3 Years"}],"opening":"20 May 2026","closing":"31 July 2026","entry":"Contact us","url":"https://www.massey.ac.nz/study/scholarships-and-awards/phd-scholarship-opportunity-m%C4%81ori-business-workplace-equity-and-social-mobility/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori","Indigenous"],"other":"Applicants must be already enrolled in Semester 1 of 2026 but are able to pivot to this topic, or able to enrol in Semester 2 of 2026"},"rounds":[]},{"i":"700311001_freemasons_university_scholarship","n":"Freemasons University Scholarship","o":"700311001","about":"These scholarships are funded by the Freemasons of New Zealand. We're looking for students who give back to their communities. This is an undergraduate or postgraduate scholarship. You can be enrolled in any subject.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$6,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 July 2026","closing":"1 October 2026","entry":"The Freemasons Charity","url":"https://www.massey.ac.nz/study/scholarships-and-awards/freemasons-university-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You can be enrolled in any subject"},"rounds":[]},{"i":"602257001_page_not_found","n":"Page not found","o":"602257001","about":"Some reasons why you are seeing this page may be: If you were trying to access our online services, and you couldn’t reach them, try the following: If you need help finding some information, please contact us onfreephone 0508 650 200.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.openpolytechnic.ac.nz/maori/scholarships-for-maori/contact-us","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_massey_university_postgraduate_scholarship_semester_one","n":"Massey University Postgraduate Scholarship - Semester One","o":"700311001","about":"The Massey University Postgraduate Scholarship developed from an ambition for Massey University postgraduate students to shape the future of New Zealand. In 2004, the postgraduate scholarships were developed and named in honour of Sir Alan Stewart KBE (8 December 1917 – 1 September 2004), the principal of Massey Agricultural College from 1959 to 1963 and founding vice-chancellor of Massey University from 1964 to 1983. Sir Alan guided the institution's transition from an agricultural college to full university. He is noted for building the university's internationally recognised agricultural programme, as well as for greatly expanding the university's distance programme to make tertiary education available to rural New Zealanders. In 1940, Stewart was awarded Massey's second Rhodes Scholars","levels":["PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Semester"}],"opening":"15 October 2026","closing":"15 January 2027","entry":"Applications open 15 October 2026 and close 15 January 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-postgraduate-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"When choosing our recipients, we will consider your academic achievements in your New Zealand based tertiary study record"},"rounds":[]},{"i":"700277001_te_ara_whnui_scholarship","n":"Te Ara Whānui Scholarship","o":"700277001","about":"Subject area(s)Arts, Business & Management, Computer Science, Mathematics, Education, Health, Engineering, Law, Māori & Indigenous Studies, Science, Social Sciences This Scholarship is available for all subject areas. Te Ara Whānui Scholarship recognises the importance the University of Waikato assigns to fostering, developing, and protecting excellence of Māori, and kapa haka, kaupapa Māori, tikanga, reo and/or mātauranga Māori.","levels":["General"],"values":[{"condition":"NoCondition","value":"$20,000"}],"lengths":[{"condition":"NoCondition","length":"Three Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Please ensure you readHow to apply for scholarships and awardsbefore you commence the application process.","url":"https://www.waikato.ac.nz/study/scholarships/find-a-scholarship/te-ara-whanui-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori","Indigenous"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600737001_nursing_health_sport_science","n":"Nursing, Health & Sport Science","o":"600737001","about":"For more information on any of the below scholarships please contact the School of Nursing on 06 830 1179 or emailNursing@eit.ac.nzor the School of Health and Sport Science on 06 830 1521 or emailSport@eit.ac.nz OverviewThe Sport Hawke’s Bay and EIT Sport Scholarship is designed to support student-athletes who are striving to maintain a balance between their academic studies and sporting commitments. This scholarship offers financial assistance to help ease the pressures of juggling both pursuits, enabling students to focus on achieving excellence in the classroom and on the field. This scholarship is awarded annually to three individuals—both new students about to begin their studies and current students returning to EIT Hawke’s Bay. Students who actively represent a sports team within th","levels":["Diploma","Masters","Undergraduate"],"values":[{"condition":"NoCondition","value":"$11,000"}],"lengths":[{"condition":"NoCondition","length":"18 Years"}],"opening":"6 July 2026","closing":"3 August 2026","entry":"STEP 1: RegisterStudents must register and create an account on the Perpetual Guardian Funding Hub to view the application form and apply when applications open. Early registration is recommended.","url":"https://www.eit.ac.nz/students/scholarships/nursing-health-sport-science/","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":["Māori"],"other":"The Sport Hawke’s Bay and EIT Sport Scholarship is designed to support student-athletes who are striving to maintain a balance between their academic studies and sporting commitments"},"rounds":[]},{"i":"700122001_doctoral_scholarships_for_international_students","n":"Doctoral scholarships for international students","o":"700122001","about":"In 2026, the Scholarship provides a tax-free stipend of up to $35,468 pa, with an annual CPI adjustment to the stipend value, for up to 42 months of full-time study, plus tuition fees for international students who are eligible to study under thedomestic fees policy, and the single student Health Insurance compulsory charge. Students will be considered for a University of Auckland Doctoral Scholarship at the time of application for a place in their doctoral programme. Any student who is to be offered a place in a doctoral programme will be eligible for scholarship consideration prior to receiving their offer of place.","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"International students","value":"$40,000"},{"condition":"NoCondition","value":"$70,000"}],"lengths":[{"condition":"International students","length":"42 Months"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/scholarship-types/scholarships-for-international-students/doctoral-scholarships-for-international-students.html","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":[],"other":"International students must be a citizen of a member country of The Commonwealth"},"rounds":[]},{"i":"700311001_te_ara_whakamua_fund_the_path_forward","n":"Te Ara Whakamua Fund- The Path Forward","o":"700311001","about":"The Te Ara Whakamua Fund helps Māori students take part in placements, internships, professional wānanga, and student hui that build skills, connections, and confidence for the future.It’s here to reduce the financial pressure of travel, accommodation, kai, and other costs so you can focus on learning and growth. The Te Ara Whakamua Fund may be granted to assist with costs directly related to the approved activity, including but not limited to: Applications may be submitted at any time during the year but must be received at least two weeks prior to the commencement of the placement, internship, or hui.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$500"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/te-ara-whakamua-fund-the-path-forward/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":") Accommodation Kai and daily living costs during the placement, internship, or hui Registration or participation fees Equipment or resources essential to participation Applications may be submitted at any time during the year but must be received at least two weeks prior to the commencement of the placement, internship, or hui"},"rounds":[]},{"i":"700277001_funded_research_projects","n":"Funded Research Projects","o":"700277001","about":"Discover funded research projects at the University of Waikato, including research funding, research masters degrees, and scholarships across multiple disciplines. Explore current project vacancies, departmental scholarships, and other funded opportunities to support your postgraduate journey. Opportunities are updated regularly. Check back often and connect with academics in your field to stay informed.","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.waikato.ac.nz/study/scholarships/funded-research-projects/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Check back often and connect with academics in your field to stay informed"},"rounds":[]},{"i":"700311001_rewa_o_puanga_screen_arts_scholarship","n":"Rewa o Puanga Screen Arts Scholarship","o":"700311001","about":"The Rewa o Puanga Screen Arts Scholarship was established by Massey University to provide support to promising applicants in preparation for a career in the screen arts industries, specifically animation, factual production, film production, game development, immersive media, and visual effects. Typically, six scholarships are offered annually: You will be enrolling in the first year of the Bachelor of Screen Arts with Honours in the year following the scholarship application.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 June 2026","closing":"1 September 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/te-rewa-o-puanga-screen-arts-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must be: a New Zealand citizen or New Zealand resident"},"rounds":[]},{"i":"700311001_max_chapple_memorial_scholarship","n":"Max Chapple Memorial Scholarship","o":"700311001","about":"The Max Chapple Memorial Scholarship was established in memory of Max Honomai Chapple, who in 1995 completed a Bachelor of Arts with a major in history at Massey University. This is a postgraduate scholarship. You will want to or be studying and undertaking research in history, preferably New Zealand or Pacific Islands history. Include the following with your application:","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"25 January 2027","closing":"31 March 2027","entry":"Applications open 25 January 2027 and close 31 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/max-chapple-memorial-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Pacific Islands"],"other":"When choosing our recipients, we will consider your academic achievements, financial need and other scholarships or bursaries you hold"},"rounds":[]},{"i":"600449001_kate_edger_postgraduate_diploma_awards","n":"Kate Edger Postgraduate Diploma Awards","o":"600449001","about":"To assist women graduates to undertake a Postgraduate Diploma full time at an approved Institute in the Auckland area. Applicants for the Postgraduate Diploma Awards must be: a) womenb) New Zealand Citizens or Permanent Residents;c) enrolled or planning to enrol full time for a Postgraduate Diploma, for the following academic year, at an approved institute in the Auckland region","levels":["Diploma","Postgraduate"],"values":[{"condition":"NoCondition","value":"$8,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"18 November 2024","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/kate-edger-postgraduate-diploma-awards/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Applicants for the Postgraduate Diploma Awards must be:"},"rounds":[]},{"i":"700800001_doctoral_scholarships","n":"Doctoral scholarships","o":"700800001","about":"Our PhD students are at the heart of AUT’s research culture. To attract and recognise highly achieving research students and stimulate doctoral research in areas that enhance AUT’s capability, AUT offers a number of doctoral scholarships. To qualify for a doctoral scholarship, you must have gained admission into an approved doctoral programme at AUT before applying for the scholarship. Doctoral scholarships are awarded to applicants with an excellent academic record (normally first-class honours), strong academic references and the potential for high-quality research.","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$34,737"},{"condition":"Domestic students","value":"$34,737"}],"lengths":[{"condition":"NoCondition","length":"Three Years"},{"condition":"Domestic students","length":"Three Months"}],"opening":"Open all year","closing":"Refer to website","entry":"Doctoral scholarships are awarded to applicants with an excellent academic record (normally first-class honours), strong academic references and the potential for high-quality research.","url":"https://www.aut.ac.nz/study/fees-and-scholarships/scholarships-and-awards-at-aut/doctoral-scholarships","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori","Pacific Islands"],"other":"2026 AUT doctoral scholarships you can apply for Doctoral scholarships are awarded to applicants with an excellent academic record (normally first-class honours), strong academic references and the potential for high-quality research"},"rounds":[]},{"i":"700311001_joe_walding_memorial_bursary","n":"Joe Walding Memorial Bursary","o":"700311001","about":"The bursary was established in memory of the late Honourable J A Walding, Member of Parliament for Palmerston North, Minister of Overseas Trade and New Zealand High Commissioner in London. We're looking for a postgraduate or doctoral business student based in the Manawatu, Whanganui, or Wellington region. Include the following with your application:","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"31 January 2027","closing":"30 April 2027","entry":"Applications open 31 January 2027 and close 30 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/joe-walding-memorial-bursary/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"When choosing our recipient, we will consider your academic achievements"},"rounds":[]},{"i":"700311001_whangarei_maungatapere_veterinary_clubs_charitable_trust","n":"Whangarei Maungatapere Veterinary Clubs Charitable Trust","o":"700311001","about":"Whangarei Maungatapere Veterinary Clubs Charitable Trust 2025 Scholarship/s The above Trust has a long and successful history of supporting veterinary students and researchers in their aspirations to make a positive difference for Te Tai Tokerau","levels":["General"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"3 February 2027","closing":"10 March 2027","entry":"Applications open 3 February 2027 and close 10 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/whangarei-maungatapere-veterinary-clubs-charitable-trust/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"The applicant must be from Northland or be Northland based"},"rounds":[]},{"i":"600449001_rider_levett_bucknall_professional_quantity_surveyor_of_the_year_schol","n":"Rider Levett Bucknall Professional Quantity Surveyor of the Year Scholarship","o":"600449001","about":"The purpose of this scholarship is to provide financial support and work experience to a Building and Construction student majoring in Property Economics or Quantity Surveying. The work experience may continue for future years of study and upon graduation RLB may also make an offer of full-time employment. Rider Levett Bucknall (RLB) is a global independent construction, property and management consultancy, with a team of 500 people across Australia and New Zealand. Please visitwww.rlb.comfor further information about Rider Levett Bucknall.","levels":["General"],"values":[{"condition":"NoCondition","value":"$7,500"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"13 June 2025","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/rider-levett-bucknall-professional-quantity-surveyor-of-the-year-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Academic success as demonstrated in course results to date (please provide copies with application)"},"rounds":[]},{"i":"700800001_paying_your_fees","n":"Paying your fees","o":"700800001","about":"Paying your fees doesn't have to be complicated. Get it sorted early and you can focus on what matters – your learning. Your fees are due in full by the date on your invoice. We don't offer payment plans, so paying on time means you won't miss out on your spot in class or your access to university services. Domestic students: you can pay your fees through","levels":["General"],"values":[{"condition":"Domestic students","value":"$12,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.aut.ac.nz/study/fees-and-scholarships/paying-your-fees","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_marcp_scholarships_for_innovation_and_industry_connections","n":"MARCP Scholarships for Innovation and Industry Connections","o":"600449001","about":"These Scholarships are available to support talented students enrolled in the Master of Architecture (Professional) at Unitec. Please refer to theMaster Scholarship Guidelinesfor details. The scholarship is open to both Domestic and International students.","levels":["Masters"],"values":[{"condition":"NoCondition","value":"$2,500"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"31 January 2025","entry":"Application and fundingScholarships and AwardsHow to applyAcademic CalendarAdmission requirementsDo your apprenticeship with usFeesFunding your studyChange Enrolment","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/marcp-scholarships-for-innovation-and-industry-connections/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"These Scholarships are available to support talented students enrolled in the Master of Architecture (Professional) at Unitec"},"rounds":[]},{"i":"600449001_whai_ake_mori_scholarship_teina","n":"Whai Ake Māori Scholarship – Teina","o":"600449001","about":"The Whai Ake mentoring programme aims to provide a strong support system for Māori students who are new to tertiary education. Whai Ake is about growing Māori student leadership capability, increasing first-year completions, and lifting Māori student academic success and retention overall in tertiary study. The scholarship is designed to support Whai Ake tauira to engage with their culture throughout their journey at Te Whare Wānanga o Wairaka. This scholarship also provides financial support for education-related costs. We want all tauira Māori who are new to tertiary education or new to Unitec to apply along with tauira who have studied with Unitec in the past.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/whai-ake-maori-scholarship-teina/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori"],"other":"Whai Ake is about growing Māori student leadership capability, increasing first-year completions, and lifting Māori student academic success and retention overall in tertiary study"},"rounds":[]},{"i":"601915001_general_scholarship","n":"General Scholarship","o":"601915001","about":"Mikayla brings energy, excellence, and empathy to everything she does. A top student two years running, she balances study with being a single mum, carer, and part-time worker—always showing up with a smile and a solution-focused mindset. Her leadership as Agency Director and student rep reflects her generosity in sharing knowledge and uplifting others. Mikayla embraces new challenges, from volunteering at arts festivals to featuring in regional campaigns, all while excelling academically. Her drive to grow, support her peers, and give back to the community makes her a standout learner and a future asset to the creative communications industry. Danielle, known as Danni, is a passionate and dedicated learner whose journey through the Bachelor of Teaching (ECE) has been marked by excellence ","levels":["Diploma","Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"Two Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.wintec.ac.nz/student-resources/support-services/scholarships/ala-nominees/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":["Māori","Pasifika","Pacific Islands"],"other":"Mikayla embraces new challenges, from volunteering at arts festivals to featuring in regional campaigns, all while excelling academically"},"rounds":[]},{"i":"600449001_te_pou_angit","n":"Te Pou Angitū","o":"600449001","about":"Te Pou Angitū were established in 2019 to encourage Māori students thinking about studying at Unitec for the first time, to pursue their goals and study with Unitec. Tauira who have not enrolled at Unitec before and are starting in an undergraduate certificate, diploma, or degree or in a postgraduate certificate or diploma, are encouraged to apply. Unitec recognises that financial support is an important consideration for ākonga/learners considering study. The scholarship provides both financial support and mentoring opportunities in the first year of study.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Complete the online application. Support is available for ākonga through our Careers Team or Scholarships Team. Please book an appointment early and prior to the application deadline if you would like to discuss or seek support with your application:https://guides.unitec.ac.nz/scholarships","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/te-pou-angitu/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori","Pacific Islands"],"other":"Academic progress : Ākonga who are awarded the scholarship are expected to achieve Pass grades for all courses, unless exceptional circumstances prevail"},"rounds":[]},{"i":"700311001_massey_university_pacific_postgraduate_scholarship","n":"Massey University Pacific Postgraduate Scholarship","o":"700311001","about":"This scholarship provides support for Pacific students intending to enrol in postgraduate studies at Massey in the year following the selection of the award. We're looking for Pacific students planning on studying a postgraduate qualification in the following year. You will demonstrate good character and community participation. You must be a domestic student from Pacific heritage/ethnicity","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$4,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 November 2026","closing":"1 February 2027","entry":"Applications open 1 November 2026 and close 1 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-pacific-postgraduate-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You must be a domestic student from Pacific heritage/ethnicity"},"rounds":[]},{"i":"600737001_mori_pasifika","n":"Māori & Pasifika","o":"600737001","about":"There is a wide range of undergraduate and postgraduate scholarships and awards available to Māori and Pasifika students who are studying at EIT. He karanga tēnei ki ngā rangatahi kia hui mai ki runga o Te Tairawhiti ki Toihoukura, ko Te Kupenga tēnei te hao nei i a tiki matua. This year as part of celebrating our rangatahi, Toihoukura are offering two scholarships to Year 12 or Year 13 students who have been accepted into Te Toi o Ngā Rangi | Bachelor of Māori Visual Arts. (This is a three year programme).","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"Targeted ethnicity criteria","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"Three Year"}],"opening":"October 20, 2022","closing":"6 July 2026","entry":"Applications must be received by11:59pm on Sunday 4 October 2026.","url":"https://www.eit.ac.nz/students/scholarships/maori-pasifika/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori","Pasifika"],"other":"The Māori and Pasifika Trades Training (MPTT) scholarship is a transformative initiative designed to support students of Māori and Pacific heritage who are enrolled in eligible programmes"},"rounds":[]},{"i":"700800001_honorary_degrees_and_awards","n":"Honorary degrees and awards","o":"700800001","about":"The honorary degrees and awards at Auckland University of Technology (AUT) hold immense significance. They recognise individuals who have made significant contributions to AUT, Aotearoa New Zealand and the world. Conferment of these honorary degrees and awards is made by the AUT Council pursuant to the University Statute under the powers of section 284 of the Education and Training Act 2020. Read more aboutAUT's honorary doctors, fellows and former staffwho have significantly contributed to AUT and the wider community.","levels":["PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.aut.ac.nz/alumni/honorary-degrees-and-awards","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori","Indigenous"],"other":"AUT appoints four Professor Emeriti Auckland University of Technology has recognised four distinguished academics with the title of Emeritus Professor, acknowledging their exceptional leadership, teaching, research and long-standing service to AUT and communities in Aotearoa and beyond"},"rounds":[]},{"i":"700311001_asurequality_seed_technology_scholarship","n":"AsureQuality Seed Technology Scholarship","o":"700311001","about":"This scholarship was first offered in 2005, and using funding generated by Seed Tech Services. In 2022, this business was purchased by AsureQuality, who recognise the importance of supporting and developing future capability within the seed industry and so continue to fund these scholarships. The name changed to AsureQuality Seed Technology Scholarship to mark this change We're looking for postgraduate students researching agronomy This is a postgraduate scholarship. You will want to or be undertaking research that involves agricultural plants, such as pasture, crops, seeds and trees. Ideally, you will be a master’s student and your research project will involve some aspect of seed biology or seed technology.","levels":["Masters","Postgraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"One Years"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/seed-tech-services-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be: studying full-time undertaking research in agricultural plants, such as pasture, crops, seeds, and trees"},"rounds":[]},{"i":"700311001_leonard_condell_farming_research_scholarship","n":"Leonard Condell Farming Research Scholarship","o":"700311001","about":"These scholarships are awarded by the Leonard Condell Farming Scholarship Trust established under the terms of the will of Leonard Condell. He was a Pukekohe farmer who died in 1974. Include the following with your application: When choosing our recipient, we will consider your academic achievements, good character, and financial need. We will also consider how your research topic meets the intentions of the scholarship.","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$4,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/leonard-condell-farming-research-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"a copy of your academic transcripts"},"rounds":[]},{"i":"700311001_brian_aspin_memorial_scholarship","n":"Brian Aspin Memorial Scholarship","o":"700311001","about":"At LIC we are proud of our contribution to the New Zealand dairy sector. Our vision is to improve the prosperity and productivity of New Zealand farmers; and we want great people to join us on the journey. The Livestock Improvement Brian Aspin Scholarship Programme is named after a passionate dairy farmer who had a 38 year association with LIC. He was an Artificial Breeding Technician, an Artificial Breeding Supervisor, Liaison Farmer and Shareholder Councillor. Following Brian’s passing, his family, in collaboration with LIC, created a memorial scholarship fund to ensure his legacy is preserved while supporting talented students pursuing careers in agriculture and farming. We're looking for candidates who want to pursue careers in agriculture.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"21 January 2027","closing":"9 March 2027","entry":"Applications open 21 January 2027 and close 9 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/brian-aspin-memorial-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Academic ability with special emphasis on agriculture"},"rounds":[]},{"i":"700311001_manaaki_new_zealand_scholarships","n":"Manaaki New Zealand Scholarships","o":"700311001","about":"The Manaaki New Zealand Scholarship is funded through the New Zealand Aid Programme and is administered by Education New Zealand (ENZ), in partnership with the New Zealand Ministry of Foreign Affairs and Trade (MFAT). Massey administers these scholarships and provides pastoral care to the students. The purpose of the scholarship is to provide recipients with academic study to learn new skills and acquire knowledge to assist in the social and economic development of their country when you return home. The New Zealand Aid Programme provides scholarships as part of our mission to support sustainable development to reduce poverty and contribute to a more secure, equitable and prosperous world. Scholarships are offered in specific subject areas that are most relevant to the development needs of","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"6 Years"}],"opening":"1 March 2027","closing":"10 April 2027","entry":"Applications open 1 March 2027 and close 10 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/manaaki-new-zealand-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"The purpose of the scholarship is to provide recipients with academic study to learn new skills and acquire knowledge to assist in the social and economic development of their country when you return home"},"rounds":[]},{"i":"700311001_taranaki_tree_crops_scholarship","n":"Taranaki Tree Crops Scholarship","o":"700311001","about":"This scholarship was initiated by a gift from the Taranaki Branch of the New Zealand Tree Crops Association. This is a postgraduate scholarship. You will be studying a postgraduate degree or diploma in agriculture or horticulture, undertaking research related to trees. Include the following with your application:","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/taranaki-tree-crops-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"your academic transcripts for any tertiary study completed outside of Massey University"},"rounds":[]},{"i":"700311001_joan_berry_fellowships_in_veterinary_science_postgraduate","n":"Joan Berry Fellowships in Veterinary Science - Postgraduate","o":"700311001","about":"We're looking for a postgraduate veterinary science student with a passion for promoting animal health and welfare. This is a postgraduate scholarship. You will be studying veterinary science. Include the following with your application:","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$8,500"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 February 2027","closing":"1 May 2027","entry":"Applications open 1 February 2027 and close 1 May 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/joan-berry-fellowships-in-veterinary-science-postgraduate/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"a written reference on your academic abilities and research potential from an academic member of staff in the School of Veterinary Science"},"rounds":[]},{"i":"700311001_mona_and_rex_mcclenaghan_veterinary_scholarship","n":"Mona and Rex McClenaghan Veterinary Scholarship","o":"700311001","about":"The Mona and Rex McClenaghan Veterinary Scholarship was established to support talented veterinarians to pursue postgraduate study primarily into canine health, and welfare, including the societal and personal benefits of pet ownership. This scholarship has been established to remember and honour Mona and Rex’s lifelong love for all types of animals. We're looking for someone with a passion for canine health and welfare, or for pet ownership, and who is intending to undertake research in this area.","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$50,000"}],"lengths":[{"condition":"NoCondition","length":"3 Years"}],"opening":"1 March 2027","closing":"1 June 2027","entry":"Applications open 1 March 2027 and close 1 June 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/mona-and-rex-mcclenaghan-veterinary-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":[],"other":"a copy of your academic transcripts for your full tertiary level background"},"rounds":[]},{"i":"700311001_massey_university_foundation_peer_scholar_award","n":"Massey University Foundation Peer Scholar Award","o":"700311001","about":"The purpose of Scholars Massey is to connect scholarship holders at all levels of study across the university and support them to be the best they can be in pursuing their scholarly aspirations.The recipients of the Massey University Foundation Peer Scholar Award will be the ambassadors and leaders of theScholars Massey program. Scholars Massey connects scholarship holders at all levels of study across the university and supports students with their scholarship applications. As a Peer Scholar you will help others achieve and at the same time develop your own personal and professional skills through the supportive Scholars Massey community. Peer scholars are a select cohort who will be provided with a specialised development programme. This includes leadership and strengths training, and pe","levels":["PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$6,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"18 July 2026","closing":"18 October 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-foundation-peer-scholar-award/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"You must be a recent holder of one of the following awards:  Massey University Undergraduate First Year Scholarship – School Leavers He Oha Puiaki - Massey University Māori First Year Scholarship Massey University Undergraduate Excellence Scholarship Massey University Postgraduate Scholarship Massey University Master’s Research Scholarship Massey University Scholar Award Massey University Doctoral Scholarship Massey University Alumni Doctoral Scholarship  Shortlisted applicants will be invited to attend an interview"},"rounds":[]},{"i":"600737001_insertedit_link","n":"Insert/edit link","o":"600737001","about":"We're sorry. The content you were looking for has either moved or been deleted.Clickhereto return to the homepage.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.eit.ac.nz/wp-content/uploads/2023/06/EIT-Youth-Scholarship-Application-Form-2023.pdf/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_noeleen_olson_horticulture_masters_scholarship","n":"Noeleen Olson Horticulture Masters Scholarship","o":"700311001","about":"Noeleen Olson graduated from Massey University with a BA (Humanities) in 1970. Noeleen was a school teacher for all her working life and retired from teaching in 1988 after 28 years at Roslyn Primary School, Palmerston North. While she loved children and teaching, she had a life-long passion for horticulture and was a founding member of Palmerston North’s horticultural society. This is a postgraduate scholarship. You will be enrolled in a master's degree in horticultural science in either your first year or second year of the qualification. You must be a New Zealand citizen undertaking a master's degree in the field of horticultural science.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$15,000"}],"lengths":[{"condition":"NoCondition","length":"Two Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/noeleen-olson-horticulture-masters-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a master's degree in horticultural science in either your first year or second year of the qualification"},"rounds":[]},{"i":"600627001_financial_assistance","n":"Financial assistance","o":"600627001","about":"If you’re an enrolled Ara student facing unexpected hardship, there are several funds you can apply to which are designed to enable you to continue your current course of study. Your application is considered on its own merits as to whether it meets the fund’s criteria.Scholarshipsare also available as another source of financial assistance. For further information visit Student Central at your campus. Please note that financial assistance can not be used to pay for your course fees. If you are an enrolled Ara student, you can apply for Emergency Vouchers of up to $100 for urgent and immediate needs, to enable you to continue with your study.","levels":["General"],"values":[{"condition":"NoCondition","value":"$500"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Close","url":"https://www.ara.ac.nz/student-services/supporting-your-study/scholarships-and-financial-assistance/financial-assistance/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_the_roger_marshall_scholarship","n":"The Roger Marshall Scholarship","o":"700311001","about":"The Roger Marshall Scholarship, proudly offered by Kelso Genetics, honours the legacy of company founder Roger Marshall—an innovator and pioneer in New Zealand sheep genetics. Valued at $5,000 (GST incl) and awarded annually, this scholarship is designed to support the next generation of leaders in sheep and beef farming or agribusiness. Roger was a visionary, and demonstrated extraordinary tenacity in his pursuit of excellence in sheep breeding. The core pillars that support Kelso Genetics today of ‘Listening, Thinking, and Innovating’ originate from Roger’s determination to lead, by offering superior genetics to help drive better performance in sheep farming. This scholarship reflects those same principles, aiming to foster future professionals who share Roger’s passion for farming and h","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"1 February 2027","closing":"30 April 2027","entry":"Applications open 1 February 2027 and close 30 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/the-roger-marshall-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must be the son or daughter of a Kelso Genetics client (employees included) and demonstrate a strong passion for farming and agribusiness, a dedication to academic growth, and a forward-thinking mindset"},"rounds":[]},{"i":"700311001_millar_massey_buchanan_scholarship","n":"Millar Massey Buchanan Scholarship","o":"700311001","about":"This scholarship is supported by the combined funds derived from the William Millar Bequest, the Sir Walter Buchanan Endowment and the William Massey Memorial Trust. These funds were amalgamated in 2000 to support postgraduate research in agriculture. We're looking for someone who wants to make a significant contribution through scientific endeavour to the primary industries in New Zealand. This is a postgraduate scholarship. You will want to or be studying a postgraduate degree or diploma with a focus on agriculture or horticulture.","levels":["Diploma","Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/millar-massey-buchanan-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You must be a New Zealand citizen or resident who is studying agriculture or horticulture full time"},"rounds":[]},{"i":"700800001_ng_whakamnawa_o_matarikistaff_awards_aut_matariki_awards","n":"Ngā Whakamānawa o MatarikiStaff awards: AUT Matariki Awards","o":"700800001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.aut.ac.nz/about/aut-awards-and-honours/staff-awards-aut-matariki-awards","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_ptea_tautoko_doctoral_financial_support_grant","n":"Pūtea Tautoko - Doctoral Financial Support Grant","o":"700311001","about":"Applications which are received in December 2025 or January 2026 will not be considered until late-January 2026. You can expect an outcome in your Student Portal by February 2026. The Pūtea Tautoko - Doctoral Financial Support Grant was established by Massey University with combined funds donated by the Massey University Foundation and doctoral examiners who have contributed their examination fee to this fund. Applications are accepted year-round and assessed on a rolling basis.","levels":["PhD / Doctorate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"1 December 2025","closing":"30 November 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/p%C5%ABtea-tautoko-doctoral-financial-support-grant/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be currently enrolled in a doctoral degree and be making satisfactory progress in your research"},"rounds":[]},{"i":"700122001_undergraduate_scholarships","n":"Undergraduate scholarships","o":"700122001","about":"Are you studying at secondary school? Maybe you left last year or are already working towards your bachelor degree. Check out the scholarships available and find one that fits. Find scholarships available to you as an entry level or first year student. School-leaver and first-year scholarships","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Each scholarship’s application process is different. Find out how to apply for a scholarship at the University of Auckland.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/scholarship-types/undergraduate-scholarships.html","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_international_creative_excellence_undergraduate_scholarship","n":"International Creative Excellence Undergraduate Scholarship","o":"700311001","about":"The International Creative Excellence Undergraduate Scholarship acknowledges the creative excellence and strength of creative vision to support international students enrolling in the first year of an undergraduate degree with theCollege of Creative ArtsMassey University. You will be a new international student who can demonstrate creative excellence through a portfolio. This is an undergraduate scholarship. In 2027 you will be enrolling in the first year of one of the following qualifications:","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"15 July 2026","closing":"15 October 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/international-creative-excellence-undergraduate-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"In order to be considered for this award you must be: an international student intending to enrol in the first year of an undergraduate degree with the College of Creative Arts in Semester 1 (February) 2027"},"rounds":[]},{"i":"600449001_adhb_health_workforce_scholarship","n":"ADHB Health Workforce Scholarship","o":"600449001","about":"These scholarships are designed to grow our Māori nursing and midwifery workforce at Auckland DHB to ensure that we are meeting our obligation to Te Tiriti o Waitangi and enable equitable workforce participation for Māori. These scholarships are designed to grow our Māori nursing and midwifery workforce at Auckland DHB to ensure that we are meeting our obligation to Te Tiriti o Waitangi and enable equitable workforce participation for Māori. This endeavour recognizes that Māori caring for Māori is crucial to culturally responsive and competent care as well as helping eliminate health inequities experienced by our indigenous Māori population. Provision of scholarships to Māori is aimed at eliminating financial barriers to tertiary education and enabling potential in our communities. Opening","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Scholarships will only be available to students enrolled in the following tertiary education institutions: Massey University Albany, Auckland University of Technology, UNITEC, University of Auckland and Manukau Institute of Technology, WINTEC (for Midwifery students only).You will be a New Zealand Citizen or New Zealand permanent resident to be eligible for any of the scholarships.You will not be able to hold a scholarship within this programme and at the same time hold another scholarship from another DHB.You will be of New Zealand Maori ethnicity and can describe your whakapapaYou will be of indigenous Pacific island ethnicity (for midwifery and enrolled nurse scholarships only)Maori applicants will be eligible for midwifery, registered nursing and enrolled nursing scholarshipsPacific ap","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/adhb-health-workforce-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori","Pacific Islands","Indigenous"],"other":"Scholarships will only be available to students enrolled in the following tertiary education institutions: Massey University Albany, Auckland University of Technology, UNITEC, University of Auckland and Manukau Institute of Technology, WINTEC (for Midwifery students only)"},"rounds":[]},{"i":"700311001_china_scholarship_council_csc_massey_university_phd_scholars_programme","n":"China Scholarship Council (CSC) - Massey University PhD Scholars Programme","o":"700311001","about":"Massey University invites high achieving, excellent Chinese students to apply for PhD study in New Zealand with scholarship support from the China Scholarships Council (CSC) and the University. Our collaboration is designed to foster research cooperation between Massey University and Chinese universities by supporting doctoral candidates to undertake original research. Massey University has a valued relationship with the China Scholarship Council as illustrated by ourongoing agreement. Successful recipients will receive funding from CSC for travel, living and accommodation costs, while Massey University will support the tuition fee component.","levels":["PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"Four Years"}],"opening":"10 March 2027","closing":"1 April 2027","entry":"Applications open 10 March 2027 and close 1 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/china-scholarship-council-massey-university-phd-scholars-programme/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"When selecting the successful recipients, your academic background and intended research project will be taken into consideration"},"rounds":[]},{"i":"700800001_aut_blue_awards_celebrating_students_who_excel","n":"AUT Blue Awards: celebrating students who excel","o":"700800001","about":"The AUT Blue Awards recognise AUT students who excel in their chosen sport or area of art, design and culture while maintaining high academic standards. The Blues are part of a tradition dating back to 1922 in New Zealand and earlier in England, where the colours of Oxford and Cambridge Universities came to symbolise excellence in sport. The AUT Blue Awards were initiated in 2002 and have since expanded to include students from all art, design and cultural disciplines. Congratulations to the AUT Blue Awards winners! A standout performer and proud member of The Royal Family Dance Crew, Havana Beal has excelled globally, winning 1st place at the World Dance Crew Competition in Auckland and placing 4th at the International Dance League in Los Angeles. Havana has also performed at the Suncorp ","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.aut.ac.nz/student-life/opportunities-and-careers/aut-blue-awards","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"The AUT Blue Awards recognise AUT students who excel in their chosen sport or area of art, design and culture while maintaining high academic standards"},"rounds":[]},{"i":"600449001_kate_edger_practicum_awards","n":"Kate Edger Practicum Awards","o":"600449001","about":"To assist a woman to carry out study for a Bachelor’s or Master’s Degree or Postgraduate Diploma with a required practicum component at an approved Institute in the Auckland area. The awards will be made for a year of study that requires a student to undertake a practicum which is usually unpaid and involves travel or residence away from home. To assist a woman to carry out study for a Bachelor’s or Master’s degree  or Postgraduate Diploma with a required practicum component at an approved institute in the Auckland region. Up to four awards will be made for a year of study that requires a student to undertake a practicum which is usually unpaid and involves travel or residence away from home. This award is administered by the Kate Edger Foundation.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$7,500"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"17 February 2025","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/kate-edger-practicum-awards/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Applicants for the Practicum Award must be:"},"rounds":[]},{"i":"700311001_new_zealand_refugee_health_scholarship","n":"New Zealand Refugee Health Scholarship","o":"700311001","about":"The New Zealand Refugee Health Scholarship Programme was developed in 2025 by the National Leadership and Coordination Service (NLCS), a joint function established through a partnership between the Ministry of Business Innovation and Employment (MBIE) | Immigration New Zealand, the Ministry of Health, and the Health New Zealand | Te Whatu Ora). The scholarship is available to both undergraduate  and postgraduate applicants and the first year of the award will be for study commencing first semester or first trimester of 2026. The purpose of the scholarship is to create more equitable access to health-related education and training for former refugees to increase refugee representation in the refugee health workforce. This is to improve health outcomes for former refugees and their families.","levels":["Diploma","Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$25,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 July 2026","closing":"1 October 2026","entry":"Universities New Zealand","url":"https://www.massey.ac.nz/study/scholarships-and-awards/new-zealand-refugee-health-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Eligible qualifications must be at level 7 or above and offered by a NZQA-accredited tertiary provider with at least one year of full-time study remaining at the time of the award"},"rounds":[]},{"i":"700311001_beca_scholarship_for_rangitne_o_manawat_students","n":"Beca Scholarship for Rangitāne o Manawatū Students","o":"700311001","about":"We're looking for student's who whakapapa to Rangitāne. Preference may be given to students who whakapapa to Rangitāne o Manawatū, though all Rangitāne students are encouraged to apply. You will be enrolled, full time or part time, in an undergraduate or postgraduate qualification in one of the following disciplines at Massey University: Include the following with your application:","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$4,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 May 2026","closing":"1 August 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/beca-scholarship-for-rangit%C4%81ne-o-manawat%C5%AB-students/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_adams_fellowship","n":"Adams Fellowship","o":"700311001","about":"Established in 1954,Esco Industriesis a respected provider of electrical, gas, and cabling solutions across a wide range of industries with operations spanning both Australia and New Zealand. Esco Industries has a reputation built on innovation, quality, and customer focus. It is committed to excellence and engineers’ solutions that set the standard for durability, functionality, and long-term value. Steve Adams, owner of Esco Industries, has a strong connection to Palmerston North, and to Massey University where he studied for his Bachelor of Technology (Hons) majoring in Manufacturing and Industrial Technology. Steve graduated with First Class Honours and was awarded the IRHACE Award for his final-year project. We're looking for someone with career aspirations who has significant work ex","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$43,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"},{"condition":"Domestic students","length":"7 Years"}],"opening":"4 March 2027","closing":"1 May 2027","entry":"Applications open 4 March 2027 and close 1 May 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/adams-fellowship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"a copy of your academic transcripts for your full tertiary level background"},"rounds":[]},{"i":"601558001_fees_scholarships","n":"Fees & Scholarships","o":"601558001","about":"Details of the scholarship are available on the provider's official page.","levels":["Diploma","Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$33,700"}],"lengths":[{"condition":"NoCondition","length":"2 Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Degree Holders and/or applicants who can demonstrate equivalent practical, orProfessional or educational experience in a related discipline may also be considered.","url":"https://www.sit.ac.nz/International/Fees-Scholarships","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"1 1/2 years (18 academic months)"},"rounds":[]},{"i":"700311001_julie_alley_bursary","n":"Julie Alley Bursary","o":"700311001","about":"Julie Alley died in 1996, aged 28 years. She graduated from Massey University with a Master of Science (Ecology). She was fully committed to the conservation of New Zealand's indigenous flora and fauna, working for three years as a research scientist. We're looking for candidates who are undertaking research in the Wildlife and Ecology Group at Massey University's Manawatū campus. You will be facing financial hardship. This is a postgraduate scholarship. You will be studying ecology.","levels":["Masters","Postgraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 June 2026","closing":"10 August 2027","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/julie-alley-bursary/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Indigenous"],"other":"You must be: based on the Manawatū campus undertaking postgraduate research in the Wildlife and Ecology Group facing financial hardship an enrolled Massey University student"},"rounds":[]},{"i":"700311001_institute_of_education_postgraduate_pathway_scholarship","n":"Institute of Education Postgraduate Pathway Scholarship","o":"700311001","about":"Institute of Education staff are actively engaged in a diverse range of research on significant educational questions. There is a strong focus on providing high quality research and professional training pathway experiences for postgraduate students. The Institute can provide an authentic training pathway by including recipients as members of one of the research teams, and by supporting recipients to make a practical contribution to scholarly and professional knowledge. You are invited to apply for one of the following scholarships: - Kia Mārama Postgraduate Pathway Scholarship; for applicant’s who identify as Māori or are undertaking research in the area of Māori education - Growing Pearls of Wisdom Postgraduate Pathway Scholarship; for applicants who identify as Pacific or are undertakin","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"12 January 2027","closing":"30 March 2027","entry":"Applications open 12 January 2027 and close 30 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/institute-of-education-postgraduate-pathway-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"a letter of support from academic staff member affiliated with your intended research"},"rounds":[]},{"i":"700311001_anzmes_research_funding_opportunities","n":"ANZMES research funding opportunities","o":"700311001","about":"Associated New Zealand Myalgic Encephalomyelitis Society (ANZMES) is the national advisory body for Myalgic Encephalomyelitis/Chronic Fatigue Syndrome (ME/CFS), in New Zealand, recently also extending our support to people with Long COVID. One of our constitutional objectives is to promote and invest in ME/CFS-focussed research and we are now in a position to offer a new research funding programme. There will be six funding opportunities that may be awarded each year to Postgraduates who undertake research that furthers understanding, treatment, or prevention of ME/CFS and Long COVID, including two $20,000-$25,000 grants to support quantitative research studies and four $5,000 scholarships as a stipend to support student study expenses for either qualitative or quantitative research projec","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$20,000"},{"condition":"Academic merit / GPA requirements","value":"$25,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"31 May 2026","closing":"31 July 2026","entry":"","url":"https://www.massey.ac.nz/study/scholarships-and-awards/anzmes-research-funding-opportunities/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Academic researchers are invited to apply for the grants also"},"rounds":[]},{"i":"601420001_how_to_pay","n":"How to Pay","o":"601420001","about":"You must pay your course fees prior to starting study, or make arrangements to pay them. An invoice will be sent with your confirmation letter. Credit card, cheque or EFTPOS card at our physical campuses. Cash payments will not be accepted at any campus. Please include your student ID in the particulars, your name in the code and the invoice number in the reference.","levels":["General"],"values":[{"condition":"NoCondition","value":"$924"}],"lengths":[{"condition":"Domestic students","length":"1 Year"},{"condition":"International students","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.whitireia.ac.nz/enrolment-information/funding-your-study/how-to-pay","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700277001_sir_edmund_hillary_scholarship_programme","n":"Sir Edmund Hillary Scholarship Programme","o":"700277001","about":"Named in honour of New Zealand’s greatest adventurer, the programme educates scholars within the values of Sir Edmund Hillary and supports their growth and excellence in sport, creative and performing arts, academia, and leadership. Honouring the legacy of New Zealand’s greatest adventurer, the Sir Edmund Hillary Scholarship Programme inspires scholars to embody his values while excelling in sport, creative and performing arts, academia, and leadership. Hillary Scholars receive support to pursue their passions alongside their qualifications at the University of Waikato. They also benefit from targeted leadership and personal development opportunities.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Learn how to apply on the scholarship application page.","url":"https://www.waikato.ac.nz/study/scholarships/sir-edmund-hillary-scholarship-programme/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"If you’re a school leaver with demonstrated leadership capabilities, academic excellence, and achievements in sport or creative and performing arts, this prestigious programme is for you"},"rounds":[]},{"i":"700311001_professor_douglas_paton_legacy_fund","n":"Professor Douglas Paton Legacy Fund","o":"700311001","about":"Professor Douglas Paton was a world class researcher and listed in the Stanford University/Elsevier BV list of the top 2% most cited researchers worldwide. He has created an extraordinary body of knowledge and wisdom in the Disaster Risk Reduction (DRR) space in the form of comprehensive theories developing all-hazards and cross-cultural individual and collective adaptive capacities. Clickhereto read more about Professor Douglas Paton. To honour Douglas’s legacy on his contribution in DRR, his family, partner, and colleagues have created three annual scholarships and awards in his name to support postgraduate students, emerging researchers, accomplished scholars, and practitioners. These are the: These awards recognise and advance Douglas’s visionary work in disaster science, his deep comm","levels":["PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"1 August 2026","closing":"31 October 2026","entry":"Applications open 1 August 2026 and close 31 October 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/professor-douglas-paton-legacy-fund/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_albert_and_alexis_dennis_donation","n":"Albert and Alexis Dennis Donation","o":"700311001","about":"We're looking for someone who is aged 65 years or older. This is an undergraduate or postgraduate scholarship. You will want to or be studying by distance. You must be aged 65 years or older and studying by distance","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$1,500"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"28 January 2027","closing":"28 March 2027","entry":"Applications open 28 January 2027 and close 28 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/albert-and-alexis-dennis-donation/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be aged 65 years or older and studying by distance"},"rounds":[]},{"i":"700122001_scholarships_for_international_students","n":"Scholarships for international students","o":"700122001","about":"Discover our range of undergraduate scholarships available to international students. Find out more about our postgraduate scholarships for international students. Read more about our doctoral scholarships for international students.","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Each scholarship’s application process is different. Find out how to apply for a scholarship at the University of Auckland.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/scholarship-types/scholarships-for-international-students.html","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"602432001_general_scholarship","n":"General Scholarship","o":"602432001","about":"Each qualification has its tuition fee - This is the cost of your study. However, there may be additional costs such as tools, uniforms and equipment.Check the programme information page for the most up-to-date information about costs. Right now, the Government is investing in education to remove cost barriers for tertiary education and to fill skill-shortage areas. Let them invest in you, so you can gain a qualification that gives you recognised skills and greater job opportunities. Starting tertiary study or work-based learning for the first time? You may be able to get Fees Free after youcompleteyour first eligible qualification or programme.","levels":["General"],"values":[{"condition":"NoCondition","value":"$12,000"}],"lengths":[{"condition":"NoCondition","length":"Two Years"},{"condition":"Domestic students","length":"Three Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Complete the Tai Poutini Polytechnic enrolment form and the Tai Poutini Polytechnic Youth Guarantee Scheme application form. You can still apply for a Youth Guarantee Scheme place if you have already been accepted onto a programme. Application forms and more information can befoundhere.","url":"https://www.tpp.ac.nz/explore/fees-and-funding#layout","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"To qualify for a student loan you must be a New Zealand citizen, an Australian citizen or permanent New Zealand resident who has lived in New Zealand for at least three years, enrolled in a Ministry of Education approved full time or part-time programme (the equivalent of at least 12 weeks full time)"},"rounds":[]},{"i":"700311001_j_p_skipworth_scholarship_plant_biology","n":"J P Skipworth Scholarship - Plant Biology","o":"700311001","about":"This scholarship was established in recognition of the valuable contribution made by Associate Professor John P. Skipworth to the Department of Botany and Zoology from 1960 to 1991. The funds for the scholarship have been provided from royalties received by Dr Nelson Pomeroy through his research on bumble bees and pollination. This is a postgraduate scholarship. You will be undertaking research in the field of Plant Biology at a postgraduate or master's level at Massey University. Include the following with your application:","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"31 March 2026","closing":"15 August 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/j-p-skipworth-scholarship-plant-biology/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"When choosing our recipient we will consider your academic merit and financial need"},"rounds":[]},{"i":"700311001_hudson_and_mcgowan_scholarship","n":"Hudson and McGowan Scholarship","o":"700311001","about":"The scholarship is support by a combined fund from endowments from the late H. W. Hudson of Auckland in appreciation for agricultural training received by his son William, and the late Edgar Augustus McGowan, an engineer from Auckland who wished to commemorate his father Daniel Joseph McGowan. We're looking for a Massey University graduate. This is a postgraduate scholarship. You will want to or be studying a postgraduate degree or diploma with a focus on agriculture or horticulture.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$4,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/hudson-and-mcgowan-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be a Massey University graduate who is enrolled full time in agriculture or horticulture"},"rounds":[]},{"i":"700311001_elizabeth_a_cooper_grant_for_students_with_disabilities","n":"Elizabeth A Cooper Grant for Students with Disabilities","o":"700311001","about":"Elizabeth A Cooper, who was severely disabled by polio in her childhood, was a significant leader in the disability rights movement. She was one of the founders of the Disabled Persons Assembly Palmerston North and was a staunch advocate in supporting people with disabilities. Elizabeth passed away in 2001, this grant was established by Massey University in her memory. You will be enrolled full time or part time in an undergraduate or postgraduate qualification at Massey University in the year of the award. You must be registered with the Massey University Disability Services. Include the following with your application:","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$500"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"20 January 2027","closing":"20 March 2027","entry":"Applications open 20 January 2027 and close 20 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/elizabeth-a-cooper-grant-for-students-with-disabilities/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You must be registered with the Massey University Disability Services"},"rounds":[]},{"i":"700311001_drenched_charitable_trust_scholarship","n":"Drenched Charitable Trust Scholarship","o":"700311001","about":"The Drenched Charitable Trust scholarship is to support those who have grown up with a high-support-needs sibling or parent. This family dynamic can result in poor mental health outcomes and financial hardship. Drenched is committed to uplifting this group of young people who often place the needs of others first and deserve support towards their own aspirations. Drenched will commit $1000 towards course-related costs for tertiary education. Please email:info@drenched.org.nzfor a link to our scholarship application form. Include the following with your application:","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$1,000"}],"lengths":[{"condition":"NoCondition","length":"24 Years"}],"opening":"1 December 2026","closing":"31 March 2027","entry":"Applications open 1 December 2026 and close 31 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/drenched-charitable-trust-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_ngarimu_vc_and_28th_mori_battalion_memorial_scholarships","n":"Ngarimu VC and 28th (Māori) Battalion Memorial Scholarships","o":"600449001","about":"Ngarimu VC and 28th (Māori) Battalion Memorial Scholarships provide financial assistance to exceptional applicants of Māori descent who are undertaking tertiary study and who demonstrate characteristics consistent with members of the 28th Māori Battalion. The Ngarimu VC and 28th (Māori) Battalion Memorial Scholarship applications close early September for vocational education and training for the following Academic year. The Ngarimu VC and 28th (Māori) Battalion Scholarship Fund Board usually award:","levels":["Diploma","PhD / Doctorate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$30,000"}],"lengths":[{"condition":"NoCondition","length":"Three Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/ngarimu-vc-and-28th-maori-battalion-memorial-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"The Ngarimu VC and 28th (Māori) Battalion Memorial Scholarship applications close early September for vocational education and training for the following Academic year"},"rounds":[]},{"i":"700311001_te_mana_o_rangithua_funding_opportunities","n":"Te Mana o Rangitāhua funding opportunities","o":"700311001","about":"If you are a Ngāti Kuri student interested in any of the areas listed, we would love to hear from you. As our research programme is funded through to 2025, please reach out even if you are early in your studies as we will have opportunities for student researchers throughout our programme. We also offer flexibility in terms of your location and your tertiary institution. To find out more, please reach out. We’d love to hear from you and welcome an informal chat with you about what might be possible. We have scholarships and opportunities for you, to support you in your educational journey, whatever level you are at.","levels":["Masters","PhD / Doctorate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Download application form","url":"https://www.massey.ac.nz/study/scholarships-and-awards/te-mana-o-rangitahua-funding-opportunities/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Indigenous"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_school_of_veterinary_science_masterate_scholarship_in_cattle_health_an","n":"School of Veterinary Science Masterate Scholarship in Cattle Health and Diseases","o":"700311001","about":"This program will prepare the resident to sit the certifying board examination in the specialty of Bovine Health Management as well as providing an introduction to clinical research by completion of the Masterate in Veterinary Studies. A Diploma of the European College of Bovine Health Management qualifies the owner to obtain registration as “Veterinary specialist in Cattle management and diseases” with the NZ Veterinary Council and the Australasian Veterinary Boards Council. The role involves conducting clinical duties as part of the Farm Services Clinic in the Veterinary Teaching Hospital to gain in-depth knowledge of bovine health management and its supporting disciplines under the supervision and guidance of Diplomates of the ECBHM and senior farm animal clinicians. The program will co","levels":["Diploma","Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$46,425"}],"lengths":[{"condition":"NoCondition","length":"Three Years"}],"opening":"4 June 2026","closing":"4 July 2026","entry":"Applications open 4 June 2026 and close 4 July 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/school-of-veterinary-science-masterate-scholarship-in-cattle-health-and-diseases/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"a certified copy of your academic record (for any study completed outside of Massey University)"},"rounds":[]},{"i":"700311001_massey_university_masters_research_scholarship_semester_two","n":"Massey University Master's Research Scholarship - Semester Two","o":"700311001","about":"We're looking for candidates who are enrolling in the research component of a Massey University master's degree. Applicant's may be domestic or international students. This is a postgraduate scholarship. You will have completed the course component of your master's degree and be entering into the research component. You may apply for a Massey University Master's Research Scholarship, a Massey University Māori Master's Research Scholarship, or a Massey University Pacific Master's Research Scholarship. There are two selection rounds annually for the Massey University Master's Research Scholarship, closing at the start of semester 1 and closing at the start of semester 2.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$15,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"15 April 2027","closing":"15 July 2027","entry":"Applications open 15 April 2027 and close 15 July 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-masters-research-scholarship-semester-two/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":["Māori"],"other":"When choosing our recipient, we will consider your academic achievements in the course component of your master's degree"},"rounds":[]},{"i":"700311001_johannes_august_anderson_postgraduate_scholarship","n":"Johannes August Anderson Postgraduate Scholarship","o":"700311001","about":"This scholarship was established under the terms of the will of Johannes August Anderson, a retired farmer. This is a postgraduate scholarship. You will be studying a postgraduate diploma, postgraduate degree, or a doctoral degree in a discipline relevant to agriculture or horticulture at Massey University. Include the following with your application:","levels":["Diploma","Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/johannes-august-anderson-postgraduate-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"your academic transcripts for any tertiary study completed outside of Massey University"},"rounds":[]},{"i":"600449001_master_scholarships_for_pacific_students","n":"Master Scholarships for Pacific Students","o":"600449001","about":"These scholarships are available to support talentedPacificstudents studying towards a Masters qualification at Unitec. Please read theMasters Scholarship Guidelinesfor full details.","levels":["Masters","Postgraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"2026 Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Application and fundingScholarships and AwardsHow to applyAcademic CalendarAdmission requirementsDo your apprenticeship with usFeesFunding your studyChange Enrolment","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/master-scholarships-for-pacific-students/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700122001_postgraduate_scholarships","n":"Postgraduate scholarships","o":"700122001","about":"Check out postgraduate scholarship information and find out about other funding available for masters, sub-masters and doctoral study. Each scholarship’s application process is different. Find out how to apply for a scholarship at the University of Auckland.","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Each scholarship’s application process is different. Find out how to apply for a scholarship at the University of Auckland.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/scholarship-types/postgraduate-scholarships.html","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700277001_policies_and_guidelines","n":"Policies and Guidelines","o":"700277001","about":"The University of Waikato has a framework of principles, processes and responsibilities with respect to the scholarships, awards and prizes offered at the university. The Scholarships Policy applies to all students and staff of the University of Waikato and in accepting an offer of a scholarship, award or prize recipients will be deemed to have read, understood, and accepted the conditions of the scholarship, and theScholarships Policy. Please note:The amount offered by the University under any Award/Scholarship/Prize/Bursary is at the discretion of the Scholarships Panel/Selection Committee and subject to the criteria specified in the relevant regulations which may include, but not limited to, the total available funding, grades, financial need of the applicant, the number of applicants, ","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.waikato.ac.nz/study/scholarships/policies-and-guidelines/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700277001_scholarships_finder","n":"Scholarships Finder","o":"700277001","about":"Other funding opportunitiesfrom external providers Other funding opportunitiesfrom external providers","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.waikato.ac.nz/study/scholarships/find-a-scholarship/?page=1&filters=%7B%22studyLevel%22%3A%7B%22term_ids%22%3A%7B%22School+leaver%22%3A28%7D%7D%7D","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_massey_university_postgraduate_overseas_research_grant","n":"Massey University Postgraduate Overseas Research Grant","o":"700311001","about":"The purpose of the grant is to provide financial assistance to full time postgraduate research students who require a short term (up to 6 months) period of study or research overseas in any of the following categories: This is a postgraduate grant. You will be enrolled in a Postgraduate Diploma or Master's Degree at Massey University (doctoral students are not eligible for this grant). Include the following with your application:","levels":["Diploma","Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"6 Months"}],"opening":"15 December 2026","closing":"15 March 2027","entry":"Applications open 15 December 2026 and close 15 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-postgraduate-overseas-research-grant/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a Postgraduate Diploma or Master's Degree at Massey University (doctoral students are not eligible for this grant)"},"rounds":[]},{"i":"700122001_extensive_range_of_scholarships_for_new_international_students","n":"Extensive range of scholarships for new international students","o":"700122001","about":"Explore our range of scholarships if you're planning to enrol for the first time with us. The University of Auckland is dedicated to supporting international students by offering a wide range of scholarships, including exclusive scholarships for applicants from India and Southeast Asia. Our scholarships are highly sought-after and applications are extremely competitive, so make sure to start preparing your scholarship applications early.","levels":["Diploma","Masters","Postgraduate","Undergraduate"],"values":[{"condition":"International students","value":"$20,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"9 September 2026","closing":"21 October 2026","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/international-students/scholarships-loans-and-funding/extensive-range-of-scholarships-available.html","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_the_massey_university_foundation_enabling_excellence_bursary","n":"The Massey University Foundation Enabling Excellence Bursary","o":"700311001","about":"In 2015 The Massey University Foundation created theEnabling Excellence Fund. This fund was established specifically so that Massey University staff could make financial gifts to support students in financial hardship. This bursary supports students who suffer general hardship or unforeseen changes in their financial circumstances during the course of their postgraduate programme of study. This is a postgraduate bursary. You will be enrolled full time at any of Massey's campuses, or by distance in a Postgraduate Diploma or Master's Degree. Doctoral candidates are not eligible for this award. Include the following with your application:","levels":["Diploma","Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"15 May 2026","closing":"15 August 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/the-massey-university-foundation-enabling-excellence-bursary/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"When choosing our recipient we will look for genuine financial hardship, a record of academic success to date, and good character"},"rounds":[]},{"i":"700311001_massey_university_masters_research_scholarship_semester_one","n":"Massey University Master's Research Scholarship - Semester One","o":"700311001","about":"We're looking for candidates who are enrolling in the research component of a Massey University master's degree. Applicant's may be domestic or international students. This is a postgraduate scholarship. You will have completed the course component of your master's degree and be entering into the research component. You may apply for a Massey University Master's Research Scholarship, a Massey University Māori Master's Research Scholarship, or a Massey University Pacific Master's Research Scholarship. There are two selection rounds annually for the Massey University Master's Research Scholarship, closing at the start of semester 1 and closing at the start of semester 2.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$15,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"15 November 2026","closing":"15 February 2027","entry":"Applications open 15 November 2026 and close 15 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-masters-research-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":["Māori"],"other":"When choosing our recipient, we will consider your academic achievements in the course component of your master's degree"},"rounds":[]},{"i":"700311001_dr_warren_parker_and_pmu_agricultural_scholarship","n":"Dr Warren Parker and Pāmu Agricultural Scholarship","o":"700311001","about":"This scholarship is to honour the contributions to the agricultural sector of New Zealand of the late Dr. Warren Parker. Warren had an outstanding academic career and was involved at the highest levels of primary sector governance, in both the private and public sectors. As well as Chair of Pāmu, he was former chief executive of Scion (Forest Research Institute) and Manaaki Whenua - Land Care Research, and previously chief operating officer of AgResearch. He held board roles on Genomics Aotearoa, Farmlands Cooperative Society, Predator Free 2050, was chair of the Forestry Ministerial Advisory Group, the NZ Conservation Authority, and recently appointed independent chair of Quayside Holdings. With a PhD in animal science, Warren was previously professor of Agribusiness and Resource Manageme","levels":["PhD / Doctorate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$8,000"}],"lengths":[{"condition":"NoCondition","length":"One Years"}],"opening":"1 July 2026","closing":"1 October 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/dr-warren-parker-and-p%C4%81mu-agricultural-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Warren had an outstanding academic career and was involved at the highest levels of primary sector governance, in both the private and public sectors"},"rounds":[]},{"i":"600449001_k_ptea_scholarships","n":"Kā Pūtea Scholarships","o":"600449001","about":"Kā Pūtea Scholarships are available to all registered Ngāi Tahu members studying towards an NZQA-recognised tertiary qualification or an international equivalent. The scholarships aim to support higher learning and help students connect with their Ngāi Tahutanga.Kā Pūtea Scholarships are awarded based on applicants’ academic achievements and their engagement with whānau, hapū, or iwi-related activities. There are 58 Undergraduate Targeted Scholarships available for individuals studying a Certificate to level 7 and 24 Postgraduate Scholarships.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"6 February 2022","closing":"7 April 2023","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/ka-putea-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Kā Pūtea Scholarships are awarded based on applicants’ academic achievements and their engagement with whānau, hapū, or iwi-related activities"},"rounds":[]},{"i":"700311001_meat_industry_association_scholarships","n":"Meat Industry Association Scholarships","o":"700311001","about":"The scholarship programme provides a pathway for undergraduate or graduate students into the New Zealand red meat processing industry. Scholars will work part time or during vacation in the meat industry. Applications for the Scholarship programme can be made from October to Late November, when the Scholarship portal opens. For further details please, see ourfactsheet, visit the Scholarships page or look for announcements on the MIA website.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"Three Years"}],"opening":"8 October 2026","closing":"26 November 2026","entry":"Applications open 8 October 2026 and close 26 November 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/meat-industry-association-scholarships/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600737001_business_computing","n":"Business & Computing","o":"600737001","about":"For more information on any of the below scholarships please contact the School of Business atBusiness@eit.ac.nzor the School of Computing atComputing@eit.ac.nz. If you are an international student, please emailinternational@eit.ac.nz. Ryman Healthcare has generously offered a $15,000 scholarship in perpetuity, in the honour of the significant contribution that Sir James Wattie has made to the Hawke’s Bay economy through his entrepreneurship and philanthropy. Ryman Healthcare specifies that the scholarship be awarded to a business student, who has achieved a high academic standard, is in at least the second year of full time study, has made considerable adjustment in their lives in order to pursue their studies despite the challenges this has imposed, and whose life will significantly be c","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$15,000"},{"condition":"Targeted ethnicity criteria","value":"$5,000"}],"lengths":[{"condition":"Domestic students","length":"Two Years"},{"condition":"NoCondition","length":"One Semester"}],"opening":"6 July 2026","closing":"4 October 2026","entry":"All applicants (entrants) must email the following documentation togrants@onechoice.co.nzfor their submission to be considered:","url":"https://www.eit.ac.nz/students/scholarships/business-computing/","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":["Māori"],"other":"Ryman Healthcare specifies that the scholarship be awarded to a business student, who has achieved a high academic standard, is in at least the second year of full time study, has made considerable adjustment in their lives in order to pursue their studies despite the challenges this has imposed, and whose life will significantly be changed through this scholarship"},"rounds":[]},{"i":"700311001_sydney_campbell_foundation_postgraduate_scholarship","n":"Sydney Campbell Foundation Postgraduate Scholarship","o":"700311001","about":"This scholarship is provided under the will of Mr Sydney Campbell, who owned the Wairarapa sheep and beef farm Riverside Farm. We're looking for someone who is passionate about the Wairarapa region and wants to take their knowledge of agriculture and horticulture back to the region. This is a postgraduate scholarship. You will be studying a master's degree or PhD in one of the following areas:","levels":["Diploma","Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 July 2026","closing":"1 September 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/sydney-campbell-postgraduate-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"your academic transcripts for any tertiary study completed outside of Massey University"},"rounds":[]},{"i":"700311001_edward_turner_horticulture_futures_grant","n":"Edward Turner Horticulture Futures Grant","o":"700311001","about":"T&G Global invites postgraduate students to apply for the Edward Turner Horticulture Futures Grant, a $10,000 scholarship recognising emerging talent and fostering innovation across Aotearoa New Zealand’s horticulture sector. If you are a post-graduate tertiary student based in Aotearoa New Zealand planning your next step in your education, we want to hear from you. Whether you are planning to pursue a Masters, Honours or undertake a research project within horticulture, science or business disciplines, tell us how our $10,000 grant will assist your continued learning.","levels":["Masters","Postgraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"125 Years"}],"opening":"29 October 2026","closing":"14 November 2026","entry":"Applications open 29 October 2026 and close 14 November 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/edward-turner-horticulture-futures-grant/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Academic merit and the intended research or planned study will also be considered"},"rounds":[]},{"i":"700311001_william_milverton_scholarship","n":"William Milverton Scholarship","o":"700311001","about":"The scholarship is supported by a donation from the William Milverton Trust. This is an undergraduate or honours year scholarship. You will be enrolled full time, studying agriculture. Priority will be given to those candidates who have completed all or part of the practical work requirement for the degree. Include the following with your application:","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Years"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/william-milverton-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"When choosing our recipient we will consider your academic achievements in your study to date, as well as the potential benefit of receiving the award"},"rounds":[]},{"i":"700311001_the_hope_foundation_for_research_on_ageing_scholarship","n":"The HOPE Foundation for Research on Ageing Scholarship","o":"700311001","about":"The HOPE Foundation for Research on Ageing Scholarships seek to help prepare New Zealand for an ageing future by enabling research into ageing. This is a postgraduate scholarship. You will be enrolled in a master's degree or doctorate. You will undertake research in a topic related to ageing and its effects on individuals and society. Include the following with your application:","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$6,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"30 July 2026","closing":"30 October 2026","entry":"Applications open 30 July 2026 and close 30 October 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/hope-foundation-scholarship-for-research-on-ageing/","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":[],"other":"You will be enrolled in a master's degree or doctorate"},"rounds":[]},{"i":"700311001_te_whiri_whtau_masters_scholarship_for_2027","n":"Te Whiri Whītau Masters Scholarship for 2027","o":"700311001","about":"This scholarship provides a stipend to support a Master of Design (MDes) or Master of Fine Arts (MFA) student whose research or creative practice aligns with the kaupapa of Te Whiri Whītau, a research cluster within Toi Rauwhārangi College of Creative Arts. Te Whiri Whītau focuses on Indigenous-led and place-based approaches to natural fibre design, research, and creative practice. Applicants should demonstrate how their values, aspirations, and proposed project contribute to environmental, social, and cultural regeneration through critical, situated, and embodied engagement with materials, processes and systems.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$15,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"13 July 2026","closing":"21 August 2026","entry":"Contact us","url":"https://www.massey.ac.nz/study/scholarships-and-awards/te-whiri-wh%C4%ABtau-masters-scholarship-for-2027/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Indigenous"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_j_p_skipworth_scholarship_ecology","n":"J P Skipworth Scholarship Ecology","o":"700311001","about":"This scholarship has been established in recognition of the valuable contribution made by Associate Professor John P Skipworth to the Department of Botany and Zoology from 1960 to 1991. In 1992 the Department of Botany and Zoology was split into the Departments of Ecology and Plant Biology, each of which now administers part of the funds. The funds for the scholarship have been provided from royalties received by Dr Nelson Pomeroy through his research on bumble bees and pollination. We're looking for a postgraduate student undertaking research in the Wildlife and Ecology Group at Massey University. You must be enrolled on the Palmerston North campus and undertaking a research topic with a focus on ecology.","levels":["Masters","Postgraduate"],"values":[{"condition":"NoCondition","value":"$6,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 June 2026","closing":"10 August 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/j-p-skipworth-scholarship-ecology/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be enrolled on the Palmerston North campus and undertaking a research topic with a focus on ecology"},"rounds":[]},{"i":"600449001_keisha_rawiri_awarded_kate_edger_scholarship_for_master_of_architectur","n":"Keisha Rawiri awarded Kate Edger Scholarship for Master of Architecture Project","o":"600449001","about":"Bachelor of Architecture graduate and Ngā Wai A Te Tūī researcher Keisha Rawiri (Ngāti Hine, Ngāti Hāmoa) has been awarded a grant from The Kate Edger Educational Charitable Trust (KEECT) which will contribute to her Master of Architecture (Professional) Project supporting the regeneration of Tau Henare Marae in Te Taitokerau (Northland). Keisha’s Masters project represents an extremely significant journey of connection on a professional and personal level. KEECT Awards Coordinator Katrina Ford says Keisha’s hard work and determination to succeed combined with dedication to her whānau and community epitomizes the values of the Trust.","levels":["Masters","Undergraduate"],"values":[{"condition":"First year / School leavers","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/keisha-rawiri-awarded-kate-edger-scholarship-for-master-of-architecture-project/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori","Pasifika"],"other":"However, after having two children and working in finance, she was still unsure whether she could manage the academic load"},"rounds":[]},{"i":"700311001_gosling_ornamental_horticulture_bursary","n":"Gosling Ornamental Horticulture Bursary","o":"700311001","about":"This bursary is supported by the combined funds of the Ornamental Horticulture Trust Award and the M. W. L. and N. Gosling Bequest. We're looking for someone who is interested in the production of ornamental plants. This is an undergraduate or postgraduate scholarship. You will want to or be studying towards a qualification with a focus on horticulture. Your qualification will be relevant to the production of ornamental plants.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/gosling-ornamental-horticulture-bursary/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"your academic transcripts for any tertiary study completed outside of Massey University"},"rounds":[]},{"i":"700311001_massey_university_pacific_success_scholarship_for_masters_research_stu","n":"Massey University Pacific Success Scholarship for Master’s Research Studies","o":"700311001","about":"We're looking for Pacific students who are intending to enrol in the research component of a master's degree in the year following selection. You will demonstrate good character and community participation. Include the following with your application: When choosing our recipients we will consider your academic achievements, participation in community engagement, and character.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$6,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 November 2026","closing":"1 February 2027","entry":"Applications open 1 November 2026 and close 1 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-pacific-success-scholarship-for-masters-research-studies/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"When choosing our recipients we will consider your academic achievements, participation in community engagement, and character"},"rounds":[]},{"i":"700311001_george_mason_sustainable_land_use_scholarship","n":"George Mason Sustainable Land Use Scholarship","o":"700311001","about":"This scholarship is funded by the George Mason Charitable Trust. Dr George Mason was a Taranaki philanthropist and retired scientist. We're looking for candidates who are undertaking postgraduate research in the areas of durable resource management as affected by land use. This is a postgraduate scholarship. You will be studying towards a PhD or master's programme. You will be undertaking research that promotes sustainable land use, especially in relation to agriculture, forestry and/or conservation.","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$25,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/george-mason-sustainable-land-use-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"your academic transcripts for any tertiary study completed outside of Massey University"},"rounds":[]},{"i":"601915001_scholarship_list","n":"Scholarship List","o":"601915001","about":"Disclaimer: Every effort has been made to ensure that information is current and correct. But please contact the appropriate scholarship provider before making an application, as details change frequently. Please select one of the options below for information about scholarships offered. Lorem ipsum dolor sit amet, consectetuer adipiscing elit, sed diam nonummy nibh euismod tincidunt ut laoreet dolore magna aliquam erat volutpat. Ut wisi enim ad minim veniam, quis nostrud exerci tation ullamcorper suscipit lobortis nisl ut aliquip ex ea commodo consequat.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.wintec.ac.nz/student-resources/support-services/scholarships/scholarship-list?option=international","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_margaret_richards_bursary","n":"Margaret Richards Bursary","o":"700311001","about":"This bursary arises from a fund established in 1975 as a memorial to Margaret Richards, a member of the University staff from 1960 to 1975. We're looking for someone who is studying English. This is an undergraduate or postgraduate scholarship. You will want to or be studying the Bachelor of Arts (English), Bachelor of Communication (Expressive Arts) or a postgraduate qualification with a focus on English.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"28 February 2027","closing":"27 April 2027","entry":"Applications open 28 February 2027 and close 27 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/margaret-richards-bursary/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be studying in a specific subject area"},"rounds":[]},{"i":"700311001_helen_e_akers_postgraduate_scholarship","n":"Helen E. Akers Postgraduate Scholarship","o":"700311001","about":"This scholarship was established under the terms of the will of Helen E. Akers. It is funded from her shares in farming company, Maraekowhai Developing Company. This is a postgraduate scholarship. You will be studying a postgraduate diploma, postgraduate degree, or a doctoral degree in one of the Applied Academic Programme disciplines relevant to agriculture or horticulture at Massey University. You must be studying full-time in specific subject areas.","levels":["Diploma","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$6,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/helen-e-akers-postgraduate-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be studying a postgraduate diploma, postgraduate degree, or a doctoral degree in one of the Applied Academic Programme disciplines relevant to agriculture or horticulture at Massey University"},"rounds":[]},{"i":"700800001_china_scholarship_council_csc_scholarships","n":"China Scholarship Council (CSC) scholarships","o":"700800001","about":"High achieving students from China are encouraged to study for their PhD at Auckland University of Technology (AUT) through a collaborative agreement with China Scholarship Council (CSC). The programme aims to encourage research co-operation between AUT and Chinese universities. Students who receive a scholarship are provided with a living allowance as prescribed by the Chinese government for the term of the scholarship, return airfare to New Zealand by the most economical route, student visa fees, and the cost of health insurance for international students. These scholarships are available for the Doctor of Philosophy (PhD) programme only and are available for up to four years.","levels":["PhD / Doctorate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"Four Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply onlinefor admission to the Doctor of Philosophy (PhD) programme as soon as possible. Preferably before the end of October 2025. You must allow sufficient time for your application to be assessed by the University before the CSC scholarships open for application from March 2026. Assessment of applications for admission into the PhD programme may take several months.Information on the application process and entry requirements can be found on theDoctor of Philosophy webpage.Be sure to mention that you are applying for a CSC scholarship when you apply for admission.Submit a scholarship application to CSC in March 2026. The AUT Offer of Place should be provided to the CSC with your application for a scholarship. Please note that CSC will not accept conditional offers.","url":"https://www.aut.ac.nz/study/fees-and-scholarships/scholarships-and-awards-at-aut/china-scholarship-council-csc-scholarships","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600737001_givme_scholarship_database","n":"givME Scholarship Database","o":"600737001","about":"EIT has partnered with Generosity New Zealand to provide free access togivME, a searchable online database of scholarships, grants, and awards available across New Zealand. Anyone can now accessgivMEdirectly through our website. To see the full range, you’ll just need to create a login to start exploring funding opportunities that match your background and study goals. We collect personal information from you, including information about your:","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.eit.ac.nz/students/scholarships/givme-database/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori","Pacific Islands"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700277001_how_to_apply_for_scholarships_and_awards","n":"How to apply for scholarships and awards","o":"700277001","about":"Follow the five steps to apply for scholarship and awards. Applications are submitted through your MyWaikato portal which is where you go for all the details regarding your scholarship. Applying for scholarships and awards is easy. Follow the  five steps outlined on this page. Most scholarships are applied for through yourMyWaikato portal. However, some scholarships may link directly to applications submitted through external agencies.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Check your eligibility by thoroughly reading the regulations for each scholarship.Prepare all the required documents for each application. Remember, scholarship requirements can vary, so you might need multiple versions of certain documents.The required documents are generally listed in the regulations under'Application'.","url":"https://www.waikato.ac.nz/study/apply/scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_hawkes_bay_primary_industries_tertiary_bursary","n":"Hawke's Bay Primary Industries Tertiary Bursary","o":"700311001","about":"The Hawke's Bay Primary Industries Tertiary Bursary aims to For residents of Wairoa, Napier, Hastings or Central Hawkes Bay local authority areas. Administered by Korokipo Branch of Rural Women New Zealand","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"11 December 2026","closing":"15 January 2027","entry":"Applications open 11 December 2026 and close 15 January 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/hawkes-bay-primary-industries-tertiary-bursary/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Applicants must be residents of Wairoa, Napier, Hastings or Central Hawkes Bay local authority areas"},"rounds":[]},{"i":"700122001_setting_up_new_scholarships_and_prizes","n":"Setting up new scholarships and prizes","o":"700122001","about":"Find out how you can set up a new scholarship, prize or award. Potential donors who wish to establish scholarships and prizes should firstselect an area to support. These categories include specific scholarship funds you can support, and the contact details of the Development Manager for each Faculty or Research Institute. If you would like someone to contact you directly to discuss setting up a scholarship, prize or award, email:scholarships@auckland.ac.nz.","levels":["General"],"values":[{"condition":"NoCondition","value":"$1,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/setting-up-scholarships-prizes.html","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700800001_financial_services_and_support_for_students","n":"Financial services and support for students","o":"700800001","about":"We understand that studying can be tough on your finances and leave you in a difficult situation. You can apply for emergency and hardship support online for temporary assistance if financial difficulties are impacting your studies at AUT, or you can talk to us to discuss your situation. AUT’s Student Financial Emergency and Hardship Support can help you with essential living costs, including: We can provide food and transport vouchers, an AUT wallet voucher to use at the AUT cafés or for the AUT shuttle, a direct payment to your bank account, a direct payment to a third-party creditor (for example a power company), loan laptops and data packages for study purposes.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"You can apply online by completing the form below:","url":"https://www.aut.ac.nz/study/fees-and-scholarships/financial-assistance-for-aut-students","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_massey_university_food_technology_undergraduate_scholarship","n":"Massey University Food Technology Undergraduate Scholarship","o":"700311001","about":"The study of food technology is science, nutrition, and technology-based. It combines fundamental sciences, mathematics and chemistry – and the more applied sciences – with business and management. At the end of the four-year qualification, you will be able to move directly into key roles in the food industry such as product development, process improvement or food engineering. Massey’s food technology qualification combines your passion for food, nutrition and creativity, with practical sciences to ensure that you understand food from all perspectives. It teaches you the fundamental and applied skills that you will need in your exciting career in food science and technology. The value of the scholarship is up to $6,000 to be dispersed as follows:","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$6,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 June 2026","closing":"1 September 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-food-technology-undergraduate-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Your academic achievements to date may also be taken into consideration"},"rounds":[]},{"i":"700122001_undergraduate_scholarships_for_international_students","n":"Undergraduate scholarships for international students","o":"700122001","about":"A Scholarship of up to $20,000 toward compulsory tuition fees for new international students who have attended a New Zealand secondary school or kura, and who are enrolling in the first year of an undergraduate degree at Waipapa Taumata Rau, University of Auckland. A Scholarship of up to $10,000 towards tuition fees for new international students from ASEAN countries enrolling in undergraduate degrees, masters degrees or postgraduate diplomas. A Scholarship of up to $20,000 towards tuition fees for new international students from India enrolling full-time in undergraduate degrees, PGDip or masters degrees.","levels":["Diploma","Masters","Postgraduate","Undergraduate"],"values":[{"condition":"International students","value":"$20,000"},{"condition":"NoCondition","value":"$20,000"}],"lengths":[{"condition":"International students","length":"Two Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/scholarship-types/scholarships-for-international-students/undergraduate-scholarships-for-international-students.html","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":[],"other":"An $8,000 Scholarship to support a domestic or international student enrolling in the second or subsequent year of an undergraduate degree who has achieved academically but who is experiencing hardships or who may have been disadvantaged due to their personal circumstances"},"rounds":[]},{"i":"700311001_murray_and_terry_scholarship","n":"Murray and Terry Scholarship","o":"700311001","about":"This scholarship is supported by a combined fund from a gift from F. Terry of Ngongotaha in memory of his son, George Harold Terry, a graduate of Massey Agricultural College, who was killed in action in Italy in 1944; and from a bequest made from the will of Janet Murray of Auckland. This is a postgraduate scholarship. You will be enrolled in a postgraduate degree or a postgraduate diploma. The focus of your study will be in disciplines relevant to agriculture and/or horticulture as outlined in this award's regulations. Include the following with your application:","levels":["Diploma","Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/murray-and-terry-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a postgraduate degree or a postgraduate diploma"},"rounds":[]},{"i":"700122001_types_of_scholarships","n":"Types of scholarships","o":"700122001","about":"Find out about some of the different types of scholarships on offer If you are enrolled in an undergraduate degree at the University of Auckland, you can apply for a wide range of scholarships. Students enrolled in or intending to enrol in postgraduate study are encouraged to apply for other scholarships.","levels":["PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/scholarship-types.html","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"If you are enrolled in an undergraduate degree at the University of Auckland, you can apply for a wide range of scholarships"},"rounds":[]},{"i":"700311001_john_perrin_scholarship","n":"John Perrin Scholarship","o":"700311001","about":"Perrin Ag Consultants Ltd is a full-service agribusiness advisory and management consultancy firm with over 30 years of experience, based in Rotorua, but servicing the wider Bay of Plenty, Waikato and King Country. Perrin Ag wishes to offer an annual scholarship of up to $3,000 for a promising individual to continue agriculture and horticulture science studies at undergraduate, post-graduate diploma or Honours level at either Lincoln, Waikato or Massey Universities. Applicants must be enrolled in your 2nd year or later in an undergraduate degree or enrolled in an Honours degree or postgraduate diploma in the field of agriculture, horticulture or related science studies at either Lincoln, Waikato or Massey Universities When selecting a recipient, the panel will consider academic performance","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"30 Years"}],"opening":"1 November 2026","closing":"31 March 2027","entry":"Applications open 1 November 2026 and close 31 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/john-perrin-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must be enrolled in your 2nd year or later in an undergraduate degree or enrolled in an Honours degree or postgraduate diploma in the field of agriculture, horticulture or related science studies at either Lincoln, Waikato or Massey Universities"},"rounds":[]},{"i":"700122001_support_for_scholarship_students","n":"Support for scholarship students","o":"700122001","about":"Congratulations on receiving a scholarship from the University of Auckland! We're excited to support  you on your study journey. Starting uni can feel overwhelming sometimes, but you're not alone. This page gives you the basics on how scholarships work, how to keep your scholarship, and where to get help if you need it. Scholarship payments are tax-free (as long as you use it for study-related costs). You can spend it on things like:","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/support-for-scholarship-students.html","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Stay enrolled in an  eligible programme  (let the Scholarships Office know if you change)"},"rounds":[]},{"i":"602257001_paying_your_fees","n":"Paying your fees","o":"602257001","about":"You need to pay fees to study most of our courses. This page includes information about what fees you may need to pay, how you can pay your fees, and what happens if you need to withdraw from your course. You can also find information about how to request that we complete forms for you if needed (for example for StudyLink, the Ministry of Social Development or for a scholarship). If you are a domestic learner, you may be eligible to have your fees subsidised through the Ministry of Education. Domestic learners include:","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"How to apply to enrolCourse start, end and withdrawal datesRecognising previous study and experienceEnglish language requirementsProviding proof of your identityTerms and conditions of enrolmentFees and fundingChanges to your enrolmentInternational and studying from overseas","url":"https://www.openpolytechnic.ac.nz/study-with-us/fees-and-funding/paying-your-fees-v2/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"602432001_forbidden","n":"Forbidden","o":"602432001","about":"You don't have permission to access this resource.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://tpp.ac.nz/assets/Explore/Awards-Scholarships/Cave-Creek-Scholarships-TOR.pdf/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_sir_paul_callaghan_doctoral_scholarship_in_chemistry_and_physics","n":"Sir Paul Callaghan Doctoral Scholarship in Chemistry and Physics","o":"700311001","about":"Sir Paul Callaghan was a world-renowned scientist and physicist, who believed that inspired entrepreneurs can change New Zealand as a country. The scholarship was established from the proceeds of the sale of Magritek business, founded by Professor Sir Paul Callaghan. We're looking for a domestic doctoral student. You will have admission into, or be studying within the first 12 months, of a PhD. You will be enrolled in or intending to enrol in a PhD in the discipline of Physics or Chemistry and be researching a topic that has the potential to contribute to New Zealand's economy.","levels":["PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$105,000"}],"lengths":[{"condition":"NoCondition","length":"3 Years"}],"opening":"1 April 2027","closing":"1 June 2027","entry":"Applications open 1 April 2027 and close 1 June 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/sir-paul-callaghan-doctoral-scholarship-in-chemistry-and-physics/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in or intending to enrol in a PhD in the discipline of Physics or Chemistry and be researching a topic that has the potential to contribute to New Zealand's economy"},"rounds":[]},{"i":"600737001_government_feesfree","n":"Government Fees-Free","o":"600737001","about":"EIT is delighted to be one of the New Zealand tertiary institutions to offer free tuition for eligible first time tertiary learners. You may be able to get Fees Free after youcompleteyour first eligible qualification or programme. Fees Free covers fees for the final year of tertiary study or final 2 years of work-based learning. To get Fees Free, you must start your final year on or after 1 January 2025, and complete your qualification or programme by 31 December 2026.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"2 Years"}],"opening":"1 January 2025","closing":"31 December 2026","entry":"Public ServicesScholars Restaurant and CaféREFRESH Beauty Therapy ClinicSalon ELITE and FadeIT Barber ShopRevive Massage ClinicFacility HireSport Science ServicesŌtātara Children's CentreToru Restaurant and Hub CaféPortalsStaff WebmailStudent WebmailMy EITEIT OnlineMe@EITNew Staff InductionProgramme TimetablesStaff FarmEduroamLinkedIn LearningReport an Incident or HazardJobs @ EITEnrolment InfoStudent Handbook2027 ProspectusYouth Scholarship Application FormInternational Student Application FormInternational Student Refund PolicyApply OnlineStudent Services Levy FAQsStudent ServicesCurrent StudentsFuture StudentsInternationalLibraryGraduate Outcome SurveyStaff LinksStaff DirectoryHealth, Safety & WellbeingOther ResourcesGet ConnectedRequest an Enrolment PackNewsFacebookTwitterEIT LinkedIn ","url":"https://www.eit.ac.nz/students/futurestudents/govt-fees-free/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_prime_ministers_scholarship","n":"Prime Minister’s Scholarship","o":"600449001","about":"Become a global citizen with a Prime Minister’s Scholarship and travel to Latin America this summer. The Prime Minister's Scholarships for Latin America (PMSLA) are funded by the New Zealand Government and administered by Education New Zealand Manapou ki te Ao (ENZ). Since 2013, the Scholarships have enabled more than 2,400 New Zealanders to broaden their horizons through life-changing learning experiences in Asia and Latin America.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"18 Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/prime-ministers-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Be enrolled in a full time programme at Unitec"},"rounds":[]},{"i":"700311001_david_brundell_masters_scholarship","n":"David Brundell Master’s Scholarship","o":"700311001","about":"David Brundell completed a Bachelor of Horticulture at Massey in 1970 before going on to complete a Master of Horticulture (Subtropical Pomology and Agronomy) in 1974. His thesis topic focused on flower development of the kiwifruit. Following his graduation from Massey, David worked in a research role at the Ministry of Agriculture and Fisheries in Levin and later in Pukekohe. David’s varied career saw him being a floricultural consultant for the Commonwealth Secretariat in Jammu and Kashmir as well as various other consulting roles in floriculture and in the development of geophytes. Throughout his life David was an avid plant and crop collector, developer, producer, and trader. He had a lifelong interest in the commercial production of a wide variety of food, medicinal, and energy crops ","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$25,000"}],"lengths":[{"condition":"NoCondition","length":"5 Years"}],"opening":"15 October 2026","closing":"15 January 2027","entry":"Applications open 15 October 2026 and close 15 January 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/david-brundell-masters-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"This is a postgraduate scholarship, you will be enrolled in the Master of Horticulture (coursework or research stage) The value of the scholarship will be up to $25,000 per annum for full time students and prorated for part time students up to the value of $12,500 per year, should funds permit"},"rounds":[]},{"i":"700122001_applications_open_now","n":"Applications open now","o":"700122001","about":"If you are currently enrolled in Year 13 at a New Zealand secondary school or kura, you may be eligible for a scholarship for your first year of university study in 2027. Read more atSchool leaver and first-year scholarships. Applications close at midday on Wednesday 12 August 2026. Summer Research Scholarships are a great way to gain valuable research experience, work with leading researchers at the University of Auckland, enhance your career opportunities and help you think about pursuing postgraduate study.","levels":["Diploma","Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"Domestic students","value":"$10,000"},{"condition":"Targeted ethnicity criteria","value":"$10,000"},{"condition":"International students","value":"$5,000"},{"condition":"NoCondition","value":"$25,000"},{"condition":"Academic merit / GPA requirements","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"Three Years"},{"condition":"Domestic students","length":"18 Years"}],"opening":"12 August 2026","closing":"21 July 2026","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/applications-open-now.html","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":["Māori","Pasifika"],"other":"If you are currently enrolled in Year 13 at a New Zealand secondary school or kura, you may be eligible for a scholarship for your first year of university study in 2027"},"rounds":[]},{"i":"700311001_mary_mallon_memorial_scholarship","n":"Mary Mallon Memorial Scholarship","o":"700311001","about":"This scholarship was established in memory of Professor Mary Mallon, who died in 2006. She joined Massey University as a professor in human resource management in 2002. Professor Mallon gained her PhD from Sheffield Hallam University in England. We're looking for a New Zealand or international student who is undertaking a research thesis relevant to human resource management. You will be studying a postgraduate qualification to advance your career in human resource management. This is a postgraduate and doctoral scholarship. You will be enrolled in a research course in human resource management with the School of Management.","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$1,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"14 April 2027","closing":"30 May 2027","entry":"Applications open 14 April 2027 and close 30 May 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/mary-mallon-memorial-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"You will be enrolled in a research course in human resource management with the School of Management"},"rounds":[]},{"i":"700311001_massey_business_school_promising_student_assistance_bursary","n":"Massey Business School Promising Student Assistance Bursary","o":"700311001","about":"These bursaries were established in 2016 and are funded by the Massey Business School Development Fund. At least five bursaries will go to a student in each of the five schools, and one bursary each will be given to Māori, Pasifika and international students. We're looking for students who are facing financial hardship or other circumstances that may hinder them from progressing in their studies. These are undergraduate or postgraduate bursaries. You will be enrolled in a programme of study within the Massey Business School at undergraduate or postgraduate level.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"15 September 2026","closing":"31 October 2026","entry":"Applications open 15 September 2026 and close 31 October 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-business-school-promising-student-assistance-bursary/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":["Māori","Pasifika"],"other":"You will be enrolled in a programme of study within the Massey Business School at undergraduate or postgraduate level"},"rounds":[]},{"i":"700311001_pricewaterhousecoopers_pwc_undergraduate_food_and_fibre_scholarship_mo","n":"PricewaterhouseCoopers (PwC) Undergraduate Food and Fibre Scholarship (Māori)","o":"700311001","about":"Manukura is PwC’s dedicated network of kaimahi Māori and non-Māori who comprise one of the largest advisory teams for Māori in Aotearoa. This creates a unique value proposition in that it combines technical excellence within a te ao Māori context. Manukura operates under the principle of being a relationship builder; a connector and an interpreter that bridges the gap between te ao Māori and mainstream institutions. The strength of Manukura is that it is deeply woven through PwC Aotearoa in all parts of the business and offices. This creates an environment where Māori new joiners can see themselves reflected, supported and empowered from day one. PwC and Manukura recognise that Māori landowner’s have huge potential to contribute increasingly to the food and fibre sector to benefit Māori. G","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$7,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"22 June 2026","closing":"1 August 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/pricewaterhousecoopers-pwc-undergraduate-food-and-fibre-scholarship-m%C4%81ori/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_peter_turner_scholarship_in_contemporary_photography","n":"Peter Turner Scholarship in Contemporary Photography","o":"700311001","about":"The Peter Turner Scholarship was established in memory of the late Peter Turner; esteemed author, editor, publisher, curator, and former teacher at the Wellington School of Design. While in New Zealand he contributed to public knowledge and understanding of the medium of photography through writing, teaching, public lectures, and curated exhibitions. This annual scholarship honours and remembers his special regard for those photographic practices he termed lyric, personal, or poetic documentary. This is a postgraduate scholarship. You will be studying a Master of Design, Master of Fine Arts, or a Master of Māori Visual Arts with a focus on contemporary photography. You will preferably have a creative lens-based practice underpinned by social, cultural, political, or community concerns. Inc","levels":["Masters","Postgraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"4 February 2027","closing":"8 March 2027","entry":"Applications open 4 February 2027 and close 8 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/peter-turner-scholarship-in-contemporary-photography/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori"],"other":"You must be: a New Zealand or Australian permanent resident or citizen studying full-time studying a specific programme"},"rounds":[]},{"i":"700311001_john_alexander_milne_scholarship","n":"John Alexander Milne Scholarship","o":"700311001","about":"John Milne trained to be a veterinarian in Australia. He later moved to Dunedin, New Zealand where he successfully worked as a veterinary surgeon. Upon his death, John left a bequest of $100,000 to Massey University to be invested, with the interest being used to financially support master’s research students in the field of sheep reproduction. This is a postgraduate scholarship. You will be enrolled in a 90 or 120 credit research course as part of a master's degree with the School of Agriculture and Environment. Your research will be related to sheep reproduction either directly or indirectly (i.e. this might include systems modelling or farmer survey research which is focused on reproduction without doing a reproductive in-situ (i.e. with animals) study.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$100,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"23 February 2027","closing":"30 April 2027","entry":"Applications open 23 February 2027 and close 30 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/john-alexander-milne-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a 90 or 120 credit research course as part of a master's degree with the School of Agriculture and Environment"},"rounds":[]},{"i":"601558001_study_english","n":"Study English","o":"601558001","about":"Take advantage of our flexible intakes. We accept students almost every week. You can begin your course on any week in the year except during SIT holidays. You can begin your course almost any week of the year, except during public holidays. Placement test and orientation are conducted on Mondays in Invercargill and Queenstown. The placement test, offered free of charge, helps to ensure you are placed in the class that best matches your learning needs. Complete SIT's International Application form and send it to us with the required documents.","levels":["General"],"values":[{"condition":"NoCondition","value":"$330"},{"condition":"International students","value":"$280"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.sit.ac.nz/International/Subjects-Fees-Scholarships/Study-English","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":[],"other":"The curriculum is well-resourced and will guide your learning with a focus on Academic English"},"rounds":[]},{"i":"700311001_massey_university_pacific_success_scholarship_for_doctoral_students","n":"Massey University Pacific Success Scholarship for Doctoral Students","o":"700311001","about":"This scholarship provides support for Pacific students enrolled in doctoral studies at Massey. We're looking for Pacific students enrolled in doctoral study. You will demonstrate good character and community participation. You must be a domestic student from Pacific heritage/ethnicity","levels":["PhD / Doctorate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 November 2026","closing":"1 February 2027","entry":"Applications open 1 November 2026 and close 1 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-pacific-success-scholarship-for-doctoral-students/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"This scholarship provides support for Pacific students enrolled in doctoral studies at Massey"},"rounds":[]},{"i":"700311001_alistair_betts_scholarship","n":"Alistair Betts Scholarship","o":"700311001","about":"The Alistair Betts Scholarship was established to honour the memory of Alistair Betts, who, when employed by the New Zealand Dairy Board during the 1980's, pioneered access for New Zealand dairy products through South East and Southern Asia. We're looking for someone interested in international marketing of agribusiness products. This is a postgraduate scholarship. You will be enrolled full time or part time in agribusiness related study, undertaking research which relates to New Zealand exports.","levels":["Masters","Postgraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/alistair-betts-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"your academic transcripts for any tertiary study completed outside of Massey University"},"rounds":[]},{"i":"600449001_unitec_kura_kaupapa_and_rumaki_reo_scholarship","n":"Unitec Kura Kaupapa and Rumaki Reo Scholarship","o":"600449001","about":"The Unitec Kura Kaupapa and Rumaki Reo Scholarships were established in 2019 to support and engage Kura Kaupapa and Rumaki Reo graduates into tertiary studies at Unitec. The scholarship is designed to help cover education related costs and provide an opportunity to connect to various induction and mentoring opportunities, along with connecting recipients with Unitec’s Māori community. Opened04th June 2025 |Closed6thAugust2025 To be eligible for the Scholarship, an applicant must meet all of the following criteria:","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"24 Months"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/unitec-kura-kaupapa-and-rumaki-reo-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"601915001_english_language","n":"English Language","o":"601915001","about":"Our English language programmes are ideal for migrants and refugees who wish to improve their opportunities in both work and study in New Zealand. Students enter the programmes at a level that best corresponds to their current capability and can progress all the way through the New Zealand Certificates in English Language. Following completion, you can continue on to study at Wintec or beyond across a large array of programmes. We are an authorised  International English language testing centre and our students have the opportunity to take both academic and general IELTS, including ORS and OET exams.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"Domestic students","value":"$4,124"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"6 September 2025","closing":"4 October 2025","entry":"Refer to eligibility criteria.","url":"https://www.wintec.ac.nz/study-at-wintec/courses/english","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":[],"other":"We are an authorised  International English language testing centre and our students have the opportunity to take both academic and general IELTS, including ORS and OET exams"},"rounds":[]},{"i":"700122001_new_scholarships_prizes_and_awards","n":"New Scholarships, Prizes and Awards","o":"700122001","about":"Read about scholarships, prizes and awards that have been recently established. This $5,000 Award was established to honour the memory of Wednesday Davis, an exceptional marine scientist and beloved member of the University of Auckland community. Her legacy continues to inspire through this meaningful opportunity for emerging marine scientists. The main purpose of the Award is to motivate and support a woman student undertaking masters study in marine science, reflecting Wednesday’s dedication to marine conservation. The applicant’s involvement in volunteering and community activities, and potential to contribute to marine conservation will be central to the selection process.","levels":["Masters","Postgraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/new-scholarships--prizes-and-awards.html","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_catherine_baxter_dairy_scholarship","n":"Catherine Baxter Dairy Scholarship","o":"700311001","about":"This scholarship is funded from an endowment to Massey Agricultural College by Thomas Nimmo Baxter in 1933, an Auckland barrister and solicitor, in memory of his wife Catherine Baxter (nee Stuart) who died in 1930. It has been supplemented by funds provided by the organising committee of the Massey University Dairy Farmer Conference held in Taranaki in 1989. These are postgraduate scholarships. You will want to undertake research in the field of or related to dairy science. Include the following with your application:","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/catherine-baxter-dairy-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be: studying full-time an enrolled Massey University student undertaking research in dairy science"},"rounds":[]},{"i":"600449001_master_of_applied_science_biodiversity_management_scholarships","n":"Master of Applied Science (Biodiversity Management) Scholarships","o":"600449001","about":"These scholarships are available to support talented students enrolled in the Master of Applied Science (Biodiversity Management) at Unitec. Please refer to theMaster Scholarship Guidelinesfor details. The scholarship is open to both Domestic and International students.","levels":["Masters"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"2026 Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Application and fundingScholarships and AwardsHow to applyAcademic CalendarAdmission requirementsDo your apprenticeship with usFeesFunding your studyChange Enrolment","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/master-of-applied-science-biodiversity-management-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"These scholarships are available to support talented students enrolled in the Master of Applied Science (Biodiversity Management) at Unitec"},"rounds":[]},{"i":"600449001_heinga_equity_scholarship","n":"Āheinga Equity Scholarship","o":"600449001","about":"Unitec is committed to providing an inclusive, barrier free environment that celebrates diversity. The purpose of this scholarship is to encourage disabled and neurodivergent learners to pursue their studies at Unitec. This scholarship is open to new and continuing domestic students, studying on a full or part-time basis. Financial hardship has been identified by disabled and neurodivergent learners as a barrier to pursuing higher education. The financial and additional support that this scholarship offers is intended to help lessen this barrier by helping to support students with education related costs.  Disabled and neurodivergent students in level 3 to 8 programmes are encouraged to apply.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Complete the online application form. Support is available for ākonga through ourAccess4Success team, Careers Team or Scholarships team. Please book an appointment early and prior to the application deadline if you would like to discuss or seek support with your application:disabilityservices@unitec.ac.nzorhttps://guides.unitec.ac.nz/scholarships","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/aheinga-equity-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori","Pacific Islands"],"other":"Academic progress : Ākonga who are awarded the scholarship are expected to achieve Pass grades for all courses, unless exceptional circumstances prevail"},"rounds":[]},{"i":"600449001_diverse_gender_scholarship","n":"Diverse Gender Scholarship","o":"600449001","about":"The Diverse Gender Scholarship encourages and supports diverse gender students to pursue tertiary education at Unitec. Unitec is committed to providing an inclusive environment that celebrates diversity, by identifying and addressing barriers that diverse students face when engaged in tertiary study.  This scholarship is intended to address some of the unique barriers diverse gender students encounter. Opens:6th September 2025 |Closes12th February 2026","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply online using the form provided. Support is available for ākonga through our Careers Team orScholarships Team. Please book an appointment early and prior to the application deadline if you would liketo discuss or seek support with your application: https://guides.unitec.ac.nz/scholarships.","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/diverse-gender-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori","Pacific Islands"],"other":"applied to study or are enrolled in a relevant course at Unitec"},"rounds":[]},{"i":"601047001_scholarships_and_grants","n":"Scholarships and grants","o":"601047001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Be application ready","url":"https://www.manukau.ac.nz/student-life/current-students/tools-and-resources/student-financial-assistance/scholarships-and-grants","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_good_wool_hunting_textile_design_scholarship","n":"Good Wool Hunting Textile Design Scholarship","o":"700311001","about":"Good Wool Hunting is a retailer of NZ and imported yarns. We are less than a 5-minute drive out of Greytown, in the Wairarapa. We love crafting with natural fibres - spinning, weaving, knitting and crocheting. We also dye yarn with natural dyes and with acid dyes under the brand Greytown Fibre Co. with yarn sourced from New Zealand and abroad. Good Wool Hunting values the mental health benefits that come from crafting and would like to encourage others to develop a love of crafting with fibre as well. We're looking for someone with a passion for textiles and experience with spinning, weaving, knitting, or crocheting. This is an undergraduate scholarship. You will be studying the Bachelor of Design or Bachelor of Design (Honours) majoring in Textile Design.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"28 November 2026","closing":"28 February 2027","entry":"Applications open 28 November 2026 and close 28 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/good-wool-hunting-textile-design-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"When selecting our recipient, we will consider your academic background in your first year of the degree"},"rounds":[]},{"i":"700311001_sir_james_wattie_scholarship_for_food_technology","n":"Sir James Wattie Scholarship for Food Technology","o":"700311001","about":"The Sir James Wattie Scholarship for Food Technology is funded by Kraft Heinz, the founder of the food processing company Wattie’s, to support Bachelor of Food Technology with Honours students. We're looking for a candidate with a passion for food technology. This is an undergraduate scholarship. You will be entering your first year (i.e. 100 level) of a Bachelor of Food Technology (Hons) in the year following the award of the scholarship.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"Four Years"}],"opening":"30 August 2026","closing":"8 December 2026","entry":"Applications open 30 August 2026 and close 8 December 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/sir-james-wattie-scholarship-for-food-technology/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be: entering the first year of your qualification studying a specific subject a New Zealand citizen studying full time"},"rounds":[]},{"i":"700311001_muriel_caddie_scholarship_in_vet_science","n":"Muriel Caddie Scholarship in Vet Science","o":"700311001","about":"The Muriel Caddie Scholarship in Veterinary Science supports students of exceptional merit who have completed the Bachelor of Veterinary Science at Massey University and who wish to undertake postgraduate study or training in some aspects of veterinary science. We're looking for a Bachelor of Veterinary Science graduate. This is a postgraduate scholarship. You will be entering postgraduate study in the area of veterinary science","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$4,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 February 2027","closing":"1 May 2027","entry":"Applications open 1 February 2027 and close 1 May 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/muriel-caddie-scholarship-in-vet-science/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must: have graduated with a Bachelor of Veterinary Science from Massey University be studying veterinary science at postgraduate level have the support from an academic member of staff"},"rounds":[]},{"i":"700311001_te_rau_puawai","n":"Te Rau Puawai","o":"700311001","about":"Ko tā Te Rau Puawai he whakawhanake i te hunga e mahi ana i te rāngai hauora hinengaro Māori. Ka tautokohia ngā tauira e whai ana i ngā tohu e hāngai ana ki te hauora hinengaro Māori.Te Rau Puawai is one of the most successful academic support programmes in the country. Over the last 20 years it has helped more than 400 health workers into the Māori mental health workforce. The programme is a partnership between Health Workforce NZ and Massey University. It gives bursaries and learning support to students who want to begin or complete a Massey University qualification in the areas of: Te Rau Puawai provides a scholarship and learning supporting including:","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"20 Years"}],"opening":"1 September 2026","closing":"31 October 2026","entry":"Applications open 1 September 2026 and close 31 October 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/te-rau-puawai/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Te Rau Puawai is one of the most successful academic support programmes in the country"},"rounds":[]},{"i":"700311001_massey_university_postgraduate_scholarship_semester_two","n":"Massey University Postgraduate Scholarship - Semester Two","o":"700311001","about":"The Massey University Postgraduate Scholarship developed from an ambition for Massey University postgraduate students to shape the future of New Zealand. In 2004, the postgraduate scholarships were developed and named in honour of Sir Alan Stewart KBE (8 December 1917 – 1 September 2004), the principal of Massey Agricultural College from 1959 to 1963 and founding vice-chancellor of Massey University from 1964 to 1983. Sir Alan guided the institution's transition from an agricultural college to full university. He is noted for building the university's internationally recognised agricultural programme, as well as for greatly expanding the university's distance programme to make tertiary education available to rural New Zealanders. In 1940, Stewart was awarded Massey's second Rhodes Scholars","levels":["PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"15 May 2027","closing":"15 July 2027","entry":"Applications open 15 May 2027 and close 15 July 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-postgraduate-scholarship-semester-two/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"When choosing our recipients, we will consider your academic achievements in your New Zealand based tertiary study record"},"rounds":[]},{"i":"700122001_postgraduate_scholarships_for_international_students","n":"Postgraduate scholarships for international students","o":"700122001","about":"In 2025, the Scholarship provides a tax-free stipend of up to $34,569pa, with an annual CPI adjustment to the stipend value, for up to 36 months of full-time study, plus tuition fees for international students who are eligible to study under thedomestic fees policy, and the single student Health Insurance compulsory charge. Students will be considered for a University of Auckland Doctoral Scholarship at the time of application for a place in their doctoral programme. Any student who is to be offered a place in a doctoral programme will be eligible for scholarship consideration prior to receiving their offer of place.","levels":["Diploma","Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"International students","value":"$34,569"},{"condition":"NoCondition","value":"$25,000"}],"lengths":[{"condition":"International students","length":"36 Months"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/scholarship-types/scholarships-for-international-students/postgraduate-scholarships-for-international-students.html","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":[],"other":"enrolled in postgraduate study in Music at the University of Auckland"},"rounds":[]},{"i":"601702001_make_a_financial_support_appointment_scholarships","n":"Make a financial support appointment (Scholarships)","o":"601702001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.witt.ac.nz/make-a-financial-support-appointment-scholarships","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_lois_turnbull_postgraduate_scholarship","n":"Lois Turnbull Postgraduate Scholarship","o":"700311001","about":"This scholarship was set up with funds provided by Dr Lois V. Turnbull, a former Massey University agriculture student. Dr Turnbull was encouraged to undertake postgraduate studies because she received scholarship support. We're looking for a female student who is studying a topic that will benefit agricultural or horticultural industries. This is a postgraduate scholarship. You will be studying a master's degree or PhD with a focus on agriculture or horticulture.","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/lois-turnbull-postgraduate-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You must be: studying full-time female a New Zealand citizen or permanent resident studying in a specific subject area"},"rounds":[]},{"i":"700122001_how_to_apply_for_a_scholarship","n":"How to apply for a scholarship","o":"700122001","about":"If your application needs a reference, verification or endorsement:","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/how-to-apply.html","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Already studied at the University of Auckland? No transcript needed Studied elsewhere (New Zealand or overseas)? Upload your transcripts (don't forget to include the grade scale) Coming from secondary school or kura? We will request your NCEA/CIE/IB results Some scholarships require a minimum GPA or rank score, check the regulations for each scholarship"},"rounds":[]},{"i":"600449001_gcsb_women_in_stem_scholarship","n":"GCSB Women in STEM Scholarship","o":"600449001","about":"The GCSB – Government Communications Security Bureau Women in STEM scholarship is aimed at second-year tertiary students and above (including Honours and Masters) who intend to take a full-time course of study in computer science, cyber security, technology, mathematics, computer engineering and/ or data science at any New Zealand tertiary institution. 2023 sees the scholarship in its seventh year, with a number of previous scholarship applicants also being subsequently appointed to the graduate programme. To keep New Zealand safe we need people who are skilled and knowledgeable in cyber security, technology, mathematics, computing engineering, and computer science. The value of this award is $10,000, which can be spread over three years depending on your study plans. Note, no more than $5","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"Three Years"}],"opening":"1 July 2023","closing":"1 October 2023","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/gcsb-women-in-stem-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"have enrolled, or been accepted into a full time degree majoring in science, technology, engineering or mathematics (STEM) at an approved NZQA accredited tertiary provider in New Zealand for the next academic year"},"rounds":[]},{"i":"700311001_melhop_trust_scholarship","n":"Melhop Trust Scholarship","o":"700311001","about":"Applicants should be no older than 30 years at the time of application, be of Italian heritage, and be engaged, or about to engage, in a formal course of study provided by a recognised educational establishment in one or more of the following fields: Applications, citing the course of academic study or project and demonstrating the applicant’s Italian heritage, are to be sent in writing to theSecretaryClub Garibaldi118 Tory StreetTe AroWellington 6451or toclubgaribaldi1882@gmail.com.The criteria for this annual award is available on request from the secretary, Marco Costa.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"30 Years"}],"opening":"17 March 2027","closing":"30 April 2027","entry":"Applications open 17 March 2027 and close 30 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/melhop-trust-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applications, citing the course of academic study or project and demonstrating the applicant’s Italian heritage, are to be sent in writing to the  Secretary Club Garibaldi 118 Tory Street Te Aro Wellington 6451 or to  clubgaribaldi1882@gmail"},"rounds":[]},{"i":"601558001_government_feesfree_policy","n":"Government Fees-Free Policy","o":"601558001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.sit.ac.nz/Government-Fees-Free","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_master_scholarships_for_mori_students","n":"Master Scholarships for Māori Students","o":"600449001","about":"These scholarships are available to support talented Māori students studying towards a Master qualification at Unitec Please read theMasters Scholarship Guidelinesfor full details.","levels":["Masters"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"2026 Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Application and fundingScholarships and AwardsHow to applyAcademic CalendarAdmission requirementsDo your apprenticeship with usFeesFunding your studyChange Enrolment","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/master-scholarships-for-maori-students/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700800001_fees_to_study_at_aut","n":"Fees to study at AUT","o":"700800001","about":"You need to pay tuition fees to study at AUT. The tuition fee varies depending on your programme and the combination of courses you study. Your exact fees will be calculated at the time of invoicing. There may also be other fees and charges you need to pay.If you're a domestic student and this is your first time doing tertiary education, you may be eligible to receive one year of full-time study fees-free. The fees published on this website provide an estimate for the range of costs associated with full-time study, based on estimates from the course selection of previous student enrolments within each qualification. Part-time students pay a proportion of the full-time fee. All fees are in NZ dollars and include GST.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"Domestic students","length":"One Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.aut.ac.nz/study/fees-and-scholarships/fees-to-study-at-aut","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_unitec_pacific_progression_scholarships","n":"Unitec Pacific Progression Scholarships","o":"600449001","about":"The purpose of this  scholarship, established in 2019, is to encourage Pacific students who have successfully completed their programme of study at Unitec, to continue their higher education in a new, higher level programme of study. The scholarship is open to domestic Pacific students across Unitec, in Level 4 to 8 programmes that take at least one semester of full-time study to complete. Unitec recognises that financial support is an important consideration for our ākonga in managing their next steps. The scholarship provides both financial support and mentoring opportunities in the first year of the new programme of study.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"Domestic students","length":"One Semester"},{"condition":"NoCondition","length":"One Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply online using the form provided.","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/unitec-pacific-progression-scholarships/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori","Pacific Islands"],"other":"The Team will add the ākonga GPA scores from their most recent semester of Unitec study to all eligible applications"},"rounds":[]},{"i":"601420001_student_hardship_funds","n":"Student Hardship Funds","o":"601420001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.whitireia.ac.nz/enrolment-information/funding-your-study/student-hardship-funds","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_massey_singapore_food_technology_phd_scholarship","n":"Massey Singapore Food Technology PhD Scholarship","o":"700311001","about":"Massey University has a long association with higher education in Singapore. From 2008 Massey had a relationship was with Singapore Polytechnic, and in 2016 the relationship moved to the Singapore Institute of Technology, in line with changes in Singapore Government policy. Graduates from the programme are highly desirable in the food industry in Singapore but a small number each year are interested in pursuing higher education. Scholarship holders will benefit from opportunities to work with world class scientists on cutting edge research in the fields of food and nutrition and contribute to the future of New Zealand's agri-food industry This is a doctoral scholarship. You will have admission into, or currently be enrolled in, a doctoral degree related to food research in New Zealand. Thi","levels":["PhD / Doctorate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$50,000"}],"lengths":[{"condition":"NoCondition","length":"3 Years"}],"opening":"1 July 2026","closing":"1 November 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-singapore-food-technology-phd-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will have admission into, or currently be enrolled in, a doctoral degree related to food research in New Zealand"},"rounds":[]},{"i":"700311001_pacific_science_and_technology_scholarships","n":"Pacific Science and Technology Scholarships","o":"700311001","about":"The Pacific Science and Technology Scholarships support new Pacific students entering tertiary study for the first time. The scholarship is valued at $5,000 per year for up to four years; a total of $20,000 across the recipients' time at Massey. We're looking for New Zealand citizens or permanent residents of Pacific heritage. You will have been involved in the local community through community service or community engagement, and will be of good character and well-rounded personality. These are undergraduate scholarships. You will be enrolling in the first year of an undergraduate degree related to the following disciplines related to applied science or technology including:","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$20,000"}],"lengths":[{"condition":"NoCondition","length":"Four Years"}],"opening":"1 June 2026","closing":"1 September 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/pacific-science-engineering-and-technology-scholarships/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"When selecting our recipients, we will consider your academic background and supporting documents"},"rounds":[]},{"i":"700311001_mori_distance_student_scholarship","n":"Māori Distance Student Scholarship","o":"700311001","about":"The Extramural Student Support Trust (ESST) was established in 2011 through a founding grant from the Extramural Students' Society (EXMSS), in recognition of the unique needs of distance students undertaking study at Massey University. The Trust is held in perpetuity by the Massey University Foundation to provide financial assistance, scholarships, and bursaries to distance students. Awards are made at least once a year, with the selection process administered by Massey's Scholarships Office on the recommendation of the Trust. These scholarships and bursaries reflect the Trust's enduring commitment to supporting the academic journeys of students who study primarily by distance. You will be studying an undergraduate or postgraduate qualification, primarily by distance mode. Include the foll","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"15 July 2026","closing":"15 August 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/m%C4%81ori-distance-student-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori"],"other":"These scholarships and bursaries reflect the Trust's enduring commitment to supporting the academic journeys of students who study primarily by distance"},"rounds":[]},{"i":"700311001_energy_education_trust_of_new_zealand_masterate_scholarship","n":"Energy Education Trust of New Zealand Masterate Scholarship","o":"700311001","about":"The Energy Education Trust of New Zealand Masters’ Scholarship was established to assist students to undertake full-time study in the fields of science, economics or engineering and related fields but with a specific interest in energy as it relates to the energy needs of New Zealand. We're looking for a postgraduate research student with an interest in the energy industry of New Zealand and a desire to pursue a career in this field. This is a postgraduate scholarship. You will be enrolled in a master's degree in science, economics, or engineering and be able to relate your study back to the energy needs of New Zealand.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$8,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"31 December 2026","closing":"31 March 2027","entry":"Applications open 31 December 2026 and close 31 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/energy-education-trust-of-new-zealand-masterate-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a master's degree in science, economics, or engineering and be able to relate your study back to the energy needs of New Zealand"},"rounds":[]},{"i":"700311001_parents_bursary_for_distance_students","n":"Parents Bursary for Distance Students","o":"700311001","about":"The Extramural Student Support Trust (ESST) was established in 2011 through a founding grant from the Extramural Students' Society (EXMSS), in recognition of the unique needs of distance students undertaking study at Massey University. The Trust is held in perpetuity by the Massey University Foundation to provide financial assistance, scholarships, and bursaries to distance students. Awards are made at least once a year, with the selection process administered by Massey's Scholarships Office on the recommendation of the Trust. These scholarships and bursaries reflect the Trust's enduring commitment to supporting the academic journeys of students who study primarily by distance. We're looking for an undergraduate or postgraduate student who is studying primarily by distance. You will be the","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"15 July 2026","closing":"15 August 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/parents-bursary-for-distance-students/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"These scholarships and bursaries reflect the Trust's enduring commitment to supporting the academic journeys of students who study primarily by distance"},"rounds":[]},{"i":"600449001_master_of_applied_practice_social_practice_scholarships","n":"Master of Applied Practice (Social Practice) Scholarships","o":"600449001","about":"These scholarships are available to support talented students enrolled in the Master of Applied Practice (Social Practice) at Unitec. Please refer to theMasters Scholarship Guidelinesfor full details. The scholarship is open to both Domestic and International students","levels":["Masters"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"31 January 2026","entry":"Application and fundingScholarships and AwardsHow to applyAcademic CalendarAdmission requirementsDo your apprenticeship with usFeesFunding your studyChange Enrolment","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/master-of-applied-practice-social-practice-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"These scholarships are available to support talented students enrolled in the Master of Applied Practice (Social Practice) at Unitec"},"rounds":[]},{"i":"700311001_rongotea_lions_club_student_assistance_fund","n":"Rongotea Lions Club Student Assistance Fund","o":"700311001","about":"This fund was established by the Rongotea & District Lions Club. We're looking for someone from the Manawatū region, preferably Rongotea or nearby. This is an undergraduate or postgraduate scholarship. You will study one of these subjects: - agriculture - horticulture - agribusiness - veterinary science.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,500"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/rongotea-lions-club-student-assistance-fund/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be from the Manawatū region"},"rounds":[]},{"i":"700311001_murray_richards_bursary","n":"Murray Richards Bursary","o":"700311001","about":"This bursary arises from a fund established in 2001 as a memorial to Murray Richards, an Associate Professor in the former Department of Horticulture at Massey University. He taught horticulture from 1946 to 1984. This is an undergraduate or postgraduate bursary. You will be studying towards a qualification with a focus on horticulture. Include the following with your application:","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/murray-richards-bursary/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"your academic transcripts for any tertiary study completed outside of Massey University"},"rounds":[]},{"i":"700311001_whiti_o_rehua_school_of_art_scholarship","n":"Whiti o Rehua School of Art Scholarship","o":"700311001","about":"Whiti o Rehua School of Art Scholarship was established by Massey University to provide support to promising applicants furthering their Fine Arts practice through the Bachelor of Fine Arts, Bachelor of Fine Arts Honours or Bachelor of Fine Arts,Mātauranga Māori. Typically, three scholarships are offered annually: You will be enrolling in the first year of one of the following:","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 June 2026","closing":"1 September 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/whiti-o-rehua-school-of-art-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must be: a New Zealand citizen or New Zealand resident"},"rounds":[]},{"i":"600449001_refugee_english_fund_grants","n":"Refugee English Fund Grants","o":"600449001","about":"We want to help you improve your English. Come and study English language for free. Dan Zhao- (dzhao@unitec.ac.nz) or call +64 9 815 4321 ext 7373 The Language Studies placement tests are held throughout the year.","levels":["General"],"values":[{"condition":"NoCondition","value":"$3,043"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/refugee-english-fund-grants/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_te_whatu_ora_te_pitomata_grants","n":"Te Whatu Ora- Te Pitomata Grants","o":"600449001","about":"Te Pitomata Grants support an inclusive workforce encouraging Māori into health careers.The Te Pitomata Grant categories include key areas within the healthcare sector in New Zealand. The grants can contribute to tuition fees, course related costs and living cost for eligible students of Māori descent, undertaking a course in a health-related field through an accredited New Zealand Qualifications Authority (NZQA) provider or through a provider supporting the education of future Rongoā Māori practitioners. Opens:9th March 2026 |Closes:1st April 2026","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/te-whatu-ora-te-pitomata-grants/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"· Enrolled in a related course at NZQA Level 7 and above"},"rounds":[]},{"i":"700311001_john_young_memorial_scholarship","n":"John Young Memorial Scholarship","o":"700311001","about":"Applicants will be New Zealand citizens or New Zealand permanent residents and intend to take up a career or be engaged in some occupation or profession relevant to the dairy industry, and will be attending a full time course in a tertiary institution. The level of individual grants paid is dependent on the numbers of successful applicants and range from $2000-$5000. The application process will be in two stages:","levels":["General"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"14 October 2026","closing":"27 November 2026","entry":"Applications open 14 October 2026 and close 27 November 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/john-young-memorial-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Academic performance in the previous year of the course for re-application by existing scholars"},"rounds":[]},{"i":"601702001_general_scholarship","n":"General Scholarship","o":"601702001","about":"We have several study programmes that are offered free at WITT this upcoming Semester (starts 20 July). See a list of free options below. If you would like any assistance, we're here to help! You can find out contact detailshere.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.witt.ac.nz/information-and-enrolment/funding-and-financing/free-study-options","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_john_hodgson_pastoral_science_scholarship","n":"John Hodgson Pastoral Science Scholarship","o":"700311001","about":"This scholarship is supported by funds accumulated under the Trade for Training Scheme established by Associate Professor Alex Chu between 1988 and 1996. It is named after Professor John Hodgson, former Head of the Agronomy Department at Massey University, in recognition of his leadership of, and contribution to, numerous pastoral projects conducted in China managed by Dr Chu. These projects included a United Nations Development Programme project in Guizhou. These are postgraduate scholarships. You will want to or be undertaking research in the field of or related to pastoral science. You must be studying in a specific subject area.","levels":["Masters","Postgraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/john-hodgson-pastoral-science-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be studying in a specific subject area"},"rounds":[]},{"i":"700311001_student_exchange_scholarship","n":"Student Exchange Scholarship","o":"700311001","about":"Student Exchange provides Massey students with the opportunity to study overseas for one or two semesters as part of their Massey University degree. You will have applied for the Massey University Student Exchange while enrolled in an undergraduate or postgraduate qualification. We're looking for a good ambassador for both Massey University and New Zealand. When choosing our recipients we will consider your academic merit and destination. Supporting information provided as part of your Student Exchange application may also be taken into consideration.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$1,000"}],"lengths":[{"condition":"NoCondition","length":"Two Semesters"}],"opening":"30 April 2026","closing":"31 July 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/student-exchange-and-global-citizen-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will have applied for the Massey University Student Exchange while enrolled in an undergraduate or postgraduate qualification"},"rounds":[]},{"i":"600449001_pacific_health_scholarships_2026","n":"Pacific Health Scholarships 2026","o":"600449001","about":"Te Whatu Ora Pacific Health Scholarships support the development of our Pacific health and disability workforce.The Scholarships contribute to tuition fees for eligible students of indigenous Pacific Islands descent undertaking a course in medical and health or disability-related studies. Open to full-time and part-time students. The Scholarships are a contribution toward tuition fees only. Accommodation costs, course related costs and study leave are not covered by the Scholarships. OpenDecember 2025 |Closes9th February 2026 at 11:59pm","levels":["General"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/pacific-health-scholarships-2023/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Pacific Islands","Indigenous"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_tpuna_maunga_authority_research_scholarship","n":"Tūpuna Maunga Authority Research Scholarship","o":"700311001","about":"The Tūpuna Maunga Authority has established this scholarship as a product of theTūpuna Maunga Education Strategy. The scholarship applies to research that aligns with the Tūpuna Maunga Values, that enhances and protects the mauri and wairua of the Tūpuna Maunga. From 2026, the Tūpuna Maunga Authority has partnered with the Māori Education Trust (MET) to increase funding for the Research Scholarship to $20,000 annually. MET is the largest national scholarship provider for Māori secondary and tertiary students and has awarded 65,000 scholarships since 1963.","levels":["Masters","PhD / Doctorate"],"values":[{"condition":"NoCondition","value":"$10,000"},{"condition":"Targeted ethnicity criteria","value":"$20,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"29 June 2026","closing":"30 August 2026","entry":"The Tūpuna Maunga Authority","url":"https://www.massey.ac.nz/study/scholarships-and-awards/t%C5%ABpuna-maunga-authority-research-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori"],"other":"You must be a member of a research or education institution"},"rounds":[]},{"i":"700311001_farmers_union_scholarship","n":"Farmers' Union Scholarship","o":"700311001","about":"This scholarship is from a donation by Sir James Wilson, the first president of the Farmers’ Union (1902 to 1920), now Federated Farmers of New Zealand. This is a postgraduate scholarship. You will be enrolled in a postgraduate degree or a postgraduate diploma, focusing your study on agriculture and/or horticulture as outlined in this award's regulations. Include the following with your application:","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/farmers-union-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a postgraduate degree or a postgraduate diploma, focusing your study on agriculture and/or horticulture as outlined in this award's regulations"},"rounds":[]},{"i":"600449001_archiland_architectural_and_construction_community_impact_scholarship","n":"Archiland Architectural and Construction Community Impact Scholarship","o":"600449001","about":"The purpose of the Scholarship is to provide financial support to a high achieving learner in a Building and Construction or Architecture related Level 6 and above programme, who is motivated to pursue a career in the industry and ensure outcomes that benefit Aotearoa’s communities in socially impactful ways. Unitec recognises that financial support is an important consideration for our ākonga in managing their study goals. The scholarship provides both financial support and industry mentoring opportunities provided by the Sponsor. Please have the following information ready before you start the application as you cannot save and return to it:","levels":["Diploma","Masters","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/archiland-architectural-and-construction-community-impact-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700277001_prizes","n":"Prizes","o":"700277001","about":"Find out more about the prizes offered in various Divisions, Faculties, Schools and subject areas. Prize information is updated annually in June. Most prizes require a minimum enrollment in the year of award of 60 points.","levels":["Diploma","Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"4 Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.waikato.ac.nz/study/scholarships/prizes/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":["Māori","Pacific Islands","Indigenous"],"other":"To the student with the highest GPA in ACCTN204-Accounting Information Systems"},"rounds":[]},{"i":"700311001_distance_postgraduate_scholarship","n":"Distance Postgraduate Scholarship","o":"700311001","about":"The Extramural Student Support Trust (ESST) was established in 2011 through a founding grant from the Extramural Students' Society (EXMSS), in recognition of the unique needs of distance students undertaking study at Massey University. The Trust is held in perpetuity by the Massey University Foundation to provide financial assistance, scholarships, and bursaries to distance students. Awards are made at least once a year, with the selection process administered by Massey's Scholarships Office on the recommendation of the Trust. These scholarships and bursaries reflect the Trust's enduring commitment to supporting the academic journeys of students who study primarily by distance. Doctoral students are not eligible for this scholarship. Include the following with your application:","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"15 July 2026","closing":"15 August 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/distance-postgraduate-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"These scholarships and bursaries reflect the Trust's enduring commitment to supporting the academic journeys of students who study primarily by distance"},"rounds":[]},{"i":"700311001_ng_pae_mhutonga_wellington_school_of_design_scholarship","n":"Ngā Pae Māhutonga Wellington School of Design Scholarship","o":"700311001","about":"The Ngā Pae Māhutonga Wellington School of Design Scholarship was established by Massey University to provide support to promising applicants furthering their practice in Fashion Design, Textile Design, Industrial Design, Spatial Design, Concept Design, Visual Communication Design or Integrated Design through the Bachelor of Design or Bachelor of Design Honours. Typically, six scholarships are offered annually: You will be enrolling in the first year of the Bachelor of Design of Bachelor of Design Honours in the year following the scholarship application.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 June 2026","closing":"1 September 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/ng%C4%81-pae-m%C4%81hutonga-wellington-school-of-design-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must be: a New Zealand citizen or New Zealand resident"},"rounds":[]},{"i":"700311001_scholarship_applications_advice_and_guidancetono_karahipi_he_whina","n":"Scholarship applications advice and guidance-Tono karahipi – he āwhina","o":"700311001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"It pays to be organised and plan ahead when it comes to scholarships.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/scholarship-applications-advice-and-guidance/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_te_waka_whakarei_career_changer_scholarship","n":"Te Waka Whakarei Career Changer Scholarship","o":"600449001","about":"A Te Waka Whakarei Career Changer scholarship supports you to change your career and follow your passion for te reo Māori. The scholarship provides financial assistance so the loss of income you experience while studying is not a barrier to obtaining a teaching qualification. The scholarship is designed to assist applicants studying to teach in Māori Medium immersion. If you are proficient in te reo Māori, have a wealth of life experience and want to become a kaiako, this could be the scholarship for you. Open19 September 2023 |Closes17 October 2023Eligibility CriteriaTo be eligible, you must:be a domestic student, i.e. a New Zealand citizen or Permanent Residentbe enrolled or intending to enrol in one of the approved initial teacher education qualifications listed on our websitebe an unqu","levels":["General"],"values":[{"condition":"NoCondition","value":"$30,000"}],"lengths":[{"condition":"NoCondition","length":"12 Years"}],"opening":"19 September 2023","closing":"17 October 2023","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/te-waka-whakarei-career-changer-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_professor_tony_parker_scholarship_in_industrial_design","n":"Professor Tony Parker Scholarship in Industrial Design","o":"700311001","about":"This scholarship is supported by research fees accumulated by former staff member and Emeritus Professor Tony Parker, Professor in Industrial Design, during his tenure at Massey University’s College of Creative Arts. Professor Parker’s Industrial Design research practice focused on aesthetically driven affective product design. This included product desirability, usability, experience, branding and innovation for improved user satisfaction. Research concentrated on strategically defining and integrating distinct, and aesthetically innovative, affective product attributes for agricultural, automotive and security products intended for global niche markets. His enduring collaboration with Gallagher Industries resulted in numerous commercially successful and international design award winning","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"30 November 2026","closing":"28 February 2027","entry":"Applications open 30 November 2026 and close 28 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/professor-tony-parker-scholarship-in-industrial-design/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Applicants for the Tony Parker Scholarship in Industrial Design must be: New Zealand citizens or permanent residents Enrolled or intending to enrol full time at the College of Creative Arts, Wellington Undergraduate applicants need to be majoring in Industrial Design (Hons) with a GPA of 7"},"rounds":[]},{"i":"700311001_ken_and_elizabeth_powell_scholarship","n":"Ken and Elizabeth Powell Scholarship","o":"700311001","about":"This scholarship is from a bequest to Massey University by Ken Powell, who had his own precision equipment business and his wife Elizabeth Powell, who was a registered nurse and midwife. Their bequest was to give \"people enthusiastic about technology an extra edge\". These are undergraduate and postgraduate scholarships. You will be undertaking research relating to the advancement of technology in the year of award.","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"15 March 2027","closing":"15 July 2027","entry":"Applications open 15 March 2027 and close 15 July 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/ken-and-elizabeth-powell-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You must be a New Zealand citizen or permanent resident who is undertaking research relating to the advancement of technology"},"rounds":[]},{"i":"700311001_mcewan_pacific_student_scholarship","n":"McEwan Pacific Student Scholarship","o":"700311001","about":"These scholarships were created in 2019 by Massey University alumni, Ross and Stephanie McEwan. Stephanie McEwan (née Duncan) graduated with a Bachelor of Technology (Honours) majoring in Food Technology in 1978, and Ross with a Bachelor of Business Studies majoring in Industrial Relations in 1980. We're looking for someone of Pacific Island descent who has evidence of good citizenship or community service. These are undergraduate scholarships. You will be enrolled in one of the following programmes:","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$8,000"}],"lengths":[{"condition":"NoCondition","length":"Three Years"}],"opening":"28 January 2027","closing":"31 March 2027","entry":"Applications open 28 January 2027 and close 31 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/mcewan-pacific-student-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Pacific Islands"],"other":"You will be enrolled in one of the following programmes: Bachelor of Business Bachelor of Nursing Bachelor of Agricultural Science Bachelor of AgriBusiness Bachelor of Horticultural and Plant Systems Bachelor of Veterinary Science Bachelor of Information Science Bachelor of Aviation Bachelor of Food Technology (Hons)"},"rounds":[]},{"i":"700311001_mba_awards","n":"MBA awards","o":"700311001","about":"A limited number of awards are available to help with your study towards your Master of Business Administration (MBA) full-time. Eligibility will be determined at time of admission application into the MBA (up to $6,000 if you meet all the criteria), with awards offered on a first-come, first-served basis. You will automatically be considered for this scholarship when you apply for admission into the MBA, so apply now!","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$6,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply for a Massey MBA","url":"https://www.massey.ac.nz/study/scholarships-and-awards/mba-awards/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_phyllis_irene_grey_fellowships_in_veterinary_science_postgraduate","n":"Phyllis Irene Grey Fellowships in Veterinary Science - Postgraduate","o":"700311001","about":"The Phyllis Irene Grey Fellowships were established under the terms of the will of the late Phyllis Irene Grey. We're looking for a female veterinary science student with an interest in animal health. This is a postgraduate scholarship. You will be undertaking postgraduate level research at Massey University.","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 February 2027","closing":"1 May 2027","entry":"Applications open 1 February 2027 and close 1 May 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/phyllis-irene-grey-fellowships-in-veterinary-science-postgraduate/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"a written reference on your academic abilities and research potential from an academic member of staff in the School of Veterinary Science"},"rounds":[]},{"i":"700311001_hurley_fraser_postgraduate_scholarship","n":"Hurley Fraser Postgraduate Scholarship","o":"700311001","about":"The funds for this award are derived from The John Alexander Hurley Scholarship (established from the will of Palmerston North solicitor Edward Hurley) and The Edith Fraser Agricultural and Horticultural Research Fund established in 1966. We're looking for someone who is studying in a field related to agriculture or horticulture. This is a postgraduate scholarship. You will be enrolled in a postgraduate degree or a postgraduate diploma. The focus of your study will be in disciplines relevant to agriculture and/or horticulture.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/hurley-fraser-postgraduate-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a postgraduate degree or a postgraduate diploma"},"rounds":[]},{"i":"700277001_the_summer_research_scholarship_programme","n":"The Summer Research Scholarship Programme","o":"700277001","about":"Dip your toes into the rewarding world of research with our 10-week Summer Research Scholarship Programme (full time). You will be supported by an academic supervisor and get hands-on in the creation of new knowledge, adding significant value to your CV. Jessie Burnette's summer research analysed persuasive language (directives) in #Covid19nz Twitter posts. David Simes' Summer Research found 2020's emergency online learning distressed students and disrupted study habits.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"13 July 2026","closing":"31 July 2026","entry":"Refer to eligibility criteria.","url":"https://www.waikato.ac.nz/study/scholarships/summer-research-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be supported by an academic supervisor and get hands-on in the creation of new knowledge, adding significant value to your CV"},"rounds":[]},{"i":"700311001_postgraduate_scholarships_for_antarctic_research","n":"Postgraduate Scholarships for Antarctic Research","o":"700311001","about":"Antarctica New Zealand recognises the value of Antarctica and the Southern Ocean as a unique environment for scientific research. We are committed to supporting the next generation of Antarctic scientists to make valuable contributions to the international knowledge base and understanding of Antarctic and global ecosystems and processes. ThePostgraduate Research Scholarship Programmeis designed to support talented researchers to get off to the best possible start in their research careers, focussing on Antarctic and Southern Ocean systems. Antarctica New Zealand is generously supported in this scholarship programme by Ella Yelich-O’Connor and New Zealand Post. Ella Yelich-O’Connor Antarctic Doctoral Scholarship","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$40,000"}],"lengths":[{"condition":"NoCondition","length":"Two Year"}],"opening":"9 February 2027","closing":"16 March 2027","entry":"Applications open 9 February 2027 and close 16 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/antarctica-nz-postgraduate-research-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"and Logistics support for one season of fieldwork in Antarctica (subject to programme availability, fieldwork must be aligned with an existing Antarctic field event) New Zealand Post Antarctic Scholarship New Zealand's presence in Antarctica is important to our nation and New Zealand Post has a long association with the continent – ever since Sir Edmund Hillary was postmaster at Scott Base in 1957"},"rounds":[]},{"i":"700311001_turners_and_growers_research_grant","n":"Turners and Growers Research Grant","o":"700311001","about":"This research grant was made possible following a donation by Turners and Growers Limited in 1982 to celebrate the 60th anniversary of their company. We're looking for someone who is passionate about improving the quality of fruit, vegetables and flowers being produced for both the local and export markets. This is a postgraduate grant. You will be enrolled full time and undertaking research in the area of fruit, vegetable, and flowers.","levels":["Masters","Postgraduate"],"values":[{"condition":"NoCondition","value":"$4,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/turners-and-growers-research-grant/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"your academic transcripts for any tertiary study completed outside of Massey University"},"rounds":[]},{"i":"601702001_scholarships","n":"Scholarships","o":"601702001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.witt.ac.nz/information-and-enrolment/funding-and-financing/scholarships#ScholarshipTips","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_lawson_robinson_hawkes_bay_scholarship","n":"Lawson Robinson Hawke's Bay Scholarship","o":"700311001","about":"The Hawke’s Bay A&P Society, owns and manages the Napier Port Hawke’s Bay Primary Sector Awards. These awards have a long history and contribute signiﬁcantly to the primary industry across the region, they tell the story of excellence within rural Hawke’s Bay and celebrate success, business innovation and growth. We welcome your entry and wish you luck with the process. The recipient must be a full-time student enrolled in a New Zealand tertiary institute in a programme related to land-based production industries at a Graduate or Postgraduate level. Applicants must be in their second to last or ﬁnal year of study when receiving this scholarship.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"1 October 2026","closing":"24 March 2027","entry":"Applications open 1 October 2026 and close 24 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/lawson-robinson-hawkes-bay-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"The recipient must be a full-time student enrolled in a New Zealand tertiary institute in a programme related to land-based production industries at a Graduate or Postgraduate level"},"rounds":[]},{"i":"600449001_kate_edgar_foundation_women_for_solomon_island_scholarship","n":"Kate Edgar Foundation – Women for Solomon Island Scholarship","o":"600449001","about":"This award, in memory of Pam Tenapiko, was made possible by a generous donation. The scholarship is intended to help support a woman from the Solomon Islands to study at an accredited tertiary institute in the Auckland region of New Zealand. In awarding this scholarship, the selection committee will consideration to: Download the full criteria and application form","levels":["General"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"18 Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/kate-edgar-foundation-women-for-solomon-island-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"the applicant’s academic record"},"rounds":[]},{"i":"700311001_international_students_financial_aid","n":"International students' financial aid","o":"700311001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.massey.ac.nz/study/fees-and-funding/international-students-financial-aid/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"601702001_scholarship_support","n":"Scholarship Support","o":"601702001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.witt.ac.nz/information-and-enrolment/domestic/career-and-scholarship-support","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_kate_edger_foundation_women_in_fine_arts_award_in_memory_of_carol_scho","n":"Kate Edger Foundation – Women in Fine Arts Award in Memory of Carol Schofield","o":"600449001","about":"This award in memory of Carol Schofield is made possible by a generous sponsorship from her family and friends. Carol was an artist and picture framer who was closely involved in Auckland’s art and gallery scene. The award is intended to provide financial assistance to a woman enrolled full-time in the third year or above of a Bachelor’s or postgraduate degree in Fine Arts, Visual Arts, or Design and Contemporary Art. Each applicant for these awards must submit their application on the current prescribed application form, together with the following: For more information and application forms, visitthe Kate Edger Educational Foundation","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,500"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/kate-edger-foundation-women-in-fine-arts-award-in-memory-of-carol-schofield/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"a certified copy or statutory declaration of her academic record (this can be in the form of a certified digital document from the tertiary institution)"},"rounds":[]},{"i":"700311001_research_funding_and_scholarshipshe_ptea_rangahau_me_ng_karahipi","n":"Research funding and scholarships-He pūtea rangahau me ngā karahipi","o":"700311001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.massey.ac.nz/research/research-funding-and-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_william_reed_scholarship","n":"William Reed Scholarship","o":"700311001","about":"We're looking for a former pupil of Palmerston North Boys’ High School. This is an undergraduate or postgraduate scholarship. You will want to or be studying a bachelor's degree, postgraduate diploma, or postgraduate degree with a focus on agriculture or horticulture. Include the following with your application:","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/william-reed-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be: a former pupil of Palmerston North Boys’ High School studying full-time studying agriculture or horticulture"},"rounds":[]},{"i":"700311001_gcsb_women_in_stem_scholarship","n":"GCSB Women in STEM Scholarship","o":"700311001","about":"To be eligible for the GCSB Tertiary Scholarship, applicants must be: More information including the application form can be found on theGCSB website. Open to those who identify as female in their second year of tertiary and above (including Honours, Masters and PhD) intending to take a full-time course of study in computer science, cyber security, technology, mathematics, computer engineering or data science at any New Zealand tertiary institution.","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"Three Years"}],"opening":"1 July 2026","closing":"1 October 2026","entry":"Download application form","url":"https://www.massey.ac.nz/study/scholarships-and-awards/gcsb-women-in-stem-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"To be eligible for the GCSB Tertiary Scholarship, applicants must be: A student aged over the age of 18 years who identifies as female In your second, or subsequent year of full time tertiary study (including Honours, Masters and PhD students) Have enrolled, or been accepted into a full time degree majoring in science, technology, engineering or mathematics (STEM) at an approved NZQA accredited tertiary provider in New Zealand for the next academic year"},"rounds":[]},{"i":"700311001_cambridge_veterinary_club_scholarships","n":"Cambridge Veterinary Club Scholarships","o":"700311001","about":"Cambridge Veterinary Club invites residents of the Cambridge area who are studying Veterinary Medicine/Nursing, or Agriculture/Animal Science with a focus on Production Animals or Animal Welfare to apply for 1 year scholarships. These scholarships are intended to assist with course fees/travel and/or accommodation expenses. While it is a 1 year scholarship, we invite applicants to reapply in subsequent years.","levels":["General"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"},{"condition":"Domestic students","length":"1 Year"}],"opening":"1 November 2026","closing":"1 December 2026","entry":"Applications open 1 November 2026 and close 1 December 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/cambridge-veterinary-club-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_k_ptea_scholarships","n":"Kā Pūtea Scholarships","o":"700311001","about":"Kā Pūtea Scholarships are awarded based on applicants’ academic achievements and their engagement with whānau, hapū or iwi-related activities. This Scholarship is open from 1 February to 1 April. The outcome of scholarship applications will be advised in May.","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$1,500"},{"condition":"Academic merit / GPA requirements","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"1 February 2027","closing":"1 April 2027","entry":"Applications open 1 February 2027 and close 1 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/k%C4%81-p%C5%ABtea-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Kā Pūtea Scholarships are awarded based on applicants’ academic achievements and their engagement with whānau, hapū or iwi-related activities"},"rounds":[]},{"i":"700311001_peter_hawkins_food_technology_scholarship","n":"Peter Hawkins Food Technology Scholarship","o":"700311001","about":"The Peter Hawkins Food Technology Scholarship was established in memory of Peter Hawkins who passed away in June 2024. Its purpose is to help the recipient become part of the New Zealand Food Industry, something which was dear to Peter’s heart. Peter founded Hawkins Watts Limited, one of New Zealand’s most respected and successful food ingredient businesses, in 1992. Peter was passionate about the food industry and was a member of the New Zealand Institute of Food Science and Technology (NZIFST) since 1977, including stints on the National Executive Committee, and was also the Chair of the Auckland Branch. Peter also managed the NZIFST national magazine “The Food Technologist” and chaired the Institute’s Publications Committee for Food NZ. Right to the end of his life, Peter saw the immens","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 November 2026","closing":"1 February 2027","entry":"Applications open 1 November 2026 and close 1 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/peter-hawkins-food-technology-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"When choosing our recipient we will consider your academic background"},"rounds":[]},{"i":"700311001_the_centenary_history_of_new_zealand_and_the_first_world_war_heritage_","n":"The Centenary History of New Zealand and the First World War Heritage Scholarship","o":"700311001","about":"The Centenary History Project (CHP) of New Zealand and the First World War is a partnership between Massey University, the New Zealand Defence Force and the Ministry for Culture and Heritage. It aims to produce definitive histories of New Zealand experiences during one of the deadliest conflicts in world history. We're looking for a postgraduate students researching a topic related to New Zealand’s involvement in and experiences of the First World War. This is a postgraduate scholarship. You will be studying a masters or doctoral degree.","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$4,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"16 January 2027","closing":"16 February 2027","entry":"Applications open 16 January 2027 and close 16 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/the-centenary-history-of-new-zealand-and-the-first-world-war-heritage-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You must be: studying full-time a New Zealand citizen or permanent resident undertaking a 120 credit research course with a focus on a topic related to New Zealand’s involvement in and experiences of the First World War"},"rounds":[]},{"i":"600449001_master_of_creative_practice_scholarships","n":"Master of Creative Practice Scholarships","o":"600449001","about":"These scholarships are available to support talented students studying towards a Master of Creative Practice programme at Unitec. Please read theMasters Scholarship Guidelinesfor full details. The scholarship is open to both Domestic and International students.","levels":["Masters"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"2026 Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Application and fundingScholarships and AwardsHow to applyAcademic CalendarAdmission requirementsDo your apprenticeship with usFeesFunding your studyChange Enrolment","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/master-of-creative-practice-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_graduate_women_north_shore_charitable_trust_scholarship","n":"Graduate Women North Shore Charitable Trust Scholarship","o":"700311001","about":"Graduate Women New Zealand believe in empowering women through education, advocacy and community. The purpose of this scholarship is to provide recognition and financial assistance to outstanding women who undertake postgraduate research. We are looking for a female students who are undertaking postgraduate research at the Albany campus, Massey University. Your research topic should contribute to the discipline, and to New Zealand as a whole.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"8 December 2026","closing":"31 March 2027","entry":"Applications open 8 December 2026 and close 31 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/graduate-women-north-shore-charitable-trust-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be: a New Zealand citizen female enrolled internally at the Albany campus Successful recipients are required to submit a written report to the Graduate Women North Shore Charitable Trust within 12 months of receiving the scholarship"},"rounds":[]},{"i":"600449001_nz_chinese_building_industry_association_nzcbia_excellence_scholarship","n":"NZ Chinese Building Industry Association (NZCBIA) Excellence Scholarship 2026","o":"600449001","about":"The NZCBIA Excellence Scholarship was established in 2018 to financially assist and recognise excellent students in fields of study relevant to the building industry, with the desire to support and increase the number of qualified professionals in the building industry. To be eligible for the Scholarship, an applicant must meet all of the following criteria: As part of the scholarship application an academic referee’s contact details are required.","levels":["Diploma","Masters","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,500"}],"lengths":[{"condition":"NoCondition","length":"One Semester"}],"opening":"21 May 2026","closing":"29 June 2026","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/nz-chinese-building-industry-association-nzcbia-excellence-scholarship-2025/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"As part of the scholarship application an academic referee’s contact details are required"},"rounds":[]},{"i":"700311001_clem_hill_memorial_scholarship","n":"Clem Hill Memorial Scholarship","o":"700311001","about":"Professor Clem Hill was the first professor of education at Massey University. He was instrumental in establishing a department that offers a variety of general and specialised qualifications from certificate to doctoral. He later became the first Dean of Education and was also a member of the Massey University Council. We're looking for a fully registered teacher active in early childhood, primary, or secondary school settings in New Zealand. This is a postgraduate scholarship. You will be enrolled full time or part time.","levels":["Diploma","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"30 December 2026","closing":"30 March 2027","entry":"Applications open 30 December 2026 and close 30 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/clem-hill-memorial-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"When choosing our recipients we will consider your academic achievements and the 'all round' quality of your undergraduate teacher education degree"},"rounds":[]},{"i":"700122001_scholarships_for_students_with_disabilities","n":"Scholarships for students with disabilities","o":"700122001","about":"The below list includes a range of undergraduate and postgraduate scholarships, administered by the University of Auckland and external organisations.* Applications normally close in April and October for study in the following year. The Award provides financial support to University of Auckland students who are part of the University’s equity groups while on an approved student exchange. Four Awards are made annually and are of the value of $6,000 each.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$20,000"},{"condition":"International students","value":"$8,000"},{"condition":"Domestic students","value":"$10,000"},{"condition":"Targeted ethnicity criteria","value":"$5,000"}],"lengths":[{"condition":"Domestic students","length":"Two Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/scholarship-types/scholarships-for-students-with-disabilities.html","eligibility":{"domesticOnly":true,"internationalOnly":true,"ethnicity":["Māori"],"other":"An $8,000 Scholarship to support an international or domestic student enrolling in the second or subsequent year of an undergraduate degree who has achieved academically but who is experiencing hardships or who may have been disadvantaged due to their personal circumstances"},"rounds":[]},{"i":"600449001_tul_takes_flight_scholarships","n":"Tulī Takes Flight Scholarships","o":"600449001","about":"The purpose of the Tuli scholarship is to acknowledge the ongoing importance of education for Aotearoa Pacific families and communities. The scholarship is intended to support Pacific people to reach their potential by reducing some financial barriers to study or training. There are scholarships for vocational and degree-level study and training in Aotearoa. Opened1stSeptember 2025 |Closes30 September 2025 To be eligible for these scholarships, you must be","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$32,000"}],"lengths":[{"condition":"NoCondition","length":"Three Years"}],"opening":"Open all year","closing":"30 September 2025","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/tuli-takes-flight-scholarships/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Pacific Islands"],"other":"To be eligible for these scholarships, you must be"},"rounds":[]},{"i":"600449001_fred_tschopp_landscape_architecture_scholarship","n":"Fred Tschopp Landscape Architecture Scholarship","o":"600449001","about":"This scholarship is available for those beginning or studying Master of Landscape Architecture The Fred Tschopp Senior Scholarship is made possible by a generous Endowment made by its Founder Fred Jr. and the New Zealand and California Tschopp Family. The award commemorates the life and achievements of Fred Tschopp Senior, a Swiss-American certified landscape architect who pioneered modern, innovative landscape architecture in New Zealand during the years 1929-1932. Fred Tschopp Snr. is thought to be the first trained and registered landscape architect who practised in this country. He is recognised in refereed publications as New Zealand’s first modern practitioner.","levels":["Diploma","Masters"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/fred-tschopp-landscape-architecture-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"Application for the scholarship closes on  October of the year prior to study  so please get your application in to the Academic Administration Team  academicadministration@unitec"},"rounds":[]},{"i":"700311001_bowler_ravensdown_scholarship_in_soil_science","n":"Bowler Ravensdown Scholarship in Soil Science","o":"700311001","about":"The Bowler Ravensdown Scholarship was established from combined funds from the memorial to Dermot G. Bowler, a Massey Agricultural College (later Massey University) staff member from 1946 to 1982, and funds established in 2011 from rebates on Ravensdown fertilisers bought by Massey University’s farms. This is a postgraduate scholarship. You will be enrolled in a postgraduate degree or postgraduate diploma and be studying soil science with the College of Sciences, Massey University. You must be enrolled full time in a postgraduate degree or diploma in agriculture or horticulture and be studying soil science.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/bowler-ravensdown-scholarship-in-soil-science/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a postgraduate degree or postgraduate diploma and be studying soil science with the College of Sciences, Massey University"},"rounds":[]},{"i":"601558001_english_scholarship","n":"English Scholarship","o":"601558001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://sit.ac.nz/International/International-Student-Scholarships/Zero-Fees-English-Scholarship","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_zonta_club_of_auckland_scholarships","n":"Zonta Club of Auckland Scholarships","o":"600449001","about":"The Zonta Club of Auckland offers financial support each year to female tertiary students who reside in Auckland. This year they are offering three discrete scholarships –Zonta Young women Business Leadership Awardof up to $1,000,celebrates excellence and recognizes outstanding achievements by women between 18-35 years of age who are driving innovation and creating an impact in the business world.Zonta women in STEM Awardof up to $1,000 to a woman aged 18-35 whouplifts innovation and celebrates the remarkable accomplishments of women between 18-35 years of age in science, technology, engineering, and mathematics (STEM) fields and acknowledges their groundbreaking research, pioneering discoveries, and/or exemplary contributions to advancing knowledge and innovation in a STEM field; and aChe","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$1,000"},{"condition":"International students","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"35 Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/zonta-club-of-auckland-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700122001_university_of_auckland_doctoral_scholarships","n":"University of Auckland Doctoral Scholarships","o":"700122001","about":"Find information about the doctoral scholarships offered by the University of Auckland. The University of Auckland Doctoral Scholarship (UoADS) is a competitive scholarship scheme in 4 rounds each year. This is what you can get: In 2026 the University of Auckland Scholarship comprises:","levels":["PhD / Doctorate"],"values":[{"condition":"NoCondition","value":"$35,468"}],"lengths":[{"condition":"NoCondition","length":"42 Months"}],"opening":"1 November 2025","closing":"1 February 2026","entry":"It’s easy! Any student who is offered a place in a doctoral programme will be considered for a University of Auckland Doctoral Scholarship. Just make sure you do not enrol in the programme before we have considered you for a scholarship and advised you of the outcome.When you apply for your doctoral programme, you will have the opportunity to confirm whether or not you also wish to be considered for a University of Auckland Doctoral Scholarship — you don’t need to apply separately.If you already have scholarship funding and/or don't want to be considered for this scholarship, confirm this in your application form so that your application can be processed as quickly as possible.If you are still completing your qualifying programme and/or have not yet received your final grades from your qua","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/scholarship-types/postgraduate-scholarships/doctoral-scholarships.html","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":["Māori"],"other":"Māori applicants with a New Zealand university qualifying programme GPA of 7"},"rounds":[]},{"i":"700311001_graham_chalmers_allen_memorial_scholarship_in_veterinary_science","n":"Graham Chalmers Allen Memorial Scholarship in Veterinary Science","o":"700311001","about":"This scholarship was established by Graham Chalmers Allen’s parents in memory of Graham, who met with a fatal accident in 1970 while he was a student at the Faculty of Veterinary Science. He wanted to be a horse veterinarian. We're looking for a vet student who has a passion for horses and equine studies. This is an undergraduate and postgraduate scholarship. You will be enrolled in a veterinary science programme.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 February 2027","closing":"1 May 2027","entry":"Applications open 1 February 2027 and close 1 May 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/graham-chalmers-allen-memorial-scholarship-in-veterinary-science/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a veterinary science programme"},"rounds":[]},{"i":"700122001_manaaki_new_zealand_scholarships","n":"Manaaki New Zealand Scholarships","o":"700122001","about":"Manaaki New Zealand Scholarships build potential leaders. Our scholars leave with a world-class education, lifelong friendships and vital skills to strengthen their careers and home countries. Manaaki New Zealand Scholarshipsare funded through the New Zealand Aid Programme and administered by the Ministry of Foreign Affairs and Trade, to help build sustainable development in partner countries and a lifetime connection with New Zealand. The purpose is for candidates to gain knowledge and skills through their study in specific subject areas that will assist in the development of their home country. Awardees are required to return to their home country for at least two years after the completion of their scholarship to apply these new skills and knowledge in government, civil society, or priv","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"Two Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/international-students/scholarships-loans-and-funding/manaaki-new-zealand-scholarships.html","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_mori_education_trust_scholarships_and_grants","n":"Māori Education Trust Scholarships and Grants","o":"600449001","about":"The objective of the Māori Education Trust is to encourage Māori into tertiary education, through the payment of grants and scholarships. They award multiple grants, across secondary, undergraduate, and postgraduate study. Applications are typically open from December to March each year. All applications are to be submitted via theMāori Education Trustwebsitewww.maorieducation.org.nz","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/maori-education-trust-scholarships-and-grants/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_macmillan_brown_agricultural_research_scholarship","n":"Macmillan Brown Agricultural Research Scholarship","o":"700311001","about":"John Macmillan Brown was born in Scotland in 1845. In 1874, he was selected as Professor of Classics and English, one of three foundation chairs at the newly established Canterbury College in Christchurch. He was Vice-Chancellor of the University of New Zealand from 1916 to 1923 and Chancellor from 1923 until his death in 1935. We're looking for a Massey University graduate. This is a doctoral scholarship. You will want to or be studying a PhD with a focus on agriculture or horticulture.","levels":["PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/macmillan-brown-agricultural-research-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"your academic transcripts for any tertiary study completed outside of Massey University"},"rounds":[]},{"i":"700311001_gym_access_grant_for_konga_mori","n":"Gym Access Grant for Ākonga Māori","o":"700311001","about":"Studying at a distance doesn’t mean missing out on campus life. To support your wellbeing while attending block courses, Te Rau Tauawhi is offering Ākonga Māori distance students a one week membership to the Massey University Recreation Centre on the campus you’re visiting. This grant provides free access to the gym, fitness classes, and recreation facilities, helping you stay active, reduce stress, and make the most of your time on campus. Invest in your wellbeing while you’re here connect, train, and recharge at Massey’s Recreation Centres.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/gym-access-grant-for-%C4%81konga-m%C4%81ori/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"To be eligible for the grant you will be: Ākonga Māori currently enrolled in a distance course at Massey University attending a block course on any Massey University campus Applications can be submitted at any time throughout the year"},"rounds":[]},{"i":"700311001_c_alma_baker_trust_postgraduate_scholarship","n":"C Alma Baker Trust Postgraduate Scholarship","o":"700311001","about":"Scholarships are valued at a maximum of $13,000 a year for masterate students and $20,000 a year for doctoral students. For masterate students, funding will be for one year (normally for a course including a significant research component); for doctoral students, awards may be for up to three years subject to satisfactory progress and the provision of regular reports. You will be enrolled or intending to enrol in masterate or doctoral programmes in the fields of agriculture, agritech or the study of rural society. Candidates must be New Zealand citizens, and graduates of a New Zealand university; awards are available for those intending to undertake postgraduate research either in New Zealand or overseas.","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$13,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 November 2026","closing":"1 February 2027","entry":"Applications open 1 November 2026 and close 1 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/c-alma-baker-trust-postgraduate-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Candidates must be New Zealand citizens, and graduates of a New Zealand university"},"rounds":[]},{"i":"700800001_aut_alumni_awards","n":"AUT Alumni Awards","o":"700800001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.aut.ac.nz/about/aut-awards-and-honours/aut-alumni-awards","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_the_ryoichi_sasakawa_young_leaders_fellowship_fund_sylff_postgraduate_","n":"The Ryoichi Sasakawa Young Leaders Fellowship Fund (Sylff) Postgraduate Scholarship","o":"700311001","about":"The Ryoichi Sasakawa Young Leaders Fellowship Fund (Sylff) was established in December 1991 from an endowment of the Nippon Foundation to Massey University. Sylff is a global programme aimed at nurturing leaders who initiate action, overcome differences and address contemporary issues facing our world. Massey University is one of 69 Sylff institutions globally and The Ryoichi Sasakawa Young Leaders Fellowships offered by Massey are for New Zealand postgraduate research students studying at any of the country’s 8 universities. In 1987 The Ryoichi Sasakawa Young Leaders Fellowship Fund (Sylff) was established with the goal of developing human resources, specifically by furthering the education of tomorrow's international leaders. Sylff is currently centrally administered by the Tokyo Foundat","levels":["Diploma","Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$31,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"12 January 2027","closing":"1 March 2027","entry":"Applications open 12 January 2027 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/the-ryoichi-sasakawa-young-leaders-fellowship-fund-sylff-postgraduate-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"The scholarship fund promotes excellence within the academic community and focuses on issues of immediate importance to New Zealand"},"rounds":[]},{"i":"700122001_scholarships_news","n":"Scholarships news","o":"700122001","about":"Read the latest news related to scholarships, including information on new scholarships and other funding opportunities. See what scholarships and awards you can currently apply for. Have you always wanted to carry out research overseas? A Fulbright Award could take you to a leading institution in the United States.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"9/07/2025","closing":"13/06/2025","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/scholarships-and-awards/scholarships-news.html","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Fulbright NZ Scholar Awards are for New Zealand academics, artists or professionals to lecture and/or conduct research at US institutions"},"rounds":[]},{"i":"700311001_dr_eric_ojala_postgraduate_scholarship_in_agricultural_policy_research","n":"Dr Eric Ojala Postgraduate Scholarship in Agricultural Policy Research","o":"700311001","about":"The Venture Trust Inc. (now known formally as the Eric Ojala Sub-Trust of the Massey University Foundation, and informally as the Eric Ojala Fund) was established in 1986. The aim of the founder (Dr Eric Ojala) was to encourage, promote and assist research and development in New Zealand agriculture and land based science, especially that involving agricultural policy and strategy, agricultural trade and markets, agricultural economics and farm management and food technology, production and innovation. The word \"agriculture\" is broadly interpreted to include any productive activity on rural land - including forestry and horticulture. In 2014 the Trustees transferred the funds into the Massey University Foundation. We are looking for a candidate who is researching agricultural policies. The ","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Years"}],"opening":"15 July 2026","closing":"15 September 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/dr-eric-ojala-postgraduate-scholarship-in-agricultural-policy-research/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You will be: a New Zealand citizen or permanent resident enrolled in, or intending to enrol in a master’s degree or doctoral degree at Massey University in the year of award"},"rounds":[]},{"i":"700311001_peter_densem_postgraduate_scholarship","n":"Peter Densem Postgraduate Scholarship","o":"700311001","about":"This scholarship was established in 2017 by Peter Densem from Tauranga marking the year he turned 100. Mr Densem was a teacher and principal and served in World War II as a Fleet Air Arm navigator. We're looking for talented, high-achieving students who would otherwise struggle to pay for their study. This is a postgraduate scholarship. You will already have completed your first year of study towards a master’s or doctoral degree with a focus on agriculture or horticulture.","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/peter-densem-postgraduate-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"your academic transcripts for any tertiary study completed outside of Massey University"},"rounds":[]},{"i":"600449001_betty_loughhead_soroptimist_scholarship_2025","n":"Betty Loughhead Soroptimist Scholarship 2025","o":"600449001","about":"Soroptimist International exists to inspire action and create opportunities to transform the lives of women and girls. The Betty Loughhead Soroptimist Scholarship provides financial assistance to women studying for a qualification to enter or re-enter the workforce or change occupation. Applicants will be notified of the trustees’ decision in late October or November 2024. Payment will be made on receipt of evidence of acceptance into your programme of study. For more information and to download an application form, please go to the webpageBetty Loughhead Soroptimist Scholarship Trust","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"25 Years"}],"opening":"1 July 2024","closing":"31 August 2024","entry":"For more information and to download an application form, please go to the webpageBetty Loughhead Soroptimist Scholarship Trust","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/betty-loughhead-soroptimist-scholarship-2025/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Enrolled in an NZQA -approved education programme, undertaken in NZ"},"rounds":[]},{"i":"700311001_garrick_latch_postgraduate_travel_grants","n":"Garrick Latch Postgraduate Travel Grants","o":"700311001","about":"Dr Garrick Latch completed a Master of Agricultural Science at Massey University in 1958. He was then awarded a Fulbright Scholarship that led to a PhD in plant pathology from the University of Wisconsin. Returning to New Zealand in 1960 Dr Latch joined the Department of Scientific and Industrial Research and established a sub-station of the Plant Disease Division in Palmerston North. He assisted plant breeders to develop disease resistance in grasses and legumes and also used pathogenic fungus for biological control of pasture insects. It was this work that brought Dr Latch to the attention of the Food and Agriculture Organisation which enlisted his help to develop a strain of fungus to control the coconut Rhinoceros beetle in Tonga and Samoa. The Garrick Latch Postgraduate Travel Grants ","levels":["Masters","PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/garrick-latch-postgraduate-travel-grants/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You must be enrolled in a PhD with a focus on plants/ plant pathology and be intending to undertake research related travel"},"rounds":[]},{"i":"600449001_bold_innovators_scholarship","n":"Bold Innovators Scholarship","o":"600449001","about":"One scholarship is available to support highly innovative recent Unitec Masters or Doctoral degree graduates to take the next step with an idea they have developed during their studies at Unitec. The award includes a $5,000 scholarship, a $500 weekly stipend (payable for up to 14 weeks), negotiated access to Unitec’s facilities (for example, the library, workshops, studios) and professional mentoring. Only New Zealand and Australian citizens and residents are eligible for this scholarship.","levels":["Masters","PhD / Doctorate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/bold-innovators-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_health_research_council_hrc_summer_studentships_ethics","n":"Health Research Council (HRC) Summer Studentships - Ethics","o":"700311001","about":"HRC is the major government-funded agency responsible for purchasing and coordinating health research and fostering the health research workforce in Aotearoa New Zealand. The HRC mission is to improve human health by promoting and funding health research. HRC purchase a range of health research, including biomedical, clinical, public health, health services, Māori and Pacific research. It also funds a range of health research career development awards. There are two ethics summer studentship categories to choose from: Applications forms can be downloaded fromHRC Gateway.","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$7,500"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"19 June 2026","closing":"11 August 2026","entry":"","url":"https://www.massey.ac.nz/study/scholarships-and-awards/health-research-council-hrc-summer-studentships-ethics/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_2026_scholarships_for_school_leavers","n":"2026 Scholarships for School Leavers","o":"600449001","about":"Unitec has two dedicated scholarships for School Leavers commencing full-time study at Unitec, and many other scholarships School Leavers may be eligible for – see the individual scholarships pages below. Unitec scholarships help cover education-related costs and provide opportunities to connect to various induction and mentoring opportunities. Please go to the respective pages below for scholarship details and information on how to apply. You may apply for any of the three scholarships you are eligible to be considered for. Each scholarship has different regulations. Please take the time to read through the regulations to find out if you are eligible to be considered for more than one of the scholarship programmes. This scholarship supports Māori ākonga new to Unitec pursue their educatio","levels":["General"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/2026-scholarships-for-school-leavers/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_new_zealand_institute_of_management_foundation_scholarship","n":"New Zealand Institute of Management Foundation Scholarship","o":"700311001","about":"The New Zealand Institute of Management Foundation was established to provide financial assistance to individuals, to assist them to undertake courses of study relating to management and leadership. More particularly, where individuals did not have an opportunity to be supported by their employer for professional development in the areas relating to management and leadership. Funding for the Trust and this Scholarship has been provided by the Founding Members and Friends of the Foundation, as well as members of NZIM. We're looking for a postgraduate student studying leadership and/or management, preferably concurrently employed in a managerial position These are postgraduate scholarships. You will want to or be studying towards a qualification with a focus on leadership or management.","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$15,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 November 2026","closing":"15 January 2027","entry":"Applications open 1 November 2026 and close 15 January 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/new-zealand-institute-of-management-foundation-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"When choosing our recipients, we will consider your academic achievements"},"rounds":[]},{"i":"700122001_scholarship_student_stories","n":"Scholarship student stories","o":"700122001","about":"Hard work and family support through his schooling in New Zealand led Jay to an International School Leaver Scholarship. Explore our range of scholarships exclusive for international students. New Zealand Scholarships build future leaders, equipped with the skills to benefit their home countries.","levels":["PhD / Doctorate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/international-students/meet-our-international-students/scholarship-student-stories.html","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_international_creative_excellence_masters_degree_scholarship","n":"International Creative Excellence Masters Degree Scholarship","o":"700311001","about":"The International Creative Excellence Masters Degree Scholarship acknowledges the creative excellence and strength of creative vision to support international students enrolling in the first year of a masters degree with theCollege of Creative ArtsMassey University. You will be a new international student who can demonstrate creative excellence through a portfolio. This is a postgraduate scholarship. In 2027 you will be enrolling in the first year of one of the following qualifications:","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$10,000"},{"condition":"International students","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"15 July 2026","closing":"15 October 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/international-creative-excellence-masters-degree-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"In order to be considered for this award you must be: an international student intending to enrol in the first year of a masters degree with the College of Creative Arts in semester one, February, 2027"},"rounds":[]},{"i":"600449001_ngti_whtua_rkei_scholarships","n":"Ngāti Whātua Ōrākei Scholarships","o":"600449001","about":"Ngāti Whātua Ōrākei Scholarships were established in 2021 to encourage Māori students to pursue tertiary education at Unitec. Registered members of Ngāti Whātua Ōrākei are invited to apply for this scholarship for study from a Level 3 Certificate through to a Masters Degree at Unitec. Open16th March 2026 |Closed15th April 2026 The Selection Committee will review all eligible applications and make award recommendations based on a combination of:","levels":["Diploma","Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,500"}],"lengths":[{"condition":"NoCondition","length":"One Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/ngati-whatua-orakei-scholarships/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_graduate_women_manawatu_postgraduate_scholarship","n":"Graduate Women Manawatu Postgraduate Scholarship","o":"700311001","about":"The purpose of the postgraduate scholarship is to provide recognition and financial assistance to outstanding women who undertake post-graduate study or research. Graduate Women New Zealand believe in empowering women through education, advocacy and community. This is a postgraduate scholarship. You will be enrolling in a master's degree or in the final year of a postgraduate honour's degree at Massey University. Include the following with your application:","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"2 March 2027","closing":"1 April 2027","entry":"Applications open 2 March 2027 and close 1 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/graduate-women-manawatu-postgraduate-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"a copy of your academic transcripts for any tertiary study completed outside of Massey University (if applicable)"},"rounds":[]},{"i":"700311001_c_v_fife_memorial_scholarship_soil_science","n":"C V Fife Memorial Scholarship - Soil Science","o":"700311001","about":"The C V Fife Memorial Scholarship arises from a fund established in memory of Dr Cliff V. Fife. He was a member of the Department of Soils and Field Husbandry from 1934 to 1961 and the first Head of the Department of Soil Science from 1961 to 1972. This is a postgraduate scholarship. You will be enrolled in a postgraduate degree or a postgraduate diploma. The focus of your study will be in disciplines relevant to soil science. Include the following with your application:","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$10,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/c-v-fife-memorial-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a postgraduate degree or a postgraduate diploma"},"rounds":[]},{"i":"700311001_william_lomis_cox_memorial_scholarship","n":"William Lomis Cox Memorial Scholarship","o":"700311001","about":"First awarded in 1958, the William Lomis Cox Scholarship was established by Norman Cox in the name of his late father. Mr Cox wanted to support Whakatane area students training to be teachers. He hoped they would return to Whakatane to share their knowledge and skills with the new generation of school students. The William Lomis Cox Memorial Scholarship supports Whakatane area students who wish to train as teachers, with emphasis on social science subjects. The scholarship is open to students who:","levels":["General"],"values":[{"condition":"NoCondition","value":"$15,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 July 2026","closing":"30 September 2026","entry":"Public Trust","url":"https://www.massey.ac.nz/study/scholarships-and-awards/william-lomis-cox-memorial-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_lovell_and_berys_clark_scholarships","n":"Lovell and Berys Clark Scholarships","o":"700311001","about":"The Lovell and Berys Clark Scholarships were established from a gift from the late Mr Lovell Clark and Mrs Berys Clark in December 2002. Mr and Mrs Clark, who farmed together in South Auckland for many years, wished to make a major contribution to the scholarship of students undertaking study at a postgraduate level. Mr Clark was never able to undertake formal tertiary study himself and wishes to make it possible for others to enjoy what he had missed. Mrs Clark completed a degree by distance at Massey University and values the opportunity she had. We’re looking for a domestic postgraduate student studying full time or part time. Students undertaking postgraduate studies in psychology, sociology, anthropology, media/film studies, women/gender studies will not be eligible.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 April 2027","closing":"1 June 2027","entry":"Applications open 1 April 2027 and close 1 June 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/lovell-and-berys-clark-scholarships/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You must be: a New Zealand citizen or permanent resident studying science, agriculture, humanities, or business at postgraduate level Students undertaking postgraduate studies in psychology, sociology, anthropology, media/film studies, women/gender studies will not be eligible"},"rounds":[]},{"i":"700277001_university_of_waikato","n":"University of Waikato","o":"700277001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.waikato.ac.nz/study/scholarships/find-a-scholarship/university-of-waikato-tauranga-campus-residential-scholarship/?stage=Stage","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"600449001_ng_taonga_mtauranga_o_ng_pou_mana_scholarships","n":"Ngā Taonga Mātauranga o Ngā Pou Mana Scholarships","o":"600449001","about":"Ngā Pou Mana are proud to be able to provide the Ngā Taonga Mātauranga o Ngā Pou Mana scholarships and awards to tauira and kaimahi Māori. Ngā Pou Mana have established yearly scholarships in collaboration with PHARMAC. The awards are to support Māori allied health workforce development, so that people can continue study and to grow professional and cultural practice. Unitec students who are studying in an allied health pathway, at any level,or studying to build their understanding of Te Ao Māori, are encouraged to apply for these scholarships. For an overview of the different scholarships offered, please go to theNgā Pou Mana Scholarshipspage. Open: 6th October 2023 |Close: 19th October 2023","levels":["Diploma","Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$1,500"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/nga-taonga-matauranga-o-nga-pou-mana-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"You must be of Māori descent and be able to provide some details of your whakapapa"},"rounds":[]},{"i":"700311001_heseltine_ecology_bursary","n":"Heseltine Ecology Bursary","o":"700311001","about":"The funds for the bursary have been donated by Massey University staff, Dr Ian Stringer and Associate Professor Alastair Robertson, from conservation-related contracts they held. In 2019, the Heseltine Trust provided an additional $75,000 to the corpus of the fund and the Ecology Bursary was renamed the Heseltine Ecology Bursary. This is a postgraduate scholarship. You will want to or be undertaking research in one of these subject areas: Include the following with your application:","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$75,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 June 2026","closing":"10 August 2026","entry":"Current Massey studentsLog in to the student portal and find theScholarships tab.Log in to the student portalNot currently enrolled at Massey?To apply for scholarships you will need access to the student portal. Get this by applying for the qualification you want to study.Apply to study at Massey","url":"https://www.massey.ac.nz/study/scholarships-and-awards/heseltine-ecology-bursary/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"an academic reference, preferably from your research supervisor"},"rounds":[]},{"i":"700277001_scholarship_faqs","n":"Scholarship FAQs","o":"700277001","about":"Find answers to common questions about applying for a University of Waikato scholarship, payments, doctoral scholarships, and more. If your question isn't answered here, ourScholarships Teamis happy to help.","levels":["PhD / Doctorate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"","url":"https://www.waikato.ac.nz/study/scholarships/scholarship-faqs/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_violet_wickham_memorial_bursary","n":"Violet Wickham Memorial Bursary","o":"700311001","about":"Violet Wickham (nee Zurcher) (1916-1988) was one of five children and grew up in Longburn, Manawatu on a dairy farm with her Swiss parents. Violet was deeply committed to helping those less fortunate than herself. Despite the demands of her own large family, she always found time to help other women and families in need. Her son Brian (born 1946) graduated from Massey with a Masters of Agricultural Science in 1972 and went on to complete a PhD in animal breeding and genetics at Cornell University, Ithaca, New York, USA in 1975. Brian has used his knowledge and skills to contribute to the field of farm animal breeding in New Zealand, Ireland and worldwide. The Violet Wickham Memorial Bursary was established by Brian Wickham in 2016. Like his mother, he believes in the value of education and","levels":["Masters","PhD / Doctorate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/violet-wickham-memorial-bursary2/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in an undergraduate degree in agriculture and will have completed a minimum of 120 credits towards your degree at the time of application"},"rounds":[]},{"i":"600449001_industry_scholarship","n":"Industry Scholarship","o":"600449001","about":"Unitec have generously provided Unitec students with opportunities for a scholarship at postgraduate level industry related research. Applications for this scholarship have now closed.","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$4,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/industry-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"601420001_scholarships","n":"Scholarships","o":"601420001","about":"Discover a variety of scholarships designed to support and fund your studies—whether you're eligible for open entry scholarships or those tailored to specific academic fields. Additional scholarships and grants can be found onStudySpy.","levels":["General"],"values":[{"condition":"NoCondition","value":"$96,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.whitireia.ac.nz/enrolment-information/funding-your-study/scholarships","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori","Pasifika"],"other":"Discover a variety of scholarships designed to support and fund your studies—whether you're eligible for open entry scholarships or those tailored to specific academic fields"},"rounds":[]},{"i":"700311001_william_broughton_bursary_in_new_zealand_literary_studies","n":"William Broughton Bursary in New Zealand Literary Studies","o":"700311001","about":"This bursary arises from a bequest to Massey University by Dr William Broughton, who was an academic staff member in the Department of English (later the School of English and Media Studies) from 1963 to 2004. Dr Broughton’s specialist area in teaching and research was in the literature of New Zealand. He died in 2016. We're looking for someone with success in English or expressive arts who would benefit from financial assistance. These are undergraduate and postgraduate bursaries. You will have recently completed, or be intending to complete, a paper in New Zealand literature as part of your study in an English or expressive arts programme.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"28 February 2027","closing":"27 April 2027","entry":"Applications open 28 February 2027 and close 27 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/william-broughton-bursary-in-new-zealand-literary-studies/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"This bursary arises from a bequest to Massey University by Dr William Broughton, who was an academic staff member in the Department of English (later the School of English and Media Studies) from 1963 to 2004"},"rounds":[]},{"i":"600737001_eit_shortlisted_for_prestigious_sustainability_awards_for_second_time","n":"EIT shortlisted for prestigious sustainability awards for second time","o":"600737001","about":"EIT is, for the second year in a row, a finalist in the prestigious Green Gown Awards, run by the Australasian Campuses Towards Sustainability (ACTS). One of only two of the country’s tertiary institutions to make it through to the final round of judging, EIT has been shortlisted in the Benefitting Society category for its community-focused Learning in Nature (LIN) project. The awards are open to all Australasian tertiary institutions and recognise exceptional sustainability initiatives. EIT’s entry last year described the development of the Ōtātara Outdoor Learning Centre (OOLC) on the Hawke’s Bay Campus and related activities, enabling Learning in Nature (LIN) within an immersive mindspace.","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.eit.ac.nz/research-innovation/sustainable-futures/learning-in-nature-space/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_massey_ventures_masters_enterprise_bursary","n":"Massey Ventures Master’s Enterprise Bursary","o":"700311001","about":"The Massey Ventures Master’s Enterprise Bursary is to support master’s students who are undertaking research with commercialisation potential. We're looking for someone who is researching an idea which has commercialisation potential and who has previously engaged with the Office of Enterprise, Massey Ventures Ltd. in relation to commercialising this research. This is a postgraduate bursary. You will be enrolled in, or eligible to enrol in a 90 credit or 120 credit research course under a master's degree at Massey University.","levels":["Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$15,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 January 2027","closing":"1 May 2027","entry":"Applications open 1 January 2027 and close 1 May 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-ventures-masters-enterprise-bursary/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in, or eligible to enrol in a 90 credit or 120 credit research course under a master's degree at Massey University"},"rounds":[]},{"i":"600449001_unitec_study_grants","n":"Unitec Study Grants","o":"600449001","about":"The Unitec Study Grant is available for current students who are experiencing financial difficulty and finding it hard to come up with the additional costs needed for essential course-related costs/materials. This could include photocopying and printing costs, textbooks, travel costs to practicums, or specialised equipment for your course. Students can apply for materials and expensesup to $500. Grants are not available for tuition fees, day-to-day travel, or living costs. International students are not eligible for this grant. Students studying short courses (less than 16 weeks) are ineligible for this funding.","levels":["General"],"values":[{"condition":"NoCondition","value":"$500"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Complete theonline Student Financial Assistance FormMake an appointment with aStudent Support Advisor","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/unitec-study-grants/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_massey_university_alumni_doctoral_scholarship","n":"Massey University Alumni Doctoral Scholarship","o":"700311001","about":"The Massey University Alumni Doctoral Scholarships support Massey graduates to undertake doctoral research. The scholarships are awarded on the basis of academic excellence and strategic research priorities, and are open to students who have completed study at Massey University. There are scholarships for full-time and part-time candidates enrolled in the Doctor of Philosophy (PhD) or our named doctorates. There are also scholarships for Māori and Pacific doctoral candidates. The expectation is that recipients of the Massey University Alumni Doctoral Scholarship will enrol in their doctoral study no later than 1 June of the year of award. When you apply you need to ask your supervisor to complete theSupervisor Support Template. You will need to upload the completed form in the Student Port","levels":["PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$90,000"}],"lengths":[{"condition":"NoCondition","length":"Three Years"},{"condition":"International students","length":"12 Months"}],"opening":"1 November 2026","closing":"1 February 2027","entry":"Applications open 1 November 2026 and close 1 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-alumni-doctoral-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori"],"other":"The scholarships are awarded on the basis of academic excellence and strategic research priorities, and are open to students who have completed study at Massey University"},"rounds":[]},{"i":"601420001_compulsory_student_services_fee_cssf","n":"Compulsory Student Services Fee (CSSF)","o":"601420001","about":"A CSSF is a fee that we charge domestic students to deliver services that help students succeed. This fee is included in your tuition fees. At Whitireia and WelTec the Compulsory Student Services fee (CSSF) is $375 per full-time student in 2025 and helps pay for the following student services:","levels":["General"],"values":[{"condition":"NoCondition","value":"$375"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.whitireia.ac.nz/enrolment-information/funding-your-study/compulsory-student-services-fee","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"Providing non-academic counselling, advice, and pastoral care"},"rounds":[]},{"i":"602548001_tauranga_crossing_scholarship","n":"Tauranga Crossing Scholarship","o":"602548001","about":"Tauranga Crossing are providing two scholarships to students enrolling for the first time at Toi Ohomai in Semester 2, 2026 and are Tauranga residents. The scholarship is aimed to help awardees with tuition fees, transport, study-related equipment including digital equipment, and other course-related and study costs. Applicants must be new students to Toi Ohomai, have a residential address within the Tauranga or Western Bay Council area, and be applying to study predominantly at the Windermere Campus.","levels":["General"],"values":[{"condition":"NoCondition","value":"$5,000"},{"condition":"Domestic students","value":"$5,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"May 25, 2026","closing":"July 5, 2026","entry":"Refer to eligibility criteria.","url":"https://www.toiohomai.ac.nz/services/fees-and-finance/scholarships/tauranga-crossing-scholarship","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Eligibility Applicants must be new students to Toi Ohomai, have a residential address within the Tauranga or Western Bay Council area, and be applying to study predominantly at the Windermere Campus"},"rounds":[]},{"i":"600449001_school_of_architecture_postgraduate_scholarships","n":"School of Architecture Postgraduate Scholarships","o":"600449001","about":"These Scholarships are available to support talented students enrolled in Master of Architecture, Master of Landscape Architecture and Master of Architecture (Professional) Programmes at Unitec. Please refer to theMaster Scholarship Guidelinesfor details. The scholarship is open to both Domestic and International students.","levels":["Masters","Postgraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"2026 Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Application and fundingScholarships and AwardsHow to applyAcademic CalendarAdmission requirementsDo your apprenticeship with usFeesFunding your studyChange Enrolment","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/school-of-architecture-postgraduate-scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"These Scholarships are available to support talented students enrolled in Master of Architecture, Master of Landscape Architecture and Master of Architecture (Professional) Programmes at Unitec"},"rounds":[]},{"i":"700311001_the_agricultural_life_sciences_phd_travel_grant","n":"The Agricultural Life Sciences PhD Travel Grant","o":"700311001","about":"We're looking for a PhD student undertaking research in agriculture, horticulture, or food technology. You will have passed your confirmation of registration event at the time of applying. You will be intending to partake in a research visit which will be of benefit to the applicant’s programme of study and will include collaborative research, sample collection, or analysis Include the following with your application:","levels":["PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$25,000"}],"lengths":[{"condition":"NoCondition","length":"Four Months"}],"opening":"1 December 2026","closing":"1 February 2027","entry":"Applications open 1 December 2026 and close 1 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/the-agricultural-life-sciences-phd-travel-grant/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700277001_scholarships","n":"Scholarships","o":"700277001","about":"The University of Waikato and our partners provide various scholarship and award options to help students cover fees and living expenses, as well as to foster academic and research excellence. A filtered list of both taught and research postgraduate scholarship opportunities. For students who have completed a degree and working towards higher study. Scholarships available for our international students studying at the University of Waikato.","levels":["Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"18 Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.waikato.ac.nz/int/study/scholarships/","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"The University of Waikato and our partners provide various scholarship and award options to help students cover fees and living expenses, as well as to foster academic and research excellence"},"rounds":[]},{"i":"700800001_university_scholarships_and_awards","n":"University scholarships and awards","o":"700800001","about":"There is a wide range of scholarships and awards available to AUT students at all stages of their studies.The AUT scholarships database holds searchable information about AUT scholarships and externally funded scholarships, as well as links to the application processes. You can search by name, level, subject area or by closing date. Set up a log-in with the GivME database if you want to see more results, save your searches, receive alerts if new scholarships meet your search criteria, set up a reminder and favourite scholarships. *Free access for AUT students through the AUT library","levels":["Masters","PhD / Doctorate"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.aut.ac.nz/study/fees-and-scholarships/scholarships-and-awards-at-aut","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":["Māori","Pacific Islands"],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_charles_and_ella_elgar_bursaries","n":"Charles and Ella Elgar Bursaries","o":"700311001","about":"These bursaries are provided from a Trust Fund established by the Will of the late Ella Grace Elgar who, with her husband Charles, farmed at \"Fernside\" near Featherston in the Wairarapa. We're looking for students who have served in the New Zealand Defence Force or who are the descendants of such discharged service men and women. This is an undergraduate and postgraduate bursary. Preference will be given to students who are studying agriculture or a related science.","levels":["Diploma","Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$1,750"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"20 November 2026","closing":"1 February 2027","entry":"Applications open 20 November 2026 and close 1 February 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/charles-and-ella-elgar-bursaries/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"an academic reference (optional)"},"rounds":[]},{"i":"600449001_te_pou_aupiki","n":"Te Pou Aupiki","o":"600449001","about":"Te Pou Aupiki Karahipi were established in 2019 to encourage Māori students who successfully complete their programme of study to continue their tertiary education at Unitec. Ākonga who have successfully completed a Level 3 to 7 programme at Unitec, who are progressing to a new higher level programme that takes at least one semester of full-time study to complete, are encouraged to apply. Unitec recognises that financial support is an important consideration for our ākonga in managing their next steps. The scholarship provides both financial support and mentoring opportunities in the first year of the new programme of study.","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Semester"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply online using the form provided. Support is available for ākonga through our Careers Team or Scholarships Team. Please book an appointment early and prior to the application deadline if you would like to discuss or seek support with your application:https://guides.unitec.ac.nz/scholarships","url":"https://www.unitec.ac.nz/application-and-funding/scholarships-and-awards/te-pou-aupiki/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":["Māori","Pacific Islands"],"other":"The Team will add the ākonga GPA scores from their most recent semester of Unitec study to all eligible applications"},"rounds":[]},{"i":"700311001_sinclair_cummings_veterinary_and_animal_sciences_scholarship","n":"Sinclair Cummings Veterinary and Animal Sciences Scholarship","o":"700311001","about":"The Sinclair Cummings Trust assists in promoting and encouraging veterinary and animal science studies relevant to high country farming. We're looking for a postgraduate student with the School of Agriculture and Environment or the School of Veterinary Science. You will preferably researching high country farming. This is a postgraduate scholarship. You will be studying veterinary science or animal science at postgraduate level.","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$15,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 August 2026","closing":"1 November 2026","entry":"Applications open 1 August 2026 and close 1 November 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/sinclair-cummings-veterinary-and-animal-sciences-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You must be: enrolled in postgraduate study within the School of Veterinary Science or the School of Agriculture & Environment willing to provide a written progress report six months after the research has commenced and a final report at the end of the project"},"rounds":[]},{"i":"700311001_bailey_bequest_bursary","n":"Bailey Bequest Bursary","o":"700311001","about":"The late Walter Henry Bailey was a retired farmer from Wellington. Massey University established these bursaries from funds provided by the Bailey Bequest. We're looking for postgraduate students who are facing financial difficulty. You can be enrolled in any postgraduate programme. Note, Doctoral students may not apply, but may be eligible for alternative hardship funding.","levels":["PhD / Doctorate","Postgraduate"],"values":[{"condition":"NoCondition","value":"$3,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"13 March 2027","closing":"26 April 2027","entry":"Applications open 13 March 2027 and close 26 April 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/bailey-bequest-bursary/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"You can be enrolled in any postgraduate programme"},"rounds":[]},{"i":"700311001_sasakawa_fellowship_fund_for_japanese_language_education_sffjle_postgr","n":"Sasakawa Fellowship Fund for Japanese Language Education (SFFJLE) Postgraduate Scholarship","o":"700311001","about":"The Sasakawa Fellowship Fund for Japanese Language Education (SFFJLE) was established in March 1995 by an endowment from the Nippon Foundation to Massey University. The Sasakawa Fellowship Fund for Japanese language education was established in 1995. It is funded from the interest earned on an endowment bestowed on Massey University by theNippon Foundation Fund for Japanese Language Education Programme(NF-JLEP), (then the Sasakawa Foundation). The purpose of the fund is to foster Japanese language in New Zealand through the training of Japanese language teachers and the provision of fellowships to students pursuing Japanese related studies. Eleven institutions across six countries have been recipients of similar endowments by the Nippon Foundation. In addition to Massey they are: - Univers","levels":["Diploma","Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$15,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"12 January 2027","closing":"1 March 2027","entry":"Applications open 12 January 2027 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/sasakawa-fellowship-fund-for-japanese-language-education-sffjle-postgraduate-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You must: be a New Zealand citizen or permanent resident be enrolled in or eligible to enrol in a master's research degree in Japanese studies"},"rounds":[]},{"i":"601558001_scholarships","n":"Scholarships","o":"601558001","about":"Details of the scholarship are available on the provider's official page.","levels":["General"],"values":[{"condition":"NoCondition","value":"Refer to website"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.sit.ac.nz/Scholarships/PID/6768/evl/0/CategoryID/68/CategoryName/Scholarships-for-Women","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"Applicants must meet academic admission standards."},"rounds":[]},{"i":"700311001_massey_university_rainbow_postgraduate_scholarship","n":"Massey University Rainbow Postgraduate Scholarship","o":"700311001","about":"This scholarship provides support for students enrolled in their postgraduate studies at Massey University – with a particular focus on students working on rainbow-related research or with a demonstrable passion for and commitment to takatāpui and rainbow inclusion. Preference will be given to students who demonstrate: The scholarship is awarded by the Rainbow New Zealand Charitable Trust with input from the Massey University Rainbow and Takatāpui Advisory Group.","levels":["Postgraduate"],"values":[{"condition":"NoCondition","value":"$4,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 October 2026","closing":"31 October 2026","entry":"Applications open 1 October 2026 and close 31 October 2026.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/massey-university-rainbow-postgraduate-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"This scholarship provides support for students enrolled in their postgraduate studies at Massey University – with a particular focus on students working on rainbow-related research or with a demonstrable passion for and commitment to takatāpui and rainbow inclusion"},"rounds":[]},{"i":"700311001_waitawhiti_memorial_postgraduate_scholarship","n":"Waitawhiti Memorial Postgraduate Scholarship","o":"700311001","about":"This scholarship is supported by a gift from Charles and Margaret Richardson, who farmed at Waitawhiti Station near Eketahuna. The scholarship is in memory of their sons, who both attended Massey Agricultural College. Graham Speedy Richardson was a member of the Royal New Zealand Air Force and died in 1944. Paul James Richardson was shot in a farm accident. This is a postgraduate scholarship. You will be enrolled in a postgraduate degree or a postgraduate diploma. The focus of your study will be in disciplines relevant to agriculture and/or horticulture. Include the following with your application:","levels":["Diploma","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/waitawhiti-memorial-postgraduate-scholarship/","eligibility":{"domesticOnly":true,"internationalOnly":false,"ethnicity":[],"other":"You will be enrolled in a postgraduate degree or a postgraduate diploma"},"rounds":[]},{"i":"700122001_countryspecific_scholarships_and_funding","n":"Country-specific scholarships and funding","o":"700122001","about":"The International Office works with the following external scholarship agencies and government bodies to provide opportunities for international students who meet admission entry criteria. Doctoral Project Opportunities 2025.Size: 4.0 MB.Type:PDF. Document Description:Download this brochure to view a selection of projects and supervisors currently available.","levels":["Masters","PhD / Doctorate","Postgraduate","Undergraduate"],"values":[{"condition":"International students","value":"$20,000"}],"lengths":[{"condition":"NoCondition","length":"1 Year"}],"opening":"Open all year","closing":"Refer to website","entry":"Refer to eligibility criteria.","url":"https://www.auckland.ac.nz/en/study/international-students/scholarships-loans-and-funding/country-specific-scholarships-and-funding0.html","eligibility":{"domesticOnly":false,"internationalOnly":true,"ethnicity":[],"other":"The DAAD funds further academic qualifications of outstanding German undergraduate and postgraduate students, young academics and researchers"},"rounds":[]},{"i":"700311001_charles_elgar_scholarship","n":"Charles Elgar Scholarship","o":"700311001","about":"This scholarship was established under the terms of the will of Ella Grace Elgar and is named for her husband, who farmed at Fernside near Featherston. We're looking for someone who is domiciled in New Zealand and preferably from the Wairarapa area. This is a postgraduate scholarship. You will be studying a postgraduate degree or diploma related to agriculture of horticulture.","levels":["Diploma","Masters","Postgraduate","Undergraduate"],"values":[{"condition":"NoCondition","value":"$2,000"}],"lengths":[{"condition":"NoCondition","length":"One Year"}],"opening":"1 December 2026","closing":"1 March 2027","entry":"Applications open 1 December 2026 and close 1 March 2027.","url":"https://www.massey.ac.nz/study/scholarships-and-awards/charles-elgar-scholarship/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":[],"other":"your academic transcripts for any tertiary study completed outside of Massey University"},"rounds":[]},{"i":"600449001_worlds_top_university_awards_scholarship_to_young_mori_researcher","n":"World’s Top University Awards Scholarship to Young Māori Researcher","o":"600449001","about":"The world’s top university, Massachusetts Institute of Technology (MIT), has awarded Jacqueline Paul (Ngā Puhi, Ngāti Kahungunu ki Heretaunga, Ngāti Tūwharetoa) a full ride scholarship. (This means one that covers all expenses, including tuition, books, fees, room and board) The Unitec lecturer andNgā Wai A Te Tūīresearcher has joined the chosen few accepted to MIT, ranked as the best university in the world alongside institutes such as Harvard, Oxford and Stanford. For more than a decade, MIT has maintained the number one spot on the QS World University Rankings, and the competitive admissions process only accepts 4.1% or 4 out of every 100 applicants. Jackie received the news of her acceptance to MIT just hours after graduating with her Masters at the University of Cambridge.","levels":["Masters","PhD / Doctorate","Undergraduate"],"values":[{"condition":"Academic merit / GPA requirements","value":"$75,000"}],"lengths":[{"condition":"NoCondition","length":"Five Years"}],"opening":"Open all year","closing":"Refer to website","entry":"Apply now to study with us in 2026","url":"https://www.unitec.ac.nz/worlds-top-university-awards-scholarship-to-young-maori-researcher/","eligibility":{"domesticOnly":false,"internationalOnly":false,"ethnicity":["Māori","Indigenous"],"other":"It costs roughly $75,000 – $100,000 USD to attend MIT per academic year, and Jackie’s scholarship package covers five years of full tuition, stipend and health insurance"},"rounds":[]}];
